window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0078", [{"word":"dispersal","ipa_uk":"/dɪˈspɜːsl/","ipa_us":"/dɪˈspɜːrsl/","definition_zh":"散布；扩散；分散；传播","definition_en":"the act or process of spreading things out over a wider area, or the state of being scattered in different directions","core_image":"蒲公英种子被风一吹，从一处散向整片河谷","scene":"秋天，蒲公英的种子被一阵风带离母株，散落到河谷各处。 In autumn, dandelion seeds are carried away from the parent plant by a gust of wind and undergo wide dispersal across the river valley.","sceneCN":"这里 dispersal 是「散布、扩散」（第 2 个义项：生物繁殖体的传播）；句意：秋天，蒲公英种子被一阵风吹离母株，散布到河谷各处。","pos":[{"tag":"n.","zh":"散布；扩散；分散（多作不可数；指一次具体扩散过程时可数）"}],"collocations":[{"phrase":"seed dispersal","zh":"种子传播"},{"phrase":"long-distance dispersal","zh":"长距离扩散"},{"phrase":"wind dispersal","zh":"风力传播"},{"phrase":"dispersal distance","zh":"扩散距离"},{"phrase":"dispersal agent","zh":"传播媒介；扩散媒介"},{"phrase":"dispersal pattern","zh":"分布格局；扩散模式"}],"forms":[{"label":"复数","form":"dispersals"},{"label":"动词（使分散）","form":"disperse"},{"label":"名词（分散状态）","form":"dispersion"},{"label":"形容词（有分散性的）","form":"dispersive"}],"derivatives":[{"word":"disperse","pos":"v.","zh":"分散；驱散；使消散"},{"word":"dispersion","pos":"n.","zh":"分散；色散；离差"},{"word":"dispersive","pos":"adj.","zh":"分散的；色散的"},{"word":"dispersible","pos":"adj.","zh":"可分散的；可溶解分散的"}],"senses":[{"no":"01","title":"Scatter outward from one point","titleCN":"自一点向四周散开","definition":"the process by which things that were gathered in one place move apart and cover a wider area","definitionCN":"原本聚在一处的东西分开移动、覆盖更大范围的过程","example":"The dispersal of the swarm began when the queen left the hive.","exampleCN":"蜂群随着蜂王离巢而开始散开。","why":"Latin dispergere joins dis- 'apart' to spargere 'to strew, scatter'. The prefix does the work of separation, so the noun names the outward breaking-up of a group.","whyCN":"拉丁语 dispergere 把 dis-「分开」与 spargere「撒、铺散」结合；前缀本身承担“分离”的动作，因此这个名词指群体向外散开的过程。"},{"no":"02","title":"Biological seed or spore spread","titleCN":"生物繁殖体的传播","definition":"the movement of seeds, spores, or larvae away from the parent organism to new places","definitionCN":"种子、孢子或幼体离开亲本、到达新地点的过程","example":"Wind dispersal lets maple seeds colonize clearings far from the parent tree.","exampleCN":"风力传播让枫树种子在远离母树的空地上定殖。","why":"Once spargere is applied to living propagules, the 'strewing' becomes sowing: the plant scatters its seeds exactly as a hand scatters grain, and the distance travelled is what the term measures.","whyCN":"当 spargere 用于活体繁殖体时，“撒开”就变成了“播种”：植物像手撒谷粒一样把种子撒出去，而这个词度量的正是种子移动的距离。"},{"no":"03","title":"Population dispersal: individuals leave a group","titleCN":"种群扩散：个体迁出群体","definition":"the movement of individuals away from a crowded or natal population into new areas","definitionCN":"个体离开拥挤的或出生的种群、进入新区域的移动","example":"Dispersal reduces competition because young animals leave the densest ranges.","exampleCN":"扩散能减轻竞争，因为幼兽会离开最密集的活动范围。","why":"The same outward scatter is read as a demographic event: what moves is not grain but individual animals, and the result is a new distribution of the species.","whyCN":"同一种向外散开被读作种群事件：移动的不是谷粒而是动物个体，结果是该物种形成新的分布。"},{"no":"04","title":"Physical or chemical dispersion","titleCN":"物理化学意义上的分散","definition":"the spreading of particles, molecules, or droplets through a medium so that they are no longer clumped","definitionCN":"颗粒、分子或液滴在介质中铺开而不再聚集","example":"Ulasonic stirring produces a fine dispersal of clay particles in water.","exampleCN":"超声搅拌使黏土颗粒在水中形成细微分散。","why":"In the laboratory the Latin image becomes literal: spargere describes particles strewn through a liquid, and the noun names the resulting non-clumped state.","whyCN":"在实验室里，这个拉丁意象变成字面意义：spargere 描述颗粒被撒进液体，名词则指由此得到的非聚集状态。"},{"no":"05","title":"Dispersal of a crowd or gathering","titleCN":"人群的散开","definition":"the breaking up of an assembled crowd, often because it is told or forced to leave","definitionCN":"聚集人群的解散，常因被要求或被强制离开","example":"The dispersal of the crowd took less than ten minutes.","exampleCN":"人群的散开不到十分钟就完成了。","why":"A crowd is a gathering held in one place; dis- pulls it apart in all directions, so the nominal form describes the moment the assembly stops being an assembly.","whyCN":"人群是聚集在一处的集合；dis- 把它向四面八方拉开，因此名词形式描述集会不再成为集会的那个时刻。"},{"no":"06","title":"Spread of information or ideas","titleCN":"信息或观念的传播","definition":"the spreading of knowledge, news, or beliefs to many people or places","definitionCN":"知识、消息或观念传播到许多人或许多地方","example":"Printing enabled the rapid dispersal of scientific ideas across Europe.","exampleCN":"印刷术使科学观念在欧洲迅速传播。","why":"The metaphor extends from physical scattering to information: ideas leave one mind and are strewn among many, and the word keeps the same outward direction.","whyCN":"这个隐喻从物理撒散延伸到信息：观念离开一个头脑、撒布到许多人之间，词义保持同样的向外方向。"},{"no":"07","title":"Decentralization of power or resources","titleCN":"权力或资源的下放","definition":"the distribution of authority, money, or functions away from a single center","definitionCN":"权力、资金或职能从单一中心向外分配","example":"The dispersal of authority to regional offices weakened the capital's control.","exampleCN":"把权力下放到地区办事处削弱了首都的控制。","why":"Here what was held at one center is scattered to several points. The Latin separation is political rather than physical, but the shape of the movement is identical.","whyCN":"这里原本集中在一处的东西被散到若干点。拉丁语中的“分离”是政治性的而非物理性的，但移动的形状完全相同。"},{"no":"08","title":"Forced scattering: police dispersal","titleCN":"强制驱散","definition":"the clearing of a crowd or gathering by authorities, sometimes with force","definitionCN":"当局对人群或集会的清场，有时使用武力","example":"The police ordered the dispersal of the illegal demonstration.","exampleCN":"警方下令驱散这次非法示威。","why":"When an authority does the scattering, the neutral 'spreading out' acquires a coercive edge; dis- is imposed on the crowd from outside rather than happening by itself.","whyCN":"当驱散由当局执行时，中性的“散开”带上了强制色彩；dis- 是从外部强加于人群，而不是人群自行散开。"}],"etymology":{"intro":{"en":"Dispersal is a nineteenth-century noun built on the older verb disperse, which came through French from Latin dispergere. The date is approximate; the underlying PIE root is a reconstruction.","cn":"dispersal 是 19 世纪在较早的动词 disperse 基础上构成的名词；disperse 经由法语来自拉丁语 dispergere。年代为大致估计，最底层原始印欧词根属于重构。"},"items":[{"era":"EARLY 19C.","en":"The noun dispersal is recorded from the 1820s in the sense 'act of dispersing', formed by adding the native suffix -al to the verb disperse.","cn":"名词 dispersal 于 19 世纪 20 年代被记录，义为“分散的行为”，由动词 disperse 加本族后缀 -al 构成。"},{"era":"LATIN","en":"The verb goes back to Latin dispersus, past participle of dispergere 'to scatter, disperse'.","cn":"该动词可追溯到拉丁语 dispersus，即 dispergere「撒开、分散」的过去分词。"},{"era":"LATIN PARTS","en":"dispergere = dis- 'apart, in different directions' + spargere 'to strew, sprinkle, scatter'. The same spargere gives sparse, intersperse and aspersion.","cn":"dispergere = dis-「分开、向不同方向」+ spargere「撒、洒、散布」。同一个 spargere 还产生 sparse、intersperse、aspersion。"},{"era":"PROTO-INDO-EUROPEAN","en":"Spargere is traced to a reconstructed root *sper- 'to strew', also seen in Greek speirein 'to sow' and sperma 'seed'. The reconstruction is conventional rather than directly attested, so the deepest layer is source uncertain.","cn":"spargere 被追溯到重构词根 *sper-「撒播」，同样见于希腊语 speirein「播种」与 sperma「种子」。这一重构是通行做法而非直接证据，故最深层来源不确定。"},{"era":"FRENCH","en":"Old French disperser and its participle gave English the verb in the 14th century; English later coined the noun rather than borrowing a Latin noun.","cn":"古法语 disperser 及其分词在 14 世纪把该动词带入英语；英语后来是自己造出名词，而不是借入拉丁名词。"},{"era":"MODERN ENGLISH","en":"Modern English keeps two nouns: dispersal for the process, especially in biology and planning, and dispersion for physical scattering such as light dispersion.","cn":"现代英语保留两个名词：dispersal 指过程，尤其在生物学与规划领域；dispersion 指物理上的分散，如光的色散。"}]},"similar":{"note":{"en":"The first group separates spelling neighbours, the second compares words of close meaning. Form is checked before meaning.","cn":"第一组区分拼写相近的词，第二组比较意思接近的词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dispersion","ipa":"/dɪˈspɜːʃn/","tag":"same root, physics","definition":"the physical scattering of light or particles; also a statistical spread. It is the Latin-derived sibling of dispersal.","definitionCN":"光或粒子的物理分散；也指统计离差。它是 dispersal 的拉丁式同源名词。"},{"word":"disposal","ipa":"/dɪˈspəʊzl/","tag":"different root","definition":"the act of getting rid of something, from dispose (dis- + ponere 'to place'). It has nothing to do with scattering.","definitionCN":"处理、处置的行为，来自 dispose（dis- + ponere「放置」）。与“撒散”无关。"},{"word":"sparse","ipa":"/spɑːs/","tag":"same root","definition":"thinly spread; not dense. It descends from Latin sparsus, the participle of the same spargere.","definitionCN":"稀疏的；不密集的。它来自拉丁语 sparsus，即同一个 spargere 的分词。"},{"word":"dispersant","ipa":"/dɪˈspɜːsənt/","tag":"derived noun","definition":"a substance that keeps particles apart in a liquid; a product noun from disperse.","definitionCN":"使颗粒在液体中保持分离的物质；由 disperse 构成的产品名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"scattering","ipa":"/ˈskætərɪŋ/","tag":"general","definition":"the action of throwing things in many directions. It is plainer and more physical than dispersal.","definitionCN":"把东西向多方向抛散的动作。比 dispersal 更朴素、更偏物理。"},{"word":"diffusion","ipa":"/dɪˈfjuːʒn/","tag":"gradual spread","definition":"the slow spreading of particles, heat, or ideas through a medium. It stresses gradual mixing rather than an initial scatter.","definitionCN":"粒子、热量或观念在介质中的缓慢铺开。强调逐渐混合，而非最初的散开。"},{"word":"spread","ipa":"/spred/","tag":"everyday","definition":"the act of extending over a wider area. It is the neutral everyday word that dispersal formalizes.","definitionCN":"扩展到更广区域的行为。是 dispersal 所正式化的日常中性词。"},{"word":"distribution","ipa":"/ˌdɪstrɪˈbjuːʃn/","tag":"arrangement","definition":"the way things are placed or shared across an area or group. It names the result, while dispersal names the movement.","definitionCN":"事物在某区域或群体中的放置或分配方式。它指结果，dispersal 指移动过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases, and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"dis- means apart and spargere means to strew: dispersal is literally 'strewing apart'.","cn":"dis- 表示“分开”，spargere 表示“撒”：dispersal 字面就是“撒开”。"},{"en":"Seed dispersal is the standard term in ecology for how plants move their seeds away from the parent.","cn":"seed dispersal 是生态学中表示植物把种子送离母株的标准术语。"},{"en":"Dispersion is the physics cousin: light dispersion through a prism spreads colours apart.","cn":"dispersion 是物理学中的同源词：棱镜中的光色散把颜色分开。"},{"en":"Sparse and intersperse share the same spargere root: sparse is 'scattered thin', intersperse is 'scatter between'.","cn":"sparse 与 intersperse 共享同一个 spargere 词根：sparse 是“撒得稀”，intersperse 是“撒在中间”。"},{"en":"Police dispersal is the coercive branch: the crowd is scattered by order, not by wind.","cn":"police dispersal 是强制分支：人群是被命令驱散的，不是被风吹散的。"}],"abstract":[{"en":"Picture one handful of grain released above a field: the hand opens, the grains separate in the air, and the pattern widens as they fall. That widening is dispersal.","cn":"想象一把谷粒在高处松开：手张开，谷粒在空中分离，落下时分布越来越宽。这个“变宽”就是 dispersal。"},{"en":"The same shape applies to seeds, animals, particles, ideas, and authority: something once held at one point is released to many points.","cn":"同一形状适用于种子、动物、颗粒、观念与权力：曾经集中在一点的东西被释放到许多点。"},{"en":"Dispersal is the movement, distribution is the final map; keeping the two apart prevents circular definitions.","cn":"dispersal 是移动过程，distribution 是最终地图；把两者分开可以避免循环定义。"}]},"examples":[{"en":"The study tracked seed dispersal by attaching radio tags to wind-borne fruits.","cn":"这项研究通过给风力传播的果实装上无线电标签来追踪种子扩散。"},{"en":"Habitat loss blocks dispersal and leaves populations isolated in small patches.","cn":"栖息地丧失阻断扩散，使种群被隔离在小块斑块中。"},{"en":"The dispersal of the protest began only after the mayor's announcement.","cn":"示威的驱散是在市长宣布之后才开始的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地斯破手”——地上一撒，破开的手一扬，种子向四方散开 → dispersal 分散、传播","word":"dispersal"},"root":"拉丁语 dispergere「向不同方向撒开」，由 dis-（分开）+ spargere（撒、散布）构成。","sensesIntro":{"en":"Eight senses of dispersal, all one gesture: what was gathered at a point is released and widens outward, whether it is seeds, animals, particles, a crowd, news, or authority.","cn":"dispersal 的八个义项都源于同一个动作：原本集中在一点的东西被释放并向四周变宽——无论那是种子、动物、颗粒、人群、消息还是权力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand opens above a field and the grains separate as they fall.","cn":"核心意象：一只手在田野上方张开，谷粒落下时彼此分开。"},"chain":["GATHERED","RELEASED","SEPARATED","WIDENING","NEW PLACES","NEW PATTERN"],"branches":[{"senses":"S1 · S5","en":"SIMPLE SCATTER: objects or a crowd break apart in all directions.","cn":"简单散开：物体或人群向四面八方分开。"},{"senses":"S2 · S3","en":"LIFE: seeds and animals leave the parent or natal group and reach new habitat.","cn":"生命：种子和动物离开亲本或出生群，抵达新栖息地。"},{"senses":"S4","en":"MATTER: particles are strewn through a medium and stop clumping.","cn":"物质：颗粒被撒入介质，不再聚集。"},{"senses":"S6 · S7","en":"ABSTRACT FLOW: ideas and authority move from one center to many points.","cn":"抽象流动：观念与权力从单一中心流向多个点。"},{"senses":"S8","en":"FORCE: an authority imposes the scatter on a crowd from outside.","cn":"强制：当局从外部把“散开”强加于人群。"}]},"affixes":{"intro":{"en":"Dispersal is the verb disperse plus the noun suffix -al. Inside the verb, dis- is the only living prefix; spargere is a Latin verb stem, not a productive English element.","cn":"dispersal 是动词 disperse 加名词后缀 -al。动词内部只有 dis- 是仍可分析的活前缀；spargere 是拉丁动词词干，不是能产的英语成分。"},"latinIntro":{"en":"Latin spargere 'to scatter' supplies sparse, aspersion and intersperse beside the dispergere family; the modern Greek seed words sperm and spermat- descend from a related but separate speirein.","cn":"拉丁语 spargere「撒」除了 dispergere 一族，还提供 sparse、aspersion、intersperse；现代希腊语系的 sperm、spermat- 则来自相关但另成一线的 speirein。"},"items":[{"word":"dispersal","structure":"disperse + -al (noun of action)","meaning":"the act of dispersing","meaningCN":"分散的行为（-al 构成行为名词）","example":"Seed dispersal is measured in metres.","exampleCN":"种子扩散以米为单位测量。"},{"word":"disperse","structure":"dis- (apart) + spargere (to scatter)","meaning":"to scatter in different directions","meaningCN":"向不同方向散开（dis- 分开 + spargere 撒）","example":"The wind dispersed the smoke.","exampleCN":"风把烟吹散了。"},{"word":"dispersion","structure":"dispersus + -ion (noun of result)","meaning":"the state of being scattered; physical dispersion","meaningCN":"被分散的状态；物理色散（-ion 构成结果名词）","example":"Dispersion of white light produces a spectrum.","exampleCN":"白光的色散产生光谱。"},{"word":"dispersive","structure":"disperse + -ive (adjective)","meaning":"tending to scatter","meaningCN":"有分散倾向的（-ive 构成形容词）","example":"Sandstone is a dispersive medium for water.","exampleCN":"砂岩对水是一种分散性介质。"},{"word":"dispersible","structure":"disperse + -ible (capable of)","meaning":"able to be dispersed in a medium","meaningCN":"可分散于介质中的（-ible 表示“能够”）","example":"The powder is dispersible in cold water.","exampleCN":"这种粉末可分散于冷水中。"},{"word":"sparse","structure":"sparsus, participle of spargere","meaning":"scattered thinly; not dense","meaningCN":"稀疏的；不密集的","example":"Sparse grass covers the dry slope.","exampleCN":"稀疏的草覆盖着干旱的坡地。"},{"word":"intersperse","structure":"inter- (between) + spargere (to scatter)","meaning":"to scatter among other things","meaningCN":"散布于其他事物之间（inter- 之间 + 撒）","example":"Wildflowers were interspersed among the wheat.","exampleCN":"野花散布在麦田之间。"},{"word":"aspersion","structure":"ad- (to) + spargere (to sprinkle) + -ion","meaning":"a sprinkling, hence a slanderous remark","meaningCN":"洒水，引申为诽谤（-ion 名词）","example":"He cast aspersions on the report.","exampleCN":"他对这份报告加以中伤。"}],"latinEntries":[{"word":"spargere","structure":"spargere (verb, third conjugation)","meaning":"to strew, scatter, sprinkle","meaningCN":"撒；散布；洒"},{"word":"dispergere","structure":"dis- + spargere (verb)","meaning":"to scatter apart, disperse","meaningCN":"撒开；分散"},{"word":"dispersus","structure":"past participle of dispergere","meaning":"scattered, dispersed","meaningCN":"被撒开的；分散的"},{"word":"sparsus","structure":"past participle of spargere","meaning":"strewn, scattered","meaningCN":"被撒布的；稀疏的"}]}},{"word":"disperse","ipa_uk":"/dɪˈspɜːs/","ipa_us":"/dɪˈspɜːrs/","definition_zh":"分散；驱散；散布；使消散","definition_en":"to scatter in different directions, or to cause a group, substance, or body of information to spread out and stop being together","core_image":"手握一把沙，一松手沙粒向四周飞散","scene":"风从山口灌进来，把堆积的火山灰吹向四面八方。 Wind poured through the pass and dispersed the piled volcanic ash in every direction.","sceneCN":"这里 disperse 是「使消散、吹散」（第 4 个义项：物质在介质中散开）；句意：风从山口灌进来，把堆积的火山灰向四面八方吹散。","pos":[{"tag":"vt.","zh":"使分散；驱散；使消散"},{"tag":"vi.","zh":"散开；消散；四散"}],"collocations":[{"phrase":"disperse a crowd","zh":"驱散人群"},{"phrase":"disperse seeds","zh":"传播种子"},{"phrase":"disperse pollutants","zh":"使污染物扩散"},{"phrase":"disperse the fog","zh":"驱散雾气"},{"phrase":"disperse over a wide area","zh":"散布在广阔区域"},{"phrase":"be dispersed throughout","zh":"分散于……各处"}],"forms":[{"label":"三单（he/she/it）","form":"disperses"},{"label":"过去式（已经发生）","form":"dispersed"},{"label":"过去分词（完成／被动）","form":"dispersed"},{"label":"现在分词（进行体）","form":"dispersing"}],"derivatives":[{"word":"dispersal","pos":"n.","zh":"散布；扩散；驱散"},{"word":"dispersion","pos":"n.","zh":"分散；色散；离差"},{"word":"dispersive","pos":"adj.","zh":"分散的；色散的"},{"word":"dispersant","pos":"n.","zh":"分散剂"}],"senses":[{"no":"01","title":"Scatter people or things in all directions","titleCN":"使人或物向四周散开","definition":"to make a group of people or objects separate and move in different directions","definitionCN":"使一群人或物分开、朝不同方向移动","example":"The gust dispersed the leaves that had gathered in the corner.","exampleCN":"一阵风把聚在角落的叶子吹散了。","why":"Latin dispergere = dis- 'apart' + spargere 'to scatter'. The verb is the act itself, so its basic sense is simply to impose separation on a collection.","whyCN":"拉丁语 dispergere = dis-「分开」+ spargere「撒」。动词就是动作本身，因此基本义就是把“分开”施加于一个集合。"},{"no":"02","title":"Break up a crowd or assembly","titleCN":"解散人群或集会","definition":"to cause a crowd, meeting, or demonstration to break up and leave","definitionCN":"使人群、会议或示威解散离开","example":"Police dispersed the onlookers before the demolition began.","exampleCN":"拆除开始前，警察驱散了围观者。","why":"The same separation is applied to an assembly: the crowd is no longer one body but many separate walkers, and the verb names the authority or force that produces that state.","whyCN":"同样的分离作用于集会：人群不再是一个整体，而是许多分开的行人；动词则指造成这一状态的权威或力量。"},{"no":"03","title":"Spread seeds or organisms","titleCN":"传播种子或生物","definition":"to carry seeds, spores, or young organisms away from their source to new places","definitionCN":"把种子、孢子或幼体从来源地带到新地点","example":"Birds disperse the berries' seeds after eating the fruit.","exampleCN":"鸟类吃下果实后把浆果种子传播出去。","why":"Once the object is a living propagule, scattering becomes transport: the agent that moves the seed is doing the dispersing, and the seed gains a new range.","whyCN":"当对象是活体繁殖体时，撒散变成运输：搬运种子的媒介在执行 disperse，种子由此获得新的分布范围。"},{"no":"04","title":"Diffuse a substance through a medium","titleCN":"使物质在介质中扩散","definition":"to spread particles, droplets, gases, or pollutants through air, water, or another medium","definitionCN":"使颗粒、液滴、气体或污染物在空气、水或其他介质中铺开","example":"The current dispersed the oil slick along the shoreline.","exampleCN":"洋流把油膜沿着海岸线扩散开来。","why":"Spargere literally means to sprinkle; in a fluid the sprinkling becomes dilution, and the verb describes particles losing their concentration.","whyCN":"spargere 字面就是“洒”；在流体中，洒布变成稀释，动词描述颗粒失去原有的浓度。"},{"no":"05","title":"Dispel fog, smoke, or a smell","titleCN":"驱散雾、烟或气味","definition":"to drive away mist, smoke, or an odour so that it is no longer concentrated","definitionCN":"把雾、烟或气味驱开，使其不再聚集","example":"Sunrise dispersed the fog that had closed the harbour.","exampleCN":"日出驱散了封锁港口的雾。","why":"Here the scattered thing is intangible and temporary. The wind applies dis- to vapour, and the result is not transport but disappearance from view.","whyCN":"这里被散开的东西是无形的、短暂的。风把 dis- 作用于水汽，结果不是运输，而是从视野中消失。"},{"no":"06","title":"Circulate information or ideas","titleCN":"传播信息或观念","definition":"to spread news, knowledge, or beliefs among many people","definitionCN":"把消息、知识或信念传播给许多人","example":"The invention of paper dispersed technical knowledge far beyond the monasteries.","exampleCN":"造纸术使技术知识传播到修道院之外的广大地区。","why":"Ideas behave like seeds in this metaphor: they leave one holder and are strewn among many, so the same verb covers both physical and intellectual propagation.","whyCN":"在这个隐喻里，观念像种子：它们离开一个持有者、撒布到许多人之间，因此同一个动词既覆盖物理传播，也覆盖思想传播。"},{"no":"07","title":"Distribute power or population","titleCN":"分散权力或人口","definition":"to move authority, functions, or people away from a single centre","definitionCN":"使权力、职能或人口离开单一中心","example":"The government dispersed administrative offices to the provinces.","exampleCN":"政府把行政机构分散到各省。","why":"The Latin separation is applied to organization: what was concentrated at a centre is deliberately scattered to several sites, producing a decentralized pattern.","whyCN":"拉丁语的“分离”被用于组织：原本集中在中心的东西被有意散到若干地点，形成去中心化的格局。"},{"no":"08","title":"Disperse doubts or fears","titleCN":"消除疑虑或恐惧","definition":"in figurative use, to cause a feeling or doubt to fade away among the people who hold it","definitionCN":"用于比喻，指使某种情绪或疑虑在持有者之间消散","example":"The clear data dispersed the doubts that had delayed the project.","exampleCN":"清晰的数据消除了拖延项目的疑虑。","why":"The metaphor treats an emotion as a cloud: it occupies one space in many minds, and dis- scatters it until no single concentration remains.","whyCN":"这个比喻把情绪当作云：它占据许多头脑中的一片空间，dis- 把它打散，直到不再有任何集中的残留。"}],"etymology":{"intro":{"en":"Disperse entered English in the fourteenth century through Old French from Latin dispergere. The PIE root behind spargere is reconstructed, not attested.","cn":"disperse 于 14 世纪经由古法语从拉丁语 dispergere 进入英语。spargere 背后的原始印欧词根是重构，而非直接记录。"},"items":[{"era":"14C.","en":"English disperse is recorded in the late fourteenth century with the sense 'to scatter, spread abroad', borrowed through Old French disperser.","cn":"英语 disperse 于 14 世纪晚期被记录，义为“使散开、传布”，经由古法语 disperser 借入。"},{"era":"LATIN","en":"Latin dispergere 'to scatter, disperse' is the source; its past participle dispersus also gave the English adjective and noun family.","cn":"来源是拉丁语 dispergere「撒开、分散」；其过去分词 dispersus 还产生英语的形容词与名词族。"},{"era":"LATIN PARTS","en":"dis- 'apart, asunder' + spargere 'to strew, sprinkle'. The prefix marks separation; the verb supplies the image of scattering grain or liquid.","cn":"dis-「分开、散开」+ spargere「撒、洒」。前缀标记分离，动词提供撒谷粒或洒液体的意象。"},{"era":"PROTO-INDO-EUROPEAN","en":"Spargere is conventionally referred to *sper- 'to strew', with Greek speirein 'to sow' as a cognate. Because this is a reconstructed root, the deepest etymology is source uncertain.","cn":"spargere 通常被归入 *sper-「撒播」，并以希腊语 speirein「播种」为同源词。由于这是重构词根，最深层词源来源不确定。"},{"era":"16C.–18C.","en":"The verb widened from physical scattering to the breaking-up of crowds, the diffusion of gases, and the distribution of offices; all these uses keep the same outward movement.","cn":"16 至 18 世纪，该动词从物理撒散扩展到人群解散、气体扩散与机构分布；这些用法都保持同样的向外移动。"},{"era":"MODERN ENGLISH","en":"Modern English pairs disperse with the noun dispersal for processes and dispersion for physical or statistical spreading; the verb itself remains neutral about force.","cn":"现代英语中，disperse 与名词 dispersal（过程）和 dispersion（物理或统计分散）配套；动词本身对是否使用武力保持中性。"}]},"similar":{"note":{"en":"The first group separates look-alikes and same-root relatives; the second compares verbs of similar meaning.","cn":"第一组区分形近词与同根词；第二组比较意义相近的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dispose","ipa":"/dɪˈspəʊz/","tag":"different root","definition":"to arrange or get rid of something, from dis- + ponere 'to place'. The -pose ending marks placement, not scattering.","definitionCN":"安排或处理掉某物，来自 dis- + ponere「放置」。-pose 词尾表示“放置”，不是“撒散”。"},{"word":"dispense","ipa":"/dɪˈspens/","tag":"different root","definition":"to hand out or provide, from dis- + pensare 'to weigh out'. It is about measured giving, not scattering.","definitionCN":"分发或提供，来自 dis- + pensare「称量」。它关于按量给出，而非散开。"},{"word":"dispersion","ipa":"/dɪˈspɜːʃn/","tag":"same root","definition":"the noun of state or result; in optics, the separation of light into colours.","definitionCN":"表状态或结果的名词；光学中指光分成不同颜色。"},{"word":"sparse","ipa":"/spɑːs/","tag":"same root","definition":"thinly scattered; from sparsus, the participle of the same spargere.","definitionCN":"稀疏散布的；来自同一个 spargere 的分词 sparsus。"}]},{"heading":"NEAR MEANING","entries":[{"word":"scatter","ipa":"/ˈskætə/","tag":"general physical","definition":"to throw or drop things over a wide area. It is the plain everyday verb behind disperse.","definitionCN":"把东西抛撒到广大区域。是 disperse 背后朴素的日常动词。"},{"word":"spread","ipa":"/spred/","tag":"wide and neutral","definition":"to extend over a larger area or among more people. It does not imply breaking a group apart.","definitionCN":"扩展到更大范围或更多人之中。不暗示把群体打散。"},{"word":"dispel","ipa":"/dɪˈspel/","tag":"fog, fears","definition":"to drive away a feeling or mist completely. It comes from pellere 'to drive', and is narrower than disperse.","definitionCN":"彻底驱走某种感觉或雾气。来自 pellere「驱赶」，比 disperse 范围更窄。"},{"word":"distribute","ipa":"/dɪˈstrɪbjuːt/","tag":"allotment","definition":"to give out or place things according to a plan. It stresses allocation rather than random scattering.","definitionCN":"按计划分发或布置。强调分配，而非随机散开。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real prefixes, real phrases, and real relatives.","cn":"正常联想：真实前缀、真实短语和真实同族词。"},"normal":[{"en":"dis- = apart; spargere = scatter. Disperse is 'scatter apart' in two pieces.","cn":"dis- = 分开；spargere = 撒。disperse 就是“撒开”，两块拼起来。"},{"en":"The noun pair is useful: dispersal for ecological or planning processes, dispersion for optics and statistics.","cn":"名词配对很有用：dispersal 用于生态或规划过程，dispersion 用于光学与统计。"},{"en":"Disperse a crowd is the standard police and news phrase for breaking up an assembly.","cn":"disperse a crowd 是警务与新闻中表示解散集会的标准搭配。"},{"en":"Dispel is the near twin for fog and fears, but it comes from pellere 'drive', not spargere 'scatter'.","cn":"dispel 是雾与恐惧的近义双胞胎，但它来自 pellere「驱赶」，不是 spargere「撒」。"},{"en":"Sparse is the adjective of the same root: what has been scattered thinly looks sparse.","cn":"sparse 是同根形容词：撒得很稀的东西看起来就 sparse。"}],"abstract":[{"en":"Picture a clenched fist of sand: opening the fingers does not move the hand, yet the sand's pattern changes completely. Disperse is that opening.","cn":"想象一只握紧沙子的拳头：手指张开时手没移动，沙的分布却彻底改变。disperse 就是那个“张开”。"},{"en":"The verb always has a source and a widening: something held at one point is made to occupy many points.","cn":"这个动词总有“源点”与“变宽”：原本握在一点的东西被迫占据许多点。"},{"en":"Force is optional in the word itself; context decides whether people leave freely or are driven apart.","cn":"这个词本身不包含武力；语境决定人们是自行离开还是被驱开。"}]},"examples":[{"en":"The wind dispersed the spores before they could settle on the log.","cn":"风在孢子落定到木头上之前就把它们吹散了。"},{"en":"Officers dispersed the crowd after repeated warnings.","cn":"多次警告后，警员驱散了人群。"},{"en":"Newspapers helped disperse the idea that cities could be planned.","cn":"报纸帮助传播了“城市可以被规划”这一观念。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“第四泼死”——第四泼水泼出去，落地就散得没影 → disperse 分散、驱散","word":"disperse"},"root":"拉丁语 dispergere「撒开」，dis-（分开）+ spargere（撒、洒）；同根词有 sparse、intersperse、aspersion。","sensesIntro":{"en":"Eight senses of disperse: one outward movement of separation, applied to objects, crowds, seeds, fluids, fog, ideas, institutions, and feelings.","cn":"disperse 的八个义项：同一个“向外分开”的动作，施于物体、人群、种子、流体、雾、观念、机构与情绪。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fist opens and the sand inside flies apart.","cn":"核心意象：拳头张开，里面的沙向四面飞散。"},"chain":["HELD TOGETHER","OPENED","SEPARATED","MOVING OUTWARD","LOWER DENSITY","NEW ARRANGEMENT"],"branches":[{"senses":"S1 · S5","en":"PHYSICAL SCATTER: objects, mist, or smoke lose their clump and spread.","cn":"物理散开：物体、雾或烟失去聚集状态并铺开。"},{"senses":"S2","en":"SOCIAL BREAK-UP: an assembly stops being one body and becomes separate people.","cn":"社会解散：集会不再是一个整体，而成为分开的个人。"},{"senses":"S3","en":"BIOLOGICAL TRANSPORT: seeds and young organisms reach new places.","cn":"生物运输：种子与幼体抵达新地点。"},{"senses":"S4","en":"MATERIAL DIFFUSION: particles lose concentration inside a medium.","cn":"物质扩散：颗粒在介质中失去浓度。"},{"senses":"S6 · S7 · S8","en":"ABSTRACT SPREAD: ideas, offices, and emotions are distributed until no single centre holds them.","cn":"抽象扩散：观念、机构与情绪被分散，直到没有单一中心持有它们。"}]},"affixes":{"intro":{"en":"Disperse is a Latin verb taken into English whole: dis- is the only analysable prefix, and spargere is a bound Latin stem that English never uses alone.","cn":"disperse 是整体借入英语的拉丁动词：只有 dis- 可分析为前缀，spargere 是英语从不单独使用的黏着拉丁词干。"},"latinIntro":{"en":"Spargere also yields sparse, intersperse, and aspersion; dispergere adds dispersus, dispersio, and the English family dispersal, dispersion, dispersive.","cn":"spargere 还产生 sparse、intersperse、aspersion；dispergere 则带来 dispersus、dispersio，以及英语的 dispersal、dispersion、dispersive 一族。"},"items":[{"word":"disperse","structure":"dis- (apart) + spargere (to scatter)","meaning":"to scatter apart","meaningCN":"使散开（dis- 分开 + spargere 撒）","example":"The wind dispersed the ash.","exampleCN":"风把火山灰吹散了。"},{"word":"dispersed","structure":"disperse + -ed (past participle)","meaning":"scattered; spread out","meaningCN":"分散的；散开的（-ed 分词作形容词）","example":"The dispersed population lives in small villages.","exampleCN":"分散的人口住在小村庄里。"},{"word":"dispersing","structure":"disperse + -ing (present participle)","meaning":"the act of scattering, or tending to scatter","meaningCN":"散开的；起分散作用的（-ing 分词）","example":"Dispersing agents keep the paint smooth.","exampleCN":"分散剂使涂料保持均匀。"},{"word":"dispersal","structure":"disperse + -al (noun)","meaning":"the process of scattering","meaningCN":"散布的过程（-al 名词）","example":"Seed dispersal depends on wind.","exampleCN":"种子传播依赖风。"},{"word":"dispersion","structure":"dispersus + -ion (noun)","meaning":"scattered state; optical separation","meaningCN":"分散状态；光学色散（-ion 名词）","example":"The prism shows dispersion of light.","exampleCN":"棱镜显示出光的色散。"},{"word":"dispersive","structure":"disperse + -ive (adjective)","meaning":"causing or showing dispersion","meaningCN":"引起或表现分散的（-ive 形容词）","example":"A dispersive lens separates colours.","exampleCN":"色散透镜把颜色分开。"},{"word":"sparse","structure":"sparsus (participle of spargere)","meaning":"scattered thinly","meaningCN":"稀疏的","example":"Vegetation is sparse on the salt flat.","exampleCN":"盐滩上的植被很稀疏。"},{"word":"intersperse","structure":"inter- (between) + spargere","meaning":"to scatter between other things","meaningCN":"散布于其间","example":"Bushes were interspersed with grass.","exampleCN":"灌木散布在草地之间。"},{"word":"aspersion","structure":"ad- (to) + spargere + -ion","meaning":"a sprinkling; a damaging remark","meaningCN":"洒布；诽谤","example":"The article cast aspersions on his work.","exampleCN":"那篇文章中伤了他的工作。"}],"latinEntries":[{"word":"spargere","structure":"spargere (third conjugation)","meaning":"to strew, scatter, sprinkle","meaningCN":"撒；散布；洒"},{"word":"dispergere","structure":"dis- + spargere","meaning":"to scatter apart","meaningCN":"使散开；分散"},{"word":"dispersus","structure":"past participle of dispergere","meaning":"scattered","meaningCN":"被散开的"},{"word":"sparsus","structure":"past participle of spargere","meaning":"strewn; sparse","meaningCN":"被撒布的；稀疏的"}]}},{"word":"geographic distribution","ipa_uk":"/ˌdʒiːəˈɡræfɪk ˌdɪstrɪˈbjuːʃn/","ipa_us":"/ˌdʒiːəˈɡræfɪk ˌdɪstrɪˈbjuːʃn/","definition_zh":"地理分布；地理分布格局","definition_en":"the way a species, population, language, resource, or other phenomenon is spread across the surface of the earth","core_image":"一张世界地图上用不同深浅标出的物种分布斑块","scene":"研究者把这种候鸟的繁殖地、迁徙路线与越冬地叠加到一张地图上，得到它的地理分布图。 Researchers overlaid the bird's breeding grounds, migration routes, and wintering sites on one map to obtain its geographic distribution.","sceneCN":"这里 geographic distribution 是「地理分布」（第 1 个义项：物种在地表占据的范围）；句意：研究者把这种候鸟的繁殖地、迁徙路线与越冬地叠加到一张地图上，得到它的地理分布。","pos":[{"tag":"n.","zh":"地理分布；地理分布格局（可数，复数为 geographic distributions）"}],"collocations":[{"phrase":"geographic distribution of a species","zh":"物种的地理分布"},{"phrase":"broad geographic distribution","zh":"广泛的地理分布"},{"phrase":"geographic distribution pattern","zh":"地理分布格局"},{"phrase":"map the geographic distribution","zh":"绘制地理分布图"},{"phrase":"geographic distribution range","zh":"地理分布范围"},{"phrase":"uneven geographic distribution","zh":"不均衡的地理分布"}],"forms":[{"label":"复数","form":"geographic distributions"},{"label":"同义变体（英式拼写）","form":"geographical distribution"},{"label":"相关名词（地理）","form":"geography"},{"label":"相关名词（分布）","form":"distribution"}],"derivatives":[{"word":"geography","pos":"n.","zh":"地理学；地理"},{"word":"geographic","pos":"adj.","zh":"地理的；地理学的"},{"word":"geographical","pos":"adj.","zh":"地理的（英式常用变体）"},{"word":"distribute","pos":"v.","zh":"分布；分配；分发"}],"senses":[{"no":"01","title":"Range occupied by a species","titleCN":"物种占据的地理范围","definition":"the area over which a species or population is naturally found","definitionCN":"某一物种或种群自然出现的地域范围","example":"The geographic distribution of the orchid stops at the first frost line.","exampleCN":"这种兰花的地理分布到第一条霜线为止。","why":"Geo- means earth and distribution means being allotted out. Together they name the map-shaped answer to the question 'where does this organism occur?'","whyCN":"geo- 意为“地球”，distribution 意为“被分配开”。合起来就是“这种生物出现在哪里”这一问题的地图式答案。"},{"no":"02","title":"Pattern rather than mere range","titleCN":"分布格局而非仅有范围","definition":"the spatial pattern in which members of a group are arranged, including gaps, clusters, and borders","definitionCN":"群体成员在空间中的排列方式，包括空白、聚集与边界","example":"The species shows a patchy geographic distribution along the coast.","exampleCN":"该物种沿海岸呈斑块状地理分布。","why":"Distribution adds the idea of allotment to space: not only where the border lies, but how presence is divided into patches, corridors, and empty zones.","whyCN":"distribution 把“分配”带入空间：不只是边界在哪里，还包括“有”如何被分成斑块、走廊与空白区。"},{"no":"03","title":"Distribution of a human population","titleCN":"人口的地理分布","definition":"the arrangement of human populations across regions, often measured by density","definitionCN":"人口在各区域的排列，常用密度衡量","example":"The country's geographic distribution of population is dominated by two coastal belts.","exampleCN":"该国人口的地理分布以两条沿海带为主。","why":"Here the items distributed are people. The phrase keeps the map frame but the variable is density, so the same term serves demography as well as ecology.","whyCN":"这里被分布的对象是人。短语保持地图框架，但变量是密度，因此同一术语既服务人口学也服务生态学。"},{"no":"04","title":"Distribution of resources","titleCN":"资源的地理分布","definition":"the way minerals, water, fertile land, or energy sources are located across a territory","definitionCN":"矿产、水、肥沃土地或能源在一国领土上的位置分布","example":"The geographic distribution of lithium shapes national energy policy.","exampleCN":"锂矿的地理分布塑造了国家能源政策。","why":"Resources are 'allotted' by geology rather than by choice, so the phrase describes an uneven map that people must adapt to rather than design.","whyCN":"资源是由地质而非人力“分配”的，因此该短语描述一张人必须适应、而非能够设计的不均衡地图。"},{"no":"05","title":"Distribution of a disease","titleCN":"疾病的地理分布","definition":"the pattern of where cases of a disease occur, often used to find environmental causes","definitionCN":"疾病病例出现地点的格局，常用于寻找环境成因","example":"The geographic distribution of the fever pointed to a mosquito-borne cause.","exampleCN":"这种热病的地理分布指向蚊媒病因。","why":"Epidemiology borrows the map: cases are plotted as points, and the shape of their scatter becomes evidence about transmission and environment.","whyCN":"流行病学借用了这张地图：病例被标为点，其散布形状成为关于传播与环境的证据。"},{"no":"06","title":"Distribution of languages or cultures","titleCN":"语言或文化的地理分布","definition":"the areas in which a language, dialect, or cultural practice is used","definitionCN":"某种语言、方言或文化习俗被使用的区域","example":"The geographic distribution of the dialect follows old river trade routes.","exampleCN":"该方言的地理分布沿古老的河流贸易路线展开。","why":"Language is treated as a population with a range; its 'distribution' is the map of speakers, and borders often reflect historical movement rather than nature.","whyCN":"语言被当作具有分布范围的种群；其“分布”是使用者的地图，边界往往反映历史迁移而非自然界线。"},{"no":"07","title":"The mapped result itself","titleCN":"作为成果的分布图","definition":"a map or dataset that shows where something occurs, used as a research product","definitionCN":"显示某事物出现位置的地图或数据集，作为研究成果","example":"The atlas contains a geographic distribution for each of the 300 species.","exampleCN":"这本图集为 300 个物种各提供一幅地理分布图。","why":"By metonymy the phrase shifts from the fact to its representation: the distribution is what the dots on the map show, not the landscape itself.","whyCN":"通过转喻，短语从事实转向其再现：所谓 distribution 就是地图上的点所显示的内容，而不是景观本身。"},{"no":"08","title":"The study of spatial ranges","titleCN":"对空间分布的研究领域","definition":"the subfield or analytical question concerned with where organisms or phenomena occur and why","definitionCN":"关注生物或现象出现在何处及其原因的子领域或分析问题","example":"Biogeography treats geographic distribution as its central problem.","exampleCN":"生物地理学把地理分布作为核心问题。","why":"When used as a topic name, the phrase names a question rather than an object: the research agenda of explaining why ranges have the shapes they do.","whyCN":"作为课题名称时，该短语指一个问题而非一个对象：解释分布范围为何呈现这些形状的研究议程。"}],"etymology":{"intro":{"en":"The phrase is a modern compound of Greek geo- 'earth', Greek -graphia 'writing', and Latin distribuere 'to allot'. It is not an inherited unit but an English scientific coinage.","cn":"这个短语是希腊语 geo-「大地」、希腊语 -graphia「书写」与拉丁语 distribuere「分配」组合成的现代词组；它不是承继而来的单位，而是英语科学造词。"},"items":[{"era":"GREEK","en":"geō- comes from gē 'earth, land'; the related geōdēs meant 'earthlike'. English uses geo- freely in scientific compounds.","cn":"geō- 来自 gē「大地、土地」；相关的 geōdēs 意为“像大地的”。英语在科学复合词中自由使用 geo-。"},{"era":"GREEK","en":"-graphic comes from graphein 'to write, draw', so geographic is 'earth-writing' — the drawing of the earth on a surface.","cn":"-graphic 来自 graphein「写、画」，因此 geographic 就是“书写大地”——把大地画在平面上。"},{"era":"LATIN","en":"distribution comes from distribuere 'to deal out, allot', from dis- 'apart' + tribuere 'to assign, allot'. The noun distributio is the act of dividing out.","cn":"distribution 来自 distribuere「分发、分配」，由 dis-「分开」+ tribuere「指派、分配」构成；名词 distributio 指分派的行为。"},{"era":"17C.–19C.","en":"Geographic entered English in the 17th century; distribution was already an English noun. The collocation became standard with the growth of biogeography in the 19th century.","cn":"geographic 于 17 世纪进入英语，distribution 当时已是英语名词；随着 19 世纪生物地理学的发展，这一搭配成为标准术语。"},{"era":"MODERN ENGLISH","en":"Modern usage prefers geographic in American English and geographical in British English; both patterns appear in academic writing, and the phrase behaves as a countable noun.","cn":"现代用法中，美式英语多用 geographic，英式英语多用 geographical；两种形式都见于学术写作，该短语作可数名词使用。"}]},"similar":{"note":{"en":"The first group separates terms that look alike, the second compares related spatial terms.","cn":"第一组区分形近术语，第二组比较相关的空间术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geographical distribution","ipa":"/ˌdʒiːəˈɡræfɪkl ˌdɪstrɪˈbjuːʃn/","tag":"spelling variant","definition":"the British-preferred variant of the same phrase; the meaning is identical.","definitionCN":"同一短语的英式优先拼写变体，意义完全相同。"},{"word":"geologic distribution","ipa":"/ˌdʒiːəˈlɒdʒɪk ˌdɪstrɪˈbjuːʃn/","tag":"different prefix","definition":"the arrangement of rocks or strata, not of organisms; geo- is shared but -logic differs.","definitionCN":"岩石或地层的排列，而非生物的分布；共享 geo- 但 -logic 不同。"},{"word":"spatial distribution","ipa":"/ˈspeɪʃl ˌdɪstrɪˈbjuːʃn/","tag":"broader","definition":"distribution in space at any scale, including indoors or in a cell; geographic specifies the earth's surface.","definitionCN":"任何尺度上的空间分布，包括室内或细胞内；geographic 特指地表。"},{"word":"population distribution","ipa":"/ˌpɒpjuˈleɪʃn ˌdɪstrɪˈbjuːʃn/","tag":"narrower","definition":"the arrangement of people or organisms, one common type of geographic distribution.","definitionCN":"人或生物的排列，是地理分布的一种常见类型。"}]},{"heading":"NEAR MEANING","entries":[{"word":"range","ipa":"/reɪndʒ/","tag":"species","definition":"the area within which a species occurs. It names the outer limit, while distribution includes internal pattern.","definitionCN":"物种出现的区域。它指外围界线，而 distribution 还包括内部格局。"},{"word":"habitat","ipa":"/ˈhæbɪtæt/","tag":"place type","definition":"the kind of place an organism lives in, not where that kind of place lies on the map.","definitionCN":"生物栖居的场所类型，而不是这类场所在图上的位置。"},{"word":"biogeography","ipa":"/ˌbaɪəʊdʒiˈɒɡrəfi/","tag":"discipline","definition":"the study of the geographic distribution of organisms; the phrase names its object, the discipline names the field.","definitionCN":"研究生物地理分布的学科；短语指其对象，学科名指该领域。"},{"word":"spread","ipa":"/spred/","tag":"process","definition":"the movement that produces a distribution; the result is the map, the process is the spread.","definitionCN":"产生分布的移动过程；结果是地图，过程是 spread。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek and Latin parts, plus standard collocations from ecology and demography.","cn":"正常联想：真实的希腊语与拉丁语成分，加上生态学与人口学的标准搭配。"},"normal":[{"en":"geo- = earth, -graphic = drawing: geographic is 'drawing the earth'.","cn":"geo- = 大地，-graphic = 绘制：geographic 就是“绘制大地”。"},{"en":"distribution from distribuere 'allot apart' supplies the 'how it is divided' half of the phrase.","cn":"distribution 来自 distribuere「分开分配」，提供短语中“如何被分割”的那一半。"},{"en":"Biogeography is the discipline that studies geographic distribution; the map is the object, the field is the study.","cn":"biogeography 是研究地理分布的学科；地图是对象，学科名是研究领域。"},{"en":"Range is the outer limit, distribution is the whole pattern of patches and gaps.","cn":"range 是外围界线，distribution 是斑块与空白构成的整体格局。"},{"en":"Population distribution, disease distribution, and resource distribution all reuse the same map frame.","cn":"人口分布、疾病分布、资源分布都复用同一张地图框架。"}],"abstract":[{"en":"Imagine a sheet of paper with pins: the pins are occurrences, their clustering is the pattern, and the paper is the earth's surface.","cn":"想象一张插满图钉的纸：图钉是出现点，它们的聚散是格局，纸就是地表。"},{"en":"The phrase is a marriage of two gestures: drawing the earth, and dividing something out across it.","cn":"这个短语是两种动作的结合：把大地画出来，以及把某物分派到大地各处。"},{"en":"A distribution answers 'where' and 'how evenly'; a range answers only 'how far'.","cn":"分布回答“在哪里”和“是否均匀”；范围只回答“到多远”。"}]},"examples":[{"en":"Climate change is shifting the geographic distribution of many tree species.","cn":"气候变化正在改变许多树种的地理分布。"},{"en":"The report mapped the geographic distribution of untreated wells across the province.","cn":"报告绘制了全省未处理水井的地理分布。"},{"en":"Its broad geographic distribution suggests the frog tolerates a wide range of temperatures.","cn":"其广泛的地理分布表明这种蛙能耐受很大的温度范围。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“几何分布”——把地图摊开，用几何格子把物种分布画出来 → geographic distribution 地理分布","word":"geographic distribution"},"root":"希腊语 gē（大地）+ graphein（书写）构成 geographic；distribution 来自拉丁语 distribuere（分配、分派）。","sensesIntro":{"en":"Eight senses of the phrase: a species range, a spatial pattern, and then the same map frame applied to people, resources, disease, languages, the map as a product, and the study of ranges.","cn":"这个短语的八个义项：先是物种范围与空间格局，再把同一地图框架用于人口、资源、疾病、语言，直到作为成果的分布图与对分布范围的研究。"},"semanticMap":{"core":{"en":"CORE IMAGE: a world map with shaded patches showing where something occurs.","cn":"核心意象：一张世界地图，用不同深浅的斑块显示某物出现的位置。"},"chain":["EARTH","DRAWN ON A SURFACE","OCCURRENCES PLOTTED","ALLOTTED INTO AREAS","PATTERN VISIBLE","WHY EXPLAINED"],"branches":[{"senses":"S1 · S2","en":"SPECIES: the range itself and the internal pattern of patches and gaps.","cn":"物种：分布范围本身，以及斑块与空白的内部格局。"},{"senses":"S3 · S4 · S5","en":"VARIABLES: the same frame carries people, resources, and disease cases.","cn":"变量：同一框架承载人口、资源与疾病病例。"},{"senses":"S6","en":"CULTURE: languages and practices occupy areas shaped by history.","cn":"文化：语言与习俗占据由历史塑造的区域。"},{"senses":"S7","en":"PRODUCT: the map or dataset becomes the distribution itself by metonymy.","cn":"成果：地图或数据集通过转喻成为“分布”本身。"},{"senses":"S8","en":"DISCIPLINE: the phrase names a research question about why ranges have their shapes.","cn":"学科：短语指“分布范围为何呈现这些形状”的研究问题。"}]},"affixes":{"intro":{"en":"The phrase combines a Greek scientific prefix geo-, the Greek combining form -graphic, and the Latin noun distribution. Only geo- and -graphic are productive English elements.","cn":"该短语由希腊语科学前缀 geo-、希腊语组合形式 -graphic 与拉丁语名词 distribution 组合；其中只有 geo- 与 -graphic 是英语中能产的成分。"},"latinIntro":{"en":"Latin distribuere 'to allot' yields distribute, distribution, distributive, and distributor; Greek gē yields geography, geology, geometry, and geocentric.","cn":"拉丁语 distribuere「分配」衍生 distribute、distribution、distributive、distributor；希腊语 gē 衍生 geography、geology、geometry、geocentric。"},"items":[{"word":"geography","structure":"geo- (earth) + -graphy (writing)","meaning":"the writing or description of the earth","meaningCN":"地理学；对地球的书写与描述","example":"She studied geography at university.","exampleCN":"她在大学学习地理学。"},{"word":"geographic","structure":"geo- + -graphic (pertaining to drawing)","meaning":"relating to the earth's surface","meaningCN":"与地表有关的","example":"Geographic data are stored as coordinates.","exampleCN":"地理数据以坐标形式存储。"},{"word":"geographical","structure":"geographic + -al (adjective variant)","meaning":"the British-preferred adjective form","meaningCN":"英式优先的形容词形式","example":"The geographical society funded the survey.","exampleCN":"地理学会资助了这次调查。"},{"word":"distribution","structure":"dis- (apart) + tribuere (to allot) + -ion","meaning":"the act of allotting out","meaningCN":"分派的行为（dis- 分开 + tribuere 分配 + -ion 名词）","example":"The distribution of rainfall is uneven.","exampleCN":"降水的分布不均衡。"},{"word":"distribute","structure":"dis- + tribuere (verb)","meaning":"to give out or spread","meaningCN":"分发；分布（动词）","example":"The species is distributed along the coast.","exampleCN":"该物种沿海岸分布。"},{"word":"distributive","structure":"distribute + -ive (adjective)","meaning":"relating to distribution","meaningCN":"与分配有关的","example":"A distributive map shows each region.","exampleCN":"分布图显示每个区域。"},{"word":"geocentric","structure":"geo- + centric (centred)","meaning":"measured from the earth's centre","meaningCN":"以地心为基准的","example":"Early models were geocentric.","exampleCN":"早期模型以地心为中心。"},{"word":"biogeography","structure":"bio- (life) + geography","meaning":"the study of life's geographic patterns","meaningCN":"研究生物地理格局的学科","example":"Biogeography explains island species.","exampleCN":"生物地理学解释岛屿物种。"}],"latinEntries":[{"word":"gē","structure":"Greek gē (noun)","meaning":"earth, land","meaningCN":"大地；土地"},{"word":"graphein","structure":"Greek graphein (verb)","meaning":"to write, draw","meaningCN":"书写；绘制"},{"word":"distribuere","structure":"dis- + tribuere (Latin verb)","meaning":"to allot out, distribute","meaningCN":"分派；分配"},{"word":"distributio","structure":"noun of action from distribuere","meaning":"a dividing out","meaningCN":"分配；分派"}]}},{"word":"territory","ipa_uk":"/ˈterətri/","ipa_us":"/ˈterətɔːri/","definition_zh":"领土；地盘；（动物的）领域；领域；地区","definition_en":"an area of land under a particular authority, or an area that an animal, person, or group treats as its own","core_image":"一只动物沿着灌木丛嗅出一圈界线，把这片地划成自己的","scene":"两只狼在河谷边缘留下气味标记，警告外来者不要进入这片领地。 Two wolves left scent marks along the edge of the valley, warning outsiders not to enter their territory.","sceneCN":"这里 territory 是「（动物的）领域、地盘」（第 2 个义项：动物防卫的空间）；句意：两只狼在河谷边缘留下气味标记，警告外来者不要进入这片领地。","pos":[{"tag":"n.","zh":"领土；属地；地区；领域；地盘（可数，复数为 territories）"}],"collocations":[{"phrase":"national territory","zh":"国家领土"},{"phrase":"defend one's territory","zh":"保卫自己的领地"},{"phrase":"mark its territory","zh":"标记领地；宣示地盘"},{"phrase":"unexplored territory","zh":"未探索的领域"},{"phrase":"territory dispute","zh":"领土争端"},{"phrase":"sales territory","zh":"销售区域"}],"forms":[{"label":"复数","form":"territories"},{"label":"形容词（领土的）","form":"territorial"},{"label":"名词（领域性）","form":"territoriality"},{"label":"相关动词（使成为领地）","form":"territorialize"}],"derivatives":[{"word":"territorial","pos":"adj.","zh":"领土的；地盘的；区域性的"},{"word":"territoriality","pos":"n.","zh":"领域性；地盘意识；属地原则"},{"word":"territorialize","pos":"v.","zh":"使领土化；按区域划分"},{"word":"territorially","pos":"adv.","zh":"在领土方面；按地域"}],"senses":[{"no":"01","title":"Land under a state's authority","titleCN":"国家管辖下的领土","definition":"the land and waters under the legal authority of a state or government","definitionCN":"处于国家或政府法律管辖之下的陆地与水域","example":"The treaty fixed the northern territory of the two nations.","exampleCN":"条约确定了两国的北部领土。","why":"Latin territorium first meant the land around a town, from terra 'earth'. The political sense grew by extending that 'land belonging to a centre' to a whole state.","whyCN":"拉丁语 territorium 最初指“城镇周围的土地”，来自 terra「土地」。政治义是把“属于某一中心的土地”扩展到整个国家。"},{"no":"02","title":"An animal's defended area","titleCN":"动物防卫的领域","definition":"the area an animal or group defends against intruders of the same or other species","definitionCN":"动物或群体防御同种或其他物种入侵的空间","example":"The male warbler sings at dawn to advertise his territory.","exampleCN":"雄莺在黎明鸣唱以宣告自己的领域。","why":"The political notion of bounded land is applied to behaviour: a bird treats a patch as if it were owned, and trespass is met with song or attack.","whyCN":"“有边界的土地”这一政治概念被用于行为：鸟把一块地当作己有，入侵者会遭到鸣唱警告或攻击。"},{"no":"03","title":"A field of knowledge or activity","titleCN":"知识或活动的领域","definition":"a domain of study, expertise, or action that belongs to a group or discipline","definitionCN":"属于某一群体或学科的研究、专长或行动范围","example":"Genetic editing lies in territory that older regulations never covered.","exampleCN":"基因编辑属于旧法规从未覆盖的领域。","why":"The spatial metaphor shifts from soil to concepts: an area is 'held' by a discipline just as land is held by a state, so new work is either inside or outside that boundary.","whyCN":"空间隐喻从土地转向概念：一个学科“持有”某个区域，就像国家持有土地，因此新研究要么在边界内，要么在边界外。"},{"no":"04","title":"Commercial or sales area","titleCN":"商业或销售区域","definition":"a region assigned to a salesperson, branch, or company as its exclusive market","definitionCN":"分配给销售员、分支机构或公司的专属市场区域","example":"The firm split the coast into three sales territories.","exampleCN":"公司把沿海地区分成三个销售区域。","why":"Modern business reuses the oldest structure: a centre assigns a bounded patch to an agent, and the boundary is protected against rival sellers.","whyCN":"现代商业复用了最古老的结构：中心把一块有边界的区域分给代理人，并防御竞争对手进入。"},{"no":"05","title":"A region or district","titleCN":"地区；地带","definition":"a general region of land, especially one with a distinguishing feature or administration","definitionCN":"具有某种特征或行政建制的广大地带","example":"Mountain territory covers most of the province.","exampleCN":"山区地带占该省的大部分。","why":"The word often simply names land at a regional scale, without the strict legal or behavioural sense; the boundary is geographic rather than defended.","whyCN":"这个词常只指区域尺度的土地，不带严格的法律或行为含义；边界是地理性的，而非被防卫的。"},{"no":"06","title":"A dependent possession","titleCN":"属地；附属领土","definition":"a land governed by another country but not fully integrated into it","definitionCN":"由另一国治理但未完全并入该国的土地","example":"The islands remain a territory of the mainland state.","exampleCN":"这些岛屿仍是大陆国家的属地。","why":"Imperial and colonial usage made territory the word for land held from outside; the people there may have rights of residence without full citizenship.","whyCN":"帝国与殖民用法使 territory 成为“从外部持有的土地”的用词；当地居民可能拥有居住权而无法获得完整公民身份。"},{"no":"07","title":"Unfamiliar or dangerous ground","titleCN":"未知或危险的处境","definition":"in figurative use, a situation or subject that people have not dealt with before","definitionCN":"用于比喻，指人们此前未曾应对过的处境或主题","example":"Negotiating with the rebels took the envoys into unknown territory.","exampleCN":"与叛军谈判把使节带入了未知领域。","why":"The metaphor treats experience as a map: known land is charted, unknown land is territory without marks, and entering it means risk.","whyCN":"这个隐喻把经验当作地图：已知之地被测绘，未知之地是没有标记的 territory，进入它就意味着风险。"},{"no":"08","title":"A marked area in a game or sport","titleCN":"比赛或运动中的场地范围","definition":"the part of a playing field or board assigned to a player or team","definitionCN":"运动场或棋盘上分配给某一方或队员的区域","example":"The defender refused to leave his territory near the goal.","exampleCN":"后卫拒绝离开球门附近的防区。","why":"Games formalize the same instinct: space is divided and each player is responsible for one patch, so 'territory' becomes a rule rather than a claim.","whyCN":"比赛把同一种本能形式化：空间被划分，每名球员负责一块区域，于是 territory 成为规则而不是主张。"}],"etymology":{"intro":{"en":"Territory came from Latin territorium, the land around a town. Its link to terra 'land' is clear, but a popular derivation from terrere 'to frighten' remains disputed, so that branch is marked uncertain.","cn":"territory 来自拉丁语 territorium，即城镇周围的土地。它与 terra「土地」的联系清楚，但流行的“来自 terrere「使恐惧」”一说仍有争议，故该分支标注为不确定。"},"items":[{"era":"LATE 14C.","en":"English territory is recorded in the late fourteenth century meaning 'land under the jurisdiction of a town or lord'.","cn":"英语 territory 于 14 世纪晚期被记录，义为“城镇或领主管辖下的土地”。"},{"era":"LATIN","en":"From Latin territorium 'land around a town, domain, district'. The suffix -orium marks a place associated with something.","cn":"来自拉丁语 territorium「城镇周围的土地、领地、区域」。后缀 -orium 标记与某物相关的地点。"},{"era":"LATIN BASE","en":"The base is terra 'earth, land', which also gives terrain, terrace, Mediterranean and terracotta. This part of the history is well supported.","cn":"词基是 terra「土地」，还衍生 terrain、terrace、Mediterranean、terracotta。这部分历史有充分支持。"},{"era":"DISPUTED","en":"Some sources connect territorium with terrere 'to frighten' and territare 'to frighten repeatedly', which would make the original sense 'land kept by fear'. Standard references disagree, so this link is source uncertain.","cn":"有些资料把 territorium 与 terrere「使恐惧」、territare「反复恐吓」联系起来，那样原义会是“靠恐惧守住的土地”。通行资料并不一致，故该联系来源不确定。"},{"era":"16C.–19C.","en":"The sense widened to colonial possessions and to figurative 'field of knowledge'; in the 20th century ethology borrowed it for defended animal space.","cn":"词义扩展到殖民地属地与比喻性的“知识领域”；20 世纪动物行为学又借它指被防卫的动物空间。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the political, behavioural, commercial, and figurative senses side by side; the plural territories is standard.","cn":"现代英语并列保留政治、行为、商业与比喻义；复数 territories 为标准形式。"}]},"similar":{"note":{"en":"The first group separates form neighbours, the second compares words for land and defended space.","cn":"第一组区分词形相近者，第二组比较表示土地与防卫空间的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"terrain","ipa":"/təˈreɪn/","tag":"same terra root","definition":"the physical surface of land, its slope and texture. It is ground as landscape, not ground as jurisdiction.","definitionCN":"土地的地表形态、坡度与质地。它是作为景观的地面，而非作为管辖范围的地面。"},{"word":"terrace","ipa":"/ˈterəs/","tag":"same terra root","definition":"a flat raised strip of land; from terra through French. It shares the earth base but not the political sense.","definitionCN":"平坦的台地；经法语来自 terra。共享“土地”词基，但无政治义。"},{"word":"terror","ipa":"/ˈterə/","tag":"possibly confused root","definition":"extreme fear, from terrere 'to frighten'. It is not a relative unless the disputed territory link is accepted.","definitionCN":"极度恐惧，来自 terrere「使恐惧」。除非接受有争议的 territory 联系，否则并非同源。"},{"word":"territorial","ipa":"/ˌterəˈtɔːriəl/","tag":"derived adjective","definition":"relating to territory; also the adjective for defensive behaviour.","definitionCN":"与领土有关的；也指防卫行为的形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"domain","ipa":"/dəˈmeɪn/","tag":"formal","definition":"an area owned or controlled, often legal or feudal; also a field of expertise. It is more formal than territory.","definitionCN":"拥有或控制的区域，常为法律或封建语境；也指专长领域。比 territory 更正式。"},{"word":"region","ipa":"/ˈriːdʒən/","tag":"geographic","definition":"a broad area defined by geography or administration. It lacks the sense of defence or ownership.","definitionCN":"由地理或行政界定的大片区域。缺少防卫或占有之义。"},{"word":"range","ipa":"/reɪndʒ/","tag":"ecology","definition":"the area in which a species occurs. It is not necessarily defended.","definitionCN":"物种出现的区域。不一定被防卫。"},{"word":"ground","ipa":"/ɡraʊnd/","tag":"everyday","definition":"the surface or an area underfoot, or a field of argument. It is neutral and physical.","definitionCN":"脚下的地面或场地，也指论点领域。中性且偏物理。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin parts, standard phrases, and real relatives.","cn":"正常联想：真实的拉丁语成分、标准搭配与真实同族词。"},"normal":[{"en":"terra means earth: territory is land marked off as belonging to someone.","cn":"terra 意为土地：territory 是被划出来、属于某人的土地。"},{"en":"Mark its territory is the fixed phrase for animals leaving scent, sound, or visible signs.","cn":"mark its territory 是动物留下气味、声音或可见标记的固定说法。"},{"en":"Terrain is the same land seen as surface; territory is the same land seen as ownership.","cn":"terrain 是把同一片土地看作地表；territory 是把同一片土地看作所有权。"},{"en":"Sales territory shows how ordinary the structure is: a company assigns a patch to a seller.","cn":"sales territory 说明这个结构多么日常：公司把一块区域分给销售员。"},{"en":"Unknown territory is the figurative branch: experience drawn as a map with blank areas.","cn":"unknown territory 是比喻分支：把经验画成一张留有空白的地图。"}],"abstract":[{"en":"Picture a line drawn in grass: on one side is 'mine', on the other 'not mine'. Territory is the area inside the line, however the line is made.","cn":"想象在草地上画一条线：一边是“我的”，另一边是“不是我的”。territory 就是线内的区域，无论线是怎么画出来的。"},{"en":"The word moves easily from states to animals to disciplines to sales because all four involve a centre assigning and defending a bounded area.","cn":"这个词能轻易从国家转到动物、学科、销售，因为四者都涉及一个中心分配并防卫有边界的区域。"},{"en":"Behavioral territory is not property in law; it is a claim enforced by presence, not by title.","cn":"行为学上的领域不是法律财产；它是由在场维系的 claim，而不是由产权证维系。"}]},"examples":[{"en":"The river forms the eastern boundary of the territory.","cn":"这条河构成该领土的东部边界。"},{"en":"Robins defend their territory against intruders throughout the spring.","cn":"整个春天，知更鸟都在防御领地、抵御入侵者。"},{"en":"The question of consciousness is still unexplored territory for the lab.","cn":"意识问题对该实验室仍是未探索的领域。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“太弱的里”——这片地里太弱的人守不住，只能让强敌占去 → territory 领地、领土","word":"territory"},"root":"拉丁语 territorium「城镇周围的土地」，词基 terra「土地」；与 terrere「使恐惧」的联系存疑。","sensesIntro":{"en":"Eight senses of territory: a bounded area held by a state, an animal, a discipline, a company, a game, or the imagination. The common core is 'land marked as belonging'.","cn":"territory 的八个义项：由国家、动物、学科、公司、比赛或想象持有的有边界区域。共同核心是“被标记为属于某方的土地”。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn around a patch of ground, with 'mine' inside and 'not mine' outside.","cn":"核心意象：在一片土地周围画一条线，线内是“我的”，线外是“不是我的”。"},"chain":["LAND","BOUNDARY DRAWN","CLAIM MADE","OUTSIDERS WARNED","AREA HELD","BELONGING"],"branches":[{"senses":"S1 · S6","en":"POLITICS: land under a state, including dependent possessions beyond the core.","cn":"政治：国家管辖的土地，包括核心之外的属地。"},{"senses":"S2 · S8","en":"BEHAVIOUR AND PLAY: animals and players defend an assigned patch.","cn":"行为与比赛：动物与球员防卫被分配的区域。"},{"senses":"S3 · S7","en":"KNOWLEDGE: a discipline's field, or the blank part of the map called unknown.","cn":"知识：学科领域，或被称作“未知”的地图空白部分。"},{"senses":"S4","en":"COMMERCE: a company assigns a market patch to an agent.","cn":"商业：公司把一块市场区域分给代理人。"},{"senses":"S5","en":"GEOGRAPHY: a broad region named by its features rather than by defence.","cn":"地理：以特征而非防卫命名的广大地区。"}]},"affixes":{"intro":{"en":"Territory is a Latin noun in -orium, a suffix of place. English adds the adjective and noun suffixes -ial and -iality, but does not build the root anew.","cn":"territory 是带 -orium（地点后缀）的拉丁名词。英语只加形容词与名词后缀 -ial、-iality，并不重新构造词根。"},"latinIntro":{"en":"Terra 'earth' yields terrain, terrace, terracotta, and Mediterranean; the territorium branch yields territorial, territoriality, and the verb territorialize.","cn":"terra「土地」衍生 terrain、terrace、terracotta、Mediterranean；territorium 这一支衍生 territorial、territoriality 与动词 territorialize。"},"items":[{"word":"territorial","structure":"territory + -ial (adjective)","meaning":"relating to territory","meaningCN":"领土的；领域的（-ial 形容词）","example":"Territorial claims caused the war.","exampleCN":"领土主张引发了战争。"},{"word":"territoriality","structure":"territorial + -ity (noun of state)","meaning":"the state or practice of holding territory","meaningCN":"领域性；属地状态（-ity 名词）","example":"Territoriality is common in songbirds.","exampleCN":"领域性在鸣禽中很常见。"},{"word":"territorialize","structure":"territorial + -ize (verb)","meaning":"to make into or organize by territory","meaningCN":"使领土化；按区域组织（-ize 动词）","example":"States territorialize maritime space.","exampleCN":"国家把海洋空间领土化。"},{"word":"territorially","structure":"territorial + -ly (adverb)","meaning":"in territorial terms","meaningCN":"在领土或地域方面（-ly 副词）","example":"The region is territorially divided.","exampleCN":"该地区在地域上被划分。"},{"word":"terrain","structure":"terra + -ain (French form)","meaning":"the surface features of land","meaningCN":"地形；地表特征","example":"The terrain is too steep for trucks.","exampleCN":"地形太陡，卡车无法通行。"},{"word":"terrace","structure":"terra + -ace (place)","meaning":"a flat raised shelf of land","meaningCN":"台地；梯田","example":"Rice grows on the terraces.","exampleCN":"水稻种在梯田上。"},{"word":"terracotta","structure":"terra + cotta (baked)","meaning":"baked earth; a reddish clay","meaningCN":"陶土；红陶","example":"The roof tiles are terracotta.","exampleCN":"屋顶瓦片是红陶的。"},{"word":"Mediterranean","structure":"medius (middle) + terra (land)","meaning":"the sea in the middle of land","meaningCN":"被陆地环绕的地中海","example":"Olives grow across the Mediterranean.","exampleCN":"橄榄树遍布地中海地区。"}],"latinEntries":[{"word":"terra","structure":"terra (noun, first declension)","meaning":"earth, land","meaningCN":"土地；大地"},{"word":"territorium","structure":"terra + -orium (place suffix)","meaning":"land around a town; domain","meaningCN":"城镇周围的土地；领地"},{"word":"terrere","structure":"terrere (verb, second conjugation)","meaning":"to frighten","meaningCN":"使恐惧（与 territory 的联系存疑）"},{"word":"terrenus","structure":"terra + -enus (adjective)","meaning":"of earth, earthly","meaningCN":"土地的；尘世的"}]}},{"word":"territorial","ipa_uk":"/ˌterəˈtɔːriəl/","ipa_us":"/ˌterəˈtɔːriəl/","definition_zh":"领土的；领地的；地盘性的；区域性的","definition_en":"relating to territory, especially to land held by a state or to an area defended by an animal or person","core_image":"地图上的国界线与动物在草丛中留下的一圈气味线叠在一起","scene":"两只雄鸟在河岸的柳丛间追逐，驱赶靠近边界的同类。 Two male birds chased each other through the riverside willows, driving away rivals that came near the territorial boundary.","sceneCN":"这里 territorial 是「地盘性的、防卫领域的」（第 2 个义项：动物对领域的防卫）；句意：两只雄鸟在河岸柳丛间互相追逐，把靠近领地边界的同类赶走。","pos":[{"tag":"adj.","zh":"领土的；领地的；地盘性的；区域性的"},{"tag":"n.","zh":"领土防卫军成员（英国用法，Territorial）"}],"collocations":[{"phrase":"territorial dispute","zh":"领土争端"},{"phrase":"territorial waters","zh":"领海"},{"phrase":"territorial integrity","zh":"领土完整"},{"phrase":"territorial behaviour","zh":"地盘行为；领域行为"},{"phrase":"territorial claim","zh":"领土主张"},{"phrase":"territorial army","zh":"地方防卫军（英国）"}],"forms":[{"label":"比较级（较少用）","form":"more territorial"},{"label":"最高级（较少用）","form":"most territorial"},{"label":"名词（领域性）","form":"territoriality"},{"label":"副词（在领土方面）","form":"territorially"}],"derivatives":[{"word":"territory","pos":"n.","zh":"领土；领域；地盘"},{"word":"territoriality","pos":"n.","zh":"领域性；属地原则"},{"word":"territorially","pos":"adv.","zh":"在领土方面；按地域"},{"word":"territorialize","pos":"v.","zh":"使领土化；按区域划分"}],"senses":[{"no":"01","title":"Relating to a state's land","titleCN":"与国家领土有关的","definition":"concerning the land and waters governed by a state","definitionCN":"涉及国家治理的陆地与水域","example":"The two countries signed a territorial agreement over the island.","exampleCN":"两国就该岛签署了一项领土协议。","why":"The adjective simply attaches territory's political sense to a noun: whatever is territorial concerns land held under a state's authority.","whyCN":"这个形容词只是把 territory 的政治义附加到名词上：凡是 territorial 的，都涉及国家权力下的土地。"},{"no":"02","title":"Defending an area, in animals","titleCN":"动物防卫领域的","definition":"describing an animal that defends a fixed area against rivals","definitionCN":"描述动物防卫固定区域、抵御同类的行为","example":"Territorial males sing to keep rivals away from the nest site.","exampleCN":"有领域性的雄鸟鸣唱，使竞争者远离巢址。","why":"Ethology borrowed the political adjective: the bird behaves as if it holds title to a patch, and its song is the boundary notice.","whyCN":"动物行为学借用了这个政治形容词：鸟表现得仿佛对一块地拥有产权，鸣唱就是边界通告。"},{"no":"03","title":"Of waters claimed by a state","titleCN":"属于国家主张的海域","definition":"relating to the belt of sea over which a coastal state claims jurisdiction","definitionCN":"与沿海国主张管辖的带状海域有关","example":"Foreign ships must respect the territorial waters of the coast.","exampleCN":"外国船只必须尊重沿海国的领海。","why":"Water is treated like land for legal purpose: the same adjective extends the state's boundary from soil to sea, producing 'territorial waters'.","whyCN":"法律上把水当作土地处理：同一形容词把国家边界从陆地延伸到海洋，形成 territorial waters。"},{"no":"04","title":"Of claims, disputes, and integrity","titleCN":"关于领土主张、争端与完整","definition":"concerning demands over land, conflicts about boundaries, or the principle that a state's land must not be broken up","definitionCN":"涉及对土地的要求、边界冲突，或国家领土不可分割的原则","example":"Territorial integrity is written into the charter.","exampleCN":"领土完整被写入宪章。","why":"Once land is bounded, it can be claimed, disputed, or guaranteed. The adjective names the legal and diplomatic dimension of those boundaries.","whyCN":"土地一旦有边界，就可以被主张、争夺或保障。该形容词命名这些边界的法律与外交维度。"},{"no":"05","title":"Organized by region","titleCN":"按区域组织的","definition":"divided or administered according to regional areas rather than a single centre","definitionCN":"按区域划分或管理，而非由单一中心统管","example":"The agency adopted a territorial structure with six regional offices.","exampleCN":"该机构采用按区域划分的结构，设六个地区办事处。","why":"The noun's 'district' sense becomes an administrative adjective: an organization mirrors a map, and each unit governs its own patch.","whyCN":"名词的“区域”义转为行政形容词：组织像地图一样被划分，每个单元管理自己的一块。"},{"no":"06","title":"Possessive about personal space","titleCN":"对个人空间有地盘意识的","definition":"in everyday use, describing a person who treats a place or role as exclusively theirs","definitionCN":"日常用法中描述把某处或某角色视为专属的人","example":"He gets territorial about his desk when interns borrow it.","exampleCN":"实习生借用他的桌子时，他就很有地盘意识。","why":"Human behaviour is described with the animal adjective: the desk is not legally owned in the relevant sense, but it is defended like a range.","whyCN":"用动物的形容词描述人类行为：那张桌子在相关意义上并非法律所有，却像领地一样被防卫。"},{"no":"07","title":"Of a local defence force","titleCN":"地方防卫军的","definition":"in British usage, relating to the volunteer reserve army organized by region","definitionCN":"英式用法中，与按地区组织的志愿预备役部队有关","example":"He served in the Territorial Army for eight years.","exampleCN":"他在地方防卫军服役八年。","why":"The word's 'regional' sense explains the name: a force raised and organized by locality rather than as a standing national army.","whyCN":"这个词的“区域”义解释了名称：按地方征募与组织的部队，而不是常备国家军队。"},{"no":"08","title":"Of animal space use in ecology","titleCN":"生态学中关于空间利用的","definition":"in ecology, describing systems where individuals or groups exclude others from an area","definitionCN":"生态学中描述个体或群体排斥他者进入某区域的体系","example":"Territorial species often show stable population densities.","exampleCN":"领域性物种常表现出稳定的种群密度。","why":"Ecology turns the adjective into a technical classifier: a species is territorial if its spacing is maintained by exclusion rather than by random movement.","whyCN":"生态学把这个形容词变成技术分类：若某物种的间距靠排斥而非随机移动维持，它就是 territorial。"}],"etymology":{"intro":{"en":"Territorial is the English adjective from territory, formed with -ial. Its base is Latin terra 'land'; the disputed terrere 'frighten' link belongs to the noun's uncertain fringe.","cn":"territorial 是由 territory 加 -ial 构成的英语形容词。词基是拉丁语 terra「土地」；有争议的 terrere「使恐惧」联系属于名词的不确定边缘。"},"items":[{"era":"18C.","en":"The adjective territorial is recorded in the eighteenth century, derived from territory rather than borrowed as a ready-made Latin adjective.","cn":"形容词 territorial 于 18 世纪被记录，由 territory 派生，而不是直接借入现成的拉丁形容词。"},{"era":"LATIN BASE","en":"territory < territorium 'land around a town' < terra 'earth, land'. The adjective therefore means 'of the land belonging to a centre'.","cn":"territory < territorium「城镇周围的土地」< terra「土地」。因此形容词意为“属于某一中心的土地的”。"},{"era":"DISPUTED","en":"The alternative derivation from terrere 'to frighten' is sometimes repeated for territory; it is not settled, so the 'land kept by fear' nuance is source uncertain.","cn":"另有把 territory 追溯到 terrere「使恐惧」的说法常被重复，但并无定论，故“靠恐惧守住的土地”这一层含义来源不确定。"},{"era":"19C.–20C.","en":"The adjective extended to territorial waters and territorial integrity in international law, and to territorial behaviour in zoology.","cn":"19 至 20 世纪，该形容词扩展到国际法中的领海与领土完整，以及动物学中的领域行为。"},{"era":"MODERN ENGLISH","en":"Modern usage distinguishes territory (the area) from territorial (the relation to it); the noun territorial is chiefly British and refers to a reservist.","cn":"现代用法区分 territory（区域）与 territorial（与之相关）；名词 territorial 主要为英式用法，指预备役军人。"}]},"similar":{"note":{"en":"The first group separates spelling relatives, the second compares adjectives of land and defence.","cn":"第一组区分拼写同族词，第二组比较表示土地与防卫的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"territory","ipa":"/ˈterətri/","tag":"base noun","definition":"the area itself; the adjective describes what relates to it.","definitionCN":"区域本身；形容词描述与它相关的事物。"},{"word":"terrestrial","ipa":"/təˈrestriəl/","tag":"same terra root","definition":"of the earth or land, often opposed to aquatic or celestial. It shares terra but not the political boundary sense.","definitionCN":"地球的或陆生的，常与水生或天体相对。共享 terra，但无政治边界义。"},{"word":"terrain","ipa":"/təˈreɪn/","tag":"same terra root","definition":"the physical surface of land; terrain is ground as shape, territory is ground as claim.","definitionCN":"土地的地表形态；terrain 是形状意义上的地面，territory 是主张意义上的地面。"},{"word":"terror","ipa":"/ˈterə/","tag":"disputed root","definition":"extreme fear, from terrere. Its connection to territory is only the disputed hypothesis.","definitionCN":"极度恐惧，来自 terrere。它与 territory 的联系仅是存疑假设。"}]},{"heading":"NEAR MEANING","entries":[{"word":"regional","ipa":"/ˈriːdʒənl/","tag":"administrative","definition":"relating to a region; it lacks the legal claim and defence senses of territorial.","definitionCN":"与区域有关的；缺少 territorial 的法律主张与防卫义。"},{"word":"possessive","ipa":"/pəˈzesɪv/","tag":"personal","definition":"wanting to keep what one has; in everyday use it overlaps with territorial about space.","definitionCN":"想要保住自己所有的；日常用法中在空间问题上与 territorial 重叠。"},{"word":"defensive","ipa":"/dɪˈfensɪv/","tag":"behaviour","definition":"acting to protect against attack; territorial behaviour is often defensive but not always.","definitionCN":"为防攻击而行动；领域行为常是防御性的，但不总是。"},{"word":"jurisdictional","ipa":"/ˌdʒʊərɪsˈdɪkʃənl/","tag":"legal","definition":"relating to the power to govern an area; it stresses authority rather than boundary.","definitionCN":"与治理某区域的权力有关；强调权威而非边界。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffix patterns and standard legal and biological phrases.","cn":"正常联想：真实后缀模式与法律、生物学的标准搭配。"},"normal":[{"en":"territory + -ial makes the adjective; anything territorial 'belongs to' a territory.","cn":"territory + -ial 构成形容词；territorial 的东西“属于”某个 territory。"},{"en":"Territorial waters extends land law to a belt of sea.","cn":"territorial waters 把土地法延伸到一条海域。"},{"en":"Territorial integrity is the legal phrase for 'the land must not be broken up'.","cn":"territorial integrity 是“领土不可被分割”的法律用语。"},{"en":"Territorial behaviour is the ethology phrase for animals excluding rivals from a patch.","cn":"territorial behaviour 是动物行为学中“把竞争者排除在某块地”的用语。"},{"en":"The British Territorial Army is regional by design; the adjective's 'regional' sense names it.","cn":"英国 Territorial Army 按地区组织；形容词的“区域”义正是其名称来源。"}],"abstract":[{"en":"Picture a fence: the land is territory, the fence's logic is territorial, and the habit of guarding it is territoriality.","cn":"想象一道篱笆：土地是 territory，篱笆的逻辑是 territorial，守卫它的习性则是 territoriality。"},{"en":"The same adjective covers state borders and a desk at work because both are areas a holder excludes others from.","cn":"同一形容词覆盖国界与办公桌，因为两者都是持有者排斥他人的区域。"},{"en":"Territorial is relational: it never names the land alone, only the land seen through a claim.","cn":"territorial 是关系性的：它从不单独命名土地，只命名透过“主张”看到的土地。"}]},"examples":[{"en":"The dispute over territorial waters has lasted for decades.","cn":"关于领海的争端已持续数十年。"},{"en":"Territorial birds attack intruders much larger than themselves.","cn":"领域性鸟类会攻击比自己大得多的入侵者。"},{"en":"She became territorial about the project after working on it alone.","cn":"独自做了一段时间后，她对这个项目有了地盘意识。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“特瑞托瑞尔”——特别划定的一块地里，谁进来就赶谁 → territorial 领土的、地盘性的","word":"territorial"},"root":"由 territory 加形容词后缀 -ial 构成；territory 出自拉丁语 territorium（terra「土地」）。","sensesIntro":{"en":"Eight senses of territorial: the adjective follows territory from state land to defended animal space, administrative regions, personal space, reserve forces, and ecological spacing.","cn":"territorial 的八个义项：这个形容词随 territory 从国家土地延伸到动物防卫空间、行政区域、个人空间、预备役部队与生态间距。"},"semanticMap":{"core":{"en":"CORE IMAGE: a boundary line, whether a national border or a scent mark in grass.","cn":"核心意象：一条边界线，无论是国界还是草丛中的气味标记。"},"chain":["TERRITORY","BOUNDARY","CLAIM OR DEFENCE","EXCLUSION","STABLE SPACING","ORDER"],"branches":[{"senses":"S1 · S4","en":"LAND AND CLAIMS: the state's own ground and the claims made about it are one boundary question seen from two sides.","cn":"土地与主张：国家自己的土地与围绕它提出的主张，是同一个边界问题从两面看的样子。"},{"senses":"S3","en":"SEA: waters a state claims carry the land boundary outward onto the water.","cn":"海域：国家主张的海域把陆地边界向外延伸到水上。"},{"senses":"S2 · S8","en":"ANIMAL SPACING: defence of an area produces regular distances between individuals.","cn":"动物间距：对区域的防卫使个体之间形成规则的距离。"},{"senses":"S5 · S7","en":"ADMINISTRATION: regional offices and local defence forces mirror the map.","cn":"行政与防卫：地区机构与地方防卫力量是地图在组织上的对应物。"},{"senses":"S6","en":"PERSONAL SPACE: a desk, a seat, or a role is defended as if it were land.","cn":"个人空间：一张桌子、一个座位或一个角色，也会像土地一样被防卫。"}]},"affixes":{"intro":{"en":"Territorial is territory plus the Latin-derived adjective suffix -ial. The suffix is productive in English (editorial, residential), but the base is a borrowed noun.","cn":"territorial 是 territory 加拉丁来源的形容词后缀 -ial。该后缀在英语中能产（editorial、residential），但词基是借入的名词。"},"latinIntro":{"en":"The terra family supplies territory, terrain, terrace, terracotta, and Mediterranean; the -ial suffix also builds memorial, financial, and substantial.","cn":"terra 一族提供 territory、terrain、terrace、terracotta、Mediterranean；-ial 后缀还构成 memorial、financial、substantial。"},"items":[{"word":"territorial","structure":"territory + -ial (adjective)","meaning":"relating to territory","meaningCN":"与领土有关的（-ial 形容词）","example":"Territorial claims are sensitive.","exampleCN":"领土主张很敏感。"},{"word":"territorially","structure":"territorial + -ly (adverb)","meaning":"in territorial terms","meaningCN":"在领土方面","example":"The sea is territorially divided.","exampleCN":"这片海在领土上被划分。"},{"word":"territoriality","structure":"territorial + -ity (noun)","meaning":"the practice of holding territory","meaningCN":"领域性；属地性（-ity 名词）","example":"Territoriality regulates spacing.","exampleCN":"领域性调节间距。"},{"word":"territorialize","structure":"territorial + -ize (verb)","meaning":"to organize by territory","meaningCN":"使领土化；按区域组织","example":"The state territorialized the coast.","exampleCN":"国家把海岸领土化。"},{"word":"territory","structure":"territorium (noun)","meaning":"a bounded area held by someone","meaningCN":"被某方持有的有界区域","example":"The territory is rich in minerals.","exampleCN":"该领土矿产丰富。"},{"word":"terrain","structure":"terra + -ain (French)","meaning":"ground as surface","meaningCN":"作为地表的地面","example":"The terrain rises sharply.","exampleCN":"地形陡然升高。"},{"word":"terrace","structure":"terra + -ace (place)","meaning":"a flat shelf of land","meaningCN":"台地；梯田","example":"The terrace holds rainwater.","exampleCN":"台地蓄住雨水。"},{"word":"terrestrial","structure":"terra + -estris (adjective)","meaning":"of the earth or land","meaningCN":"地球的；陆生的","example":"Terrestrial animals breathe air.","exampleCN":"陆生动物呼吸空气。"}],"latinEntries":[{"word":"terra","structure":"terra (first declension)","meaning":"earth, land","meaningCN":"土地；大地"},{"word":"territorium","structure":"terra + -orium","meaning":"land around a town","meaningCN":"城镇周围的土地"},{"word":"terrenus","structure":"terra + -enus","meaning":"earthly","meaningCN":"土地的；尘世的"},{"word":"terrere","structure":"terrere (second conjugation)","meaning":"to frighten (disputed link)","meaningCN":"使恐惧（与 territory 的联系存疑）"}]}},{"word":"territoriality","ipa_uk":"/ˌterəˌtɔːriˈæləti/","ipa_us":"/ˌterəˌtɔːriˈæləti/","definition_zh":"领域性；地盘性；属地原则","definition_en":"the behaviour or principle of claiming and defending an area, or in law the rule that a state's power applies within its own territory","core_image":"一只动物在自己边界内来回巡视，边界外则退让","scene":"这片珊瑚礁上的小丑鱼会驱赶靠近其寄居海葵的同种个体，研究者把这种行为记为领域性。 On this reef, clownfish drive away individuals of their own species that approach their host anemone, a behaviour researchers record as territoriality.","sceneCN":"这里 territoriality 是「领域性」（第 1 个义项：动物防卫空间的习性）；句意：珊瑚礁上的小丑鱼会驱赶靠近其寄居海葵的同种个体，研究者把这种行为记为领域性。","pos":[{"tag":"n.","zh":"领域性；地盘性；属地原则（多作不可数）"}],"collocations":[{"phrase":"animal territoriality","zh":"动物领域性"},{"phrase":"human territoriality","zh":"人类地盘性"},{"phrase":"principle of territoriality","zh":"属地原则"},{"phrase":"territoriality in ecology","zh":"生态学中的领域性"},{"phrase":"sense of territoriality","zh":"地盘意识"},{"phrase":"territoriality dispute","zh":"属地管辖争议"}],"forms":[{"label":"复数（少见）","form":"territorialities"},{"label":"形容词","form":"territorial"},{"label":"名词（区域）","form":"territory"},{"label":"副词","form":"territorially"}],"derivatives":[{"word":"territorial","pos":"adj.","zh":"领土的；领域性的"},{"word":"territory","pos":"n.","zh":"领土；领域；地盘"},{"word":"territorialize","pos":"v.","zh":"使领土化"},{"word":"territorially","pos":"adv.","zh":"在领土方面"}],"senses":[{"no":"01","title":"Animal defence of space","titleCN":"动物对空间的防卫","definition":"the pattern in which an animal excludes others from a fixed area","definitionCN":"动物把其他个体排除在固定区域之外的模式","example":"Territoriality in the lizard increases during the breeding season.","exampleCN":"这种蜥蜴的领域性在繁殖季增强。","why":"The noun turns the adjective territorial into a general property: not one defended patch, but the habit of defending patches as such.","whyCN":"这个名词把形容词 territorial 变成一般属性：不是某一块被防卫的地，而是“防卫地块”这一习性本身。"},{"no":"02","title":"Human claim on space","titleCN":"人类对空间的占有感","definition":"the tendency of people to treat places, seats, or rooms as belonging to them and to resist sharing","definitionCN":"人们把地点、座位或房间视为己有并抗拒共享的倾向","example":"Human territoriality explains why regular library seats are defended by books and coats.","exampleCN":"人类地盘性解释了为何固定使用的图书馆座位会被人用书和外套占住。","why":"Ethology's concept is transferred to people: the markers are objects rather than scent, but the exclusion of others follows the same logic.","whyCN":"动物行为学的概念被移用到人：标记物是物品而非气味，但排斥他人的逻辑相同。"},{"no":"03","title":"Legal principle of territorial jurisdiction","titleCN":"属地管辖原则","definition":"the rule that a state's law applies to acts within its territory","definitionCN":"一国法律适用于其领土内行为的规则","example":"Under territoriality, the court applied local law to the crime.","exampleCN":"依据属地原则，法院对该罪行适用当地法律。","why":"In law the noun names a principle rather than a behaviour: authority is bounded by land, so the location of an act decides which law governs it.","whyCN":"在法律中，这个名词指原则而非行为：权威受土地边界限制，因此行为发生地决定适用哪一套法律。"},{"no":"04","title":"Scope of a state's authority","titleCN":"国家权力的属地范围","definition":"the extent to which a state may exercise power over people and things within its borders","definitionCN":"国家在其边界内对人与物行使权力的范围","example":"Territoriality limits the reach of the embassy's home law.","exampleCN":"属地性限制了大使馆本国法律的适用范围。","why":"Here the abstract property is attributed to a state: power does not travel beyond the boundary, and the territory defines the outer limit of jurisdiction.","whyCN":"这里抽象属性被归于国家：权力不越出边界，领土界定了管辖的外沿。"},{"no":"05","title":"Sense of ownership of a place","titleCN":"对某地的拥有感","definition":"a felt attachment to a place that makes intrusion feel like a violation","definitionCN":"对某地的情感依恋，使他人进入被感受为侵犯","example":"The villagers' territoriality was strong around the shared well.","exampleCN":"村民对共用井的地盘感很强。","why":"The behavioural pattern becomes psychological: the boundary is internalized, so trespass produces irritation even without legal ownership.","whyCN":"行为模式变成心理现象：边界被内化，因此即使没有法律所有权，他人进入也会引起不快。"},{"no":"06","title":"Organizational turf protection","titleCN":"组织中的地盘保护","definition":"the tendency of departments or teams to guard their functions and information from other units","definitionCN":"部门或团队防卫自身职能与信息、不让其他单位介入的倾向","example":"Territoriality between the two departments delayed the merger.","exampleCN":"两个部门之间的地盘之争拖延了合并。","why":"The spatial word is applied to institutions: a department's 'area' is its function, and defending it looks exactly like defending land.","whyCN":"空间词被用于机构：部门的“区域”就是其职能，防卫职能看起来与防卫土地完全相同。"},{"no":"07","title":"Ecological spacing mechanism","titleCN":"生态学的间距机制","definition":"the process by which territorial behaviour regulates population density and resource use","definitionCN":"领域行为调节种群密度与资源利用的过程","example":"Territoriality keeps the warbler population below the food-limited ceiling.","exampleCN":"领域性使莺的种群数量低于食物限定的上限。","why":"In ecology the property is studied as a mechanism: exclusion produces regular spacing, and spacing in turn affects how many individuals an area can hold.","whyCN":"在生态学中，这一属性被当作机制研究：排斥产生规则间距，间距又影响一片区域能容纳多少个体。"},{"no":"08","title":"Degree of defensiveness","titleCN":"防卫性的强弱程度","definition":"the measurable intensity of territorial behaviour, from weakly defended home ranges to strongly guarded territories","definitionCN":"领域行为可测量的强度，从防卫很弱的家域到守卫严密的领域","example":"The study scored territoriality on a scale from one to five.","exampleCN":"这项研究用 1 到 5 的等级给领域性打分。","why":"A property noun can be quantified: different species, seasons, or individuals show more or less of the same behaviour, so territoriality becomes a variable.","whyCN":"属性名词可以被量化：不同物种、季节或个体表现出程度不同的同一行为，于是领域性成为一个变量。"}],"etymology":{"intro":{"en":"Territoriality is a nineteenth-century abstract noun from territorial plus -ity. Its base is Latin terra 'land'; the 'frighten' hypothesis about territory remains unsettled.","cn":"territoriality 是 19 世纪由 territorial 加 -ity 构成的抽象名词。词基是拉丁语 terra「土地」；关于 territory 的“使恐惧”假说仍无定论。"},"items":[{"era":"19C.","en":"The noun territoriality appears in the nineteenth century, first in legal and political writing about the scope of a state's authority.","cn":"名词 territoriality 于 19 世纪出现，最初见于关于国家权力范围的法律与政治写作。"},{"era":"LATIN BASE","en":"territorial < territory < Latin territorium 'land around a town' < terra 'land'. The suffix chain is -ity on -ial on the noun.","cn":"territorial < territory < 拉丁语 territorium「城镇周围的土地」< terra「土地」。后缀链是名词加 -ial 再加 -ity。"},{"era":"DISPUTED","en":"The hypothesis that territorium derives from terrere 'to frighten' would add a nuance of coercion; because scholars disagree, that layer is source uncertain.","cn":"认为 territorium 来自 terrere「使恐惧」的假说会附加“强制”意味；由于学者意见不一，该层来源不确定。"},{"era":"20C.","en":"Ethology gave the word its modern behavioural sense; studies of birds and mammals made territoriality a standard variable alongside density and food supply.","cn":"动物行为学赋予该词现代行为义；对鸟类与哺乳动物的研究使领域性成为与密度、食物供给并列的标准变量。"},{"era":"MODERN ENGLISH","en":"Modern usage spans law, ecology, psychology, and management; the word is usually uncountable, with a rare plural for types of territorial behaviour.","cn":"现代用法横跨法律、生态学、心理学与管理学；该词通常不可数，只有指不同类型领域行为时才偶用复数。"}]},"similar":{"note":{"en":"The first group separates noun relatives, the second compares concepts of exclusion and ownership.","cn":"第一组区分同族名词，第二组比较排斥与占有概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"territorial","ipa":"/ˌterəˈtɔːriəl/","tag":"derived adjective","definition":"the adjective describing the behaviour; territoriality is the abstract noun for the behaviour itself.","definitionCN":"描述该行为的形容词；territoriality 是行为本身的抽象名词。"},{"word":"territory","ipa":"/ˈterətri/","tag":"base noun","definition":"the area held; territoriality is the tendency to hold such areas.","definitionCN":"被持有的区域；territoriality 是持有这类区域的倾向。"},{"word":"terrestrial","ipa":"/təˈrestriəl/","tag":"same terra root","definition":"of land or the earth, not of defended space.","definitionCN":"陆地的或地球的，而非防卫空间的。"},{"word":"terror","ipa":"/ˈterə/","tag":"disputed root","definition":"extreme fear; its link to territory is only a disputed etymology.","definitionCN":"极度恐惧；与 territory 的联系只是存疑词源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dominance","ipa":"/ˈdɒmɪnəns/","tag":"social rank","definition":"priority of access to resources based on rank; territoriality is based on area instead.","definitionCN":"基于等级的优先资源获取；territoriality 则基于区域。"},{"word":"exclusivity","ipa":"/ˌekskluːˈsɪvəti/","tag":"general","definition":"the state of excluding others; it is broader and not tied to space.","definitionCN":"排斥他人的状态；更宽泛，且不与空间绑定。"},{"word":"home range","ipa":"/həʊm reɪndʒ/","tag":"ecology","definition":"the area an animal uses regularly but does not necessarily defend; territoriality implies defence.","definitionCN":"动物经常使用但不一定防卫的区域；territoriality 暗示防卫。"},{"word":"jurisdiction","ipa":"/ˌdʒʊərɪsˈdɪkʃn/","tag":"legal","definition":"the authority to govern; territoriality is the principle that this authority is bounded by land.","definitionCN":"治理的权力；territoriality 是这种权力受土地边界限制的原则。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffix stacking and standard terms in law and ecology.","cn":"正常联想：真实的后缀叠加，以及法律与生态学的标准术语。"},"normal":[{"en":"Territorial + -ity = the state of being territorial, just as active + -ity = activity.","cn":"territorial + -ity = 具有 territorial 性质的状态，正如 active + -ity = activity。"},{"en":"In law, the principle of territoriality says the place of the act decides the law.","cn":"法律中，principle of territoriality 指行为发生地决定适用法律。"},{"en":"In ecology, territoriality is measured as spacing produced by exclusion.","cn":"生态学中，领域性被度量为由排斥产生的间距。"},{"en":"Home range is used, territory is defended: the pair keeps the behavioural meaning precise.","cn":"home range 是被使用的，territory 是被防卫的：这对术语让行为义保持精确。"},{"en":"Office territoriality looks like animal territoriality because both defend a resource boundary.","cn":"办公室地盘之争像动物领域性，因为两者都在防卫资源边界。"}],"abstract":[{"en":"Picture a loop walked again and again: the walking is territorial behaviour, the loop is the territory, and the habit of walking it is territoriality.","cn":"想象一个反复绕行的圈：绕行是领域行为，圈是领地，绕行的习惯则是领域性。"},{"en":"The noun turns an adjective into a quantity: individuals can be more or less territorial, and the measure is how hard the boundary is enforced.","cn":"这个名词把形容词变成量：个体的领域性可强可弱，度量方式是边界被执行的力度。"},{"en":"The same abstract property serves a fish, a nation, and a department because all three convert 'inside' into a claim.","cn":"同一抽象属性适用于鱼、国家与部门，因为三者都把“内部”转化为一种主张。"}]},"examples":[{"en":"Territoriality in songbirds is strongest in spring, when nesting sites are scarce.","cn":"鸣禽的领域性在春季最强，此时巢址稀缺。"},{"en":"The legal principle of territoriality determines which country's tax rules apply.","cn":"属地原则决定适用哪一国的税收规则。"},{"en":"Territoriality between teams can block the flow of information.","cn":"团队之间的地盘意识会阻断信息流动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“特瑞托瑞阿乐提”——特别圈起一块地，谁进来都不乐意 → territoriality 领域性、地盘性","word":"territoriality"},"root":"territorial（领土的）+ -ity（状态、性质），词基为拉丁语 terra「土地」。","sensesIntro":{"en":"Eight senses of territoriality: the abstract property behind territory, ranging from animal spacing and human turf to legal jurisdiction, organizational protection, and measured defensiveness.","cn":"territoriality 的八个义项：territory 背后的抽象属性，从动物间距、人类地盘到法律管辖、组织保护与可度量的防卫强度。"},"semanticMap":{"core":{"en":"CORE IMAGE: an animal or person patrols a boundary and turns back outsiders.","cn":"核心意象：动物或人沿着边界巡视，把外来者挡回去。"},"chain":["AREA","CLAIM","PATROL","EXCLUSION","REGULAR SPACING","PROPERTY"],"branches":[{"senses":"S1 · S7","en":"ECOLOGY: defence of space becomes a spacing mechanism that ecologists can measure.","cn":"生态学：对空间的防卫变成一种可被生态学家度量的间距机制。"},{"senses":"S8","en":"DEGREE: the trait varies in strength, so territoriality is treated as a variable rather than a yes-or-no label.","cn":"强弱程度：这一特性有强弱之分，因此领域性被当作变量，而非非此即彼的标签。"},{"senses":"S2 · S5","en":"PSYCHOLOGY: seats and wells are felt as one's own, so intrusion produces irritation.","cn":"心理学：座位与水井被感受为自己的东西，因此他人的侵入会引发不快。"},{"senses":"S6","en":"ORGANIZATION: a department's function becomes its turf, defended like land.","cn":"组织：一个部门的职能变成它的地盘，像土地一样被防卫。"},{"senses":"S3 · S4","en":"LAW: authority is bounded by land, so location decides jurisdiction.","cn":"法律：权力以土地为界，因此地点决定管辖。"}]},"affixes":{"intro":{"en":"Territoriality stacks two Latinate suffixes on a borrowed noun: -ial makes the adjective, -ity makes the abstract noun of state. Both are productive in English.","cn":"territoriality 在借入名词上叠加两个拉丁来源后缀：-ial 构成形容词，-ity 构成表状态的抽象名词；两者在英语中都能产。"},"latinIntro":{"en":"Terra supplies territory and its family; the -ity suffix also forms activity, stability, and density, which is why territoriality fits technical writing.","cn":"terra 提供 territory 及其词族；-ity 后缀还构成 activity、stability、density，因此 territoriality 很适合技术写作。"},"items":[{"word":"territoriality","structure":"territorial + -ity (abstract noun)","meaning":"the property of being territorial","meaningCN":"具有领域性的性质（-ity 抽象名词）","example":"Territoriality varies with food density.","exampleCN":"领域性随食物密度变化。"},{"word":"territorial","structure":"territory + -ial (adjective)","meaning":"relating to territory","meaningCN":"与领土或领域有关的（-ial 形容词）","example":"Territorial defence is costly.","exampleCN":"领域防卫代价高昂。"},{"word":"territory","structure":"territorium (Latin noun)","meaning":"bounded land held by a claimant","meaningCN":"被主张者持有的有界土地","example":"The bird's territory is half a hectare.","exampleCN":"这只鸟的领域有半公顷。"},{"word":"territorialize","structure":"territorial + -ize (verb)","meaning":"to divide into territories","meaningCN":"划分为领地（-ize 动词）","example":"Males territorialize the reed bed.","exampleCN":"雄鸟把芦苇地划为领地。"},{"word":"territorially","structure":"territorial + -ly (adverb)","meaning":"in territorial terms","meaningCN":"在领土或领域方面","example":"The two groups are territorially separate.","exampleCN":"两个群体在领域上分开。"},{"word":"activity","structure":"-ity model word","meaning":"the state of being active; shows the same suffix pattern","meaningCN":"活跃的状态；展示同一后缀模式","example":"Activity peaks at dusk.","exampleCN":"活动在黄昏达到高峰。"},{"word":"stability","structure":"-ity model word","meaning":"the state of being stable","meaningCN":"稳定的状态","example":"Stability requires feedback.","exampleCN":"稳定需要反馈。"},{"word":"density","structure":"-ity model word","meaning":"the amount per unit area","meaningCN":"单位面积的数量；密度","example":"Density rises near the shore.","exampleCN":"近岸密度上升。"}],"latinEntries":[{"word":"terra","structure":"terra (first declension)","meaning":"earth, land","meaningCN":"土地；大地"},{"word":"territorium","structure":"terra + -orium","meaning":"land around a town","meaningCN":"城镇周围的土地"},{"word":"territorialis","structure":"territorium + -alis (adjective)","meaning":"of a territory","meaningCN":"领土的（拉丁形容词）"},{"word":"terrere","structure":"terrere (second conjugation)","meaning":"to frighten (disputed link)","meaningCN":"使恐惧（与 territory 的联系存疑）"}]}},{"word":"colonization","ipa_uk":"/ˌkɒlənaɪˈzeɪʃn/","ipa_us":"/ˌkɑːlənaɪˈzeɪʃn/","definition_zh":"殖民；殖民统治；定殖；定居","definition_en":"the process of establishing a settlement in a new place, or the process by which organisms occupy a new habitat","core_image":"一队人带着种子与工具，在陌生的土地上划出第一块田","scene":"火山喷发后，地衣与苔藓最先在冷却的熔岩上定居，为后来的植物准备土壤。 After the eruption, the colonization of the cooling lava by lichens and mosses prepared soil for later plants.","sceneCN":"这里 colonization 是「定殖、定居」（第 3 个义项：生物对新栖息地的占据）；句意：火山喷发后，地衣与苔藓对冷却熔岩的定殖为后来的植物准备了土壤。","pos":[{"tag":"n.","zh":"殖民；殖民统治；定殖；定居（多作不可数，指具体过程时可数）"}],"collocations":[{"phrase":"European colonization","zh":"欧洲殖民"},{"phrase":"colonization of new habitats","zh":"新栖息地的定殖"},{"phrase":"bacterial colonization","zh":"细菌定殖"},{"phrase":"colonization process","zh":"定殖过程"},{"phrase":"colonization resistance","zh":"定殖抗力"},{"phrase":"space colonization","zh":"太空殖民"}],"forms":[{"label":"复数（指多次或多种殖民过程）","form":"colonizations"},{"label":"动词","form":"colonize"},{"label":"名词（殖民地）","form":"colony"},{"label":"形容词","form":"colonial"}],"derivatives":[{"word":"colonize","pos":"v.","zh":"殖民；定殖；定居"},{"word":"colony","pos":"n.","zh":"殖民地；群体；菌落"},{"word":"colonial","pos":"adj.","zh":"殖民的；殖民地的"},{"word":"colonizer","pos":"n.","zh":"殖民者；定殖者"}],"senses":[{"no":"01","title":"Establishing a settlement","titleCN":"建立定居点","definition":"the act of founding and populating a new settlement in a distant place","definitionCN":"在远方建立并迁入人口到新定居点的行为","example":"The colonization of the island began with a single fishing village.","exampleCN":"该岛的殖民从一个渔村开始。","why":"From Latin colonia 'settled land, farm' and colonus 'tiller, settler', the verb first describes people who go to cultivate a new place. The noun names that whole process.","whyCN":"来自拉丁语 colonia「定居之地、农庄」与 colonus「耕种者、定居者」，动词最初描述前往新地方耕种的人；名词指整个这一过程。"},{"no":"02","title":"Rule by a distant power","titleCN":"外来政权的统治","definition":"the political process by which one country takes control of another land and its people","definitionCN":"一国控制另一片土地及其人民的过程","example":"Colonization reshaped borders, languages, and economies across the continent.","exampleCN":"殖民统治重塑了整个大陆的边界、语言与经济。","why":"The settlement sense acquired a power relation: settlers did not merely farm, they claimed sovereignty, so colonization became government from outside.","whyCN":"定居义带上了权力关系：定居者不只是耕种，还主张主权，于是 colonization 变成“由外部治理”。"},{"no":"03","title":"Biological occupation of a habitat","titleCN":"生物对新栖息地的占据","definition":"the process by which a species becomes established in an area where it was not previously present","definitionCN":"某物种在原先不存在的区域建立种群的过程","example":"The colonization of the new lake by fish took only three years.","exampleCN":"鱼类在新湖中的定殖只用了三年。","why":"Ecology borrows the settlement image without the politics: propagules arrive, survive, and reproduce, which is exactly 'founding a population' in a new place.","whyCN":"生态学借用了定居意象而剥离政治：繁殖体到达、存活并繁殖，这正是“在新地方建立种群”。"},{"no":"04","title":"Microbial establishment in a host","titleCN":"微生物在宿主中的定殖","definition":"the permanent or long-term presence of bacteria or fungi on or inside a host","definitionCN":"细菌或真菌在宿主表面或体内长期存在的状态","example":"Early microbial colonization shapes the infant's immune system.","exampleCN":"早期微生物定殖塑造婴儿的免疫系统。","why":"The habitat here is a body. Microbes adhere, multiply, and persist, so the same noun describes a biological settlement at a microscopic scale.","whyCN":"这里的栖息地是身体。微生物附着、繁殖并持续存在，因此同一名词描述微观尺度上的生物定居。"},{"no":"05","title":"Primary colonization of bare ground","titleCN":"对裸地的先锋定殖","definition":"the first occupation of bare rock, ash, or sand by pioneer organisms in succession","definitionCN":"演替中先锋生物首次占据裸岩、火山灰或沙地的过程","example":"Colonization of the ash field starts with nitrogen-fixing lichens.","exampleCN":"火山灰地的定殖从固氮地衣开始。","why":"In succession the word marks the beginning of a series: the first settlers alter the ground, and their change makes the next colonization possible.","whyCN":"在演替中，这个词标记一个序列的起点：首批定居者改变地面，而它们的改变使下一批定殖成为可能。"},{"no":"06","title":"Cultural or economic dominance","titleCN":"文化或经济上的支配","definition":"the spread of a dominant culture, language, or economy into another society","definitionCN":"优势文化、语言或经济向另一社会扩散","example":"Critics describe the global spread of advertising as a colonization of everyday life.","exampleCN":"批评者把广告的全球扩散描述为对日常生活的殖民。","why":"The political term is used metaphorically: a powerful system occupies a space that was organized by another culture, and the occupation changes its habits.","whyCN":"政治术语被比喻使用：强势系统占据由另一种文化组织起来的空间，并改变其习惯。"},{"no":"07","title":"Human settlement beyond Earth","titleCN":"地球之外的定居","definition":"the proposed establishment of permanent human communities on other planets or moons","definitionCN":"在其他行星或卫星上建立永久人类群落的设想","example":"Space colonization raises questions about law, resources, and reproduction.","exampleCN":"太空殖民提出法律、资源与生育等问题。","why":"The word's core 'found a settlement in a new land' is taken literally into space; only the scale of 'new land' changes.","whyCN":"这个词的核心“在新土地上建立定居点”被字面带入太空，改变的只是“新土地”的尺度。"},{"no":"08","title":"Linguistic spread and replacement","titleCN":"语言的扩散与替代","definition":"the process by which a language becomes established in a new territory, often at the expense of local languages","definitionCN":"语言在新领土上立足的过程，常以本地语言受损为代价","example":"The colonization of the region by a single language took two centuries.","exampleCN":"单一语言对该地区的语言殖民用了两个世纪。","why":"Language is treated as a settler: it arrives, takes root in schools and offices, and displaces existing speech, so the political metaphor extends to speech communities.","whyCN":"语言被当作定居者：它到达、在学校与机关扎根，并取代原有语言，于是政治隐喻延伸到言语社群。"}],"etymology":{"intro":{"en":"Colonization is an eighteenth-century noun from colonize, which goes back through colony to Latin colonia and colere 'to cultivate'. Dates are approximate; the deeper PIE root is reconstructed.","cn":"colonization 是 18 世纪由 colonize 构成的名词，经 colony 追溯到拉丁语 colonia 与 colere「耕种」。年代为大致估计；更深的原始印欧词根属于重构。"},"items":[{"era":"18C.","en":"The noun colonization is recorded in the eighteenth century, formed from colonize + -ation, in the sense 'the act of founding a colony'.","cn":"名词 colonization 于 18 世纪被记录，由 colonize + -ation 构成，义为“建立殖民地的行为”。"},{"era":"LATIN","en":"colony comes from Latin colonia 'settled land, farm, landed estate', from colonus 'tiller, tenant farmer, settler', from colere 'to cultivate, till, inhabit'.","cn":"colony 来自拉丁语 colonia「定居之地、农庄、地产」，来自 colonus「耕种者、佃农、定居者」，再来自 colere「耕种、居住」。"},{"era":"LATIN SENSE","en":"Colere meant not only to farm but to dwell in and to worship a place; Roman colonia were settlements of citizens in conquered or frontier land.","cn":"colere 不仅指耕种，还指居住与敬奉某地；罗马的 colonia 是在被征服或边疆土地上建立的公民定居点。"},{"era":"PROTO-INDO-EUROPEAN","en":"Colere is referred to the reconstructed root *kwel- 'to turn, move; dwell'. Because the root is reconstructed, the deepest layer is source uncertain.","cn":"colere 被归入重构词根 *kwel-「转动、移动；居住」。由于该词根是重构的，最深层来源不确定。"},{"era":"17C.–19C.","en":"Colonize first meant 'settle a place with colonists'; by the nineteenth century the noun covered both settlement and the political rule that followed it.","cn":"colonize 最初意为“让殖民者定居某地”；到 19 世纪，名词已同时覆盖定居与随之而来的政治统治。"},{"era":"MODERN ENGLISH","en":"Modern English uses colonization for human settlement, colonial rule, and biological establishment; ecology and microbiology added the technical senses in the twentieth century.","cn":"现代英语用 colonization 指人类定居、殖民统治与生物定殖；生态学与微生物学在 20 世纪增加了技术义。"}]},"similar":{"note":{"en":"The first group separates spelling and root neighbours, the second compares settlement terms.","cn":"第一组区分拼写与词根相近者，第二组比较表示定居的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"colonialism","ipa":"/kəˈləʊniəlɪzəm/","tag":"political system","definition":"the ideology and practice of holding colonies; colonization is the process, colonialism is the system.","definitionCN":"持有殖民地的意识形态与实践；colonization 是过程，colonialism 是体系。"},{"word":"colonial","ipa":"/kəˈləʊniəl/","tag":"derived adjective","definition":"relating to a colony; the adjective of both colony and colonization.","definitionCN":"与殖民地有关的；colony 与 colonization 的形容词。"},{"word":"colonnade","ipa":"/ˌkɒləˈneɪd/","tag":"different root","definition":"a row of columns, from Latin columna 'pillar'. The shared col- is accidental.","definitionCN":"一排柱子，来自拉丁语 columna「柱」。共享的 col- 只是巧合。"},{"word":"colon","ipa":"/ˈkəʊlən/","tag":"different root, anatomy","definition":"the large intestine, from Greek kolon. It has no connection with settlement.","definitionCN":"大肠，来自希腊语 kolon。与定居无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"settlement","ipa":"/ˈsetlmənt/","tag":"neutral","definition":"the founding of a community; it lacks the power relation that colonization often carries.","definitionCN":"建立社群；缺少 colonization 常带的权力关系。"},{"word":"occupation","ipa":"/ˌɒkjuˈpeɪʃn/","tag":"control","definition":"the holding of a territory by force; it stresses military presence rather than settlement.","definitionCN":"以武力控制领土；强调军事存在而非定居。"},{"word":"migration","ipa":"/maɪˈɡreɪʃn/","tag":"movement","definition":"movement of people or animals to a new place; colonization is establishment after arrival.","definitionCN":"人或动物迁往新地方；colonization 是到达后的建立。"},{"word":"establishment","ipa":"/ɪˈstæblɪʃmənt/","tag":"biology","definition":"the successful founding of a population; it is the ecological synonym of colonization.","definitionCN":"种群成功建立；是 colonization 的生态同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin parts, standard historical phrases, and real ecological terms.","cn":"正常联想：真实的拉丁语成分、标准历史短语与真实生态术语。"},"normal":[{"en":"colere means to cultivate: colonization literally begins with someone tilling new ground.","cn":"colere 意为耕种：colonization 字面上从有人开垦新地开始。"},{"en":"Colonia was a Roman settlement of citizens; the modern word inherits both the farm and the flag.","cn":"colonia 是罗马公民的定居点；现代词同时继承了农田与旗帜。"},{"en":"In ecology, colonization is the first stage before succession: arrive, survive, reproduce.","cn":"生态学中，colonization 是演替之前的第一阶段：到达、存活、繁殖。"},{"en":"Bacterial colonization is a standard medical phrase for microbes settling on a host.","cn":"bacterial colonization 是微生物在宿主定殖的标准医学短语。"},{"en":"Colonialism is the system; colonization is the process that builds it.","cn":"colonialism 是体系；colonization 是建立该体系的过程。"}],"abstract":[{"en":"Picture a wagon arriving at an empty valley: the wheels stop, a field is cleared, and a boundary is drawn. All of that is colonization.","cn":"想象一辆马车抵达空谷：车轮停下，一块田被清出，一条边界被画出。这一切就是 colonization。"},{"en":"The word travels from farms to empires to microbes because each case is 'a new population taking hold in a new place'.","cn":"这个词从农庄走到帝国再到微生物，因为每种情形都是“新群体在新地方立足”。"},{"en":"Removing the politics leaves a neutral biological core: arrival plus persistence plus reproduction.","cn":"剥离政治后剩下中性生物核心：到达、持续、繁殖。"}]},"examples":[{"en":"The colonization of the Americas transformed both settlers and indigenous societies.","cn":"美洲的殖民同时改变了定居者与原住民社会。"},{"en":"Root colonization by fungi improves phosphorus uptake in most crops.","cn":"真菌对根部的定殖提高了大多数作物的磷吸收。"},{"en":"The first colonization of the bare moraine was by mosses and lichens.","cn":"裸冰碛地的首次定殖由苔藓与地衣完成。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“靠了米来”——靠了米粮才有力气去开垦新地、建立定居点 → colonization 殖民、定殖","word":"colonization"},"root":"拉丁语 colonia「定居之地、农庄」，来自 colere「耕种、居住」，与 colony、colonial 同族。","sensesIntro":{"en":"Eight senses of colonization: settlement, rule, biological establishment, microbial persistence, pioneer succession, cultural dominance, space settlement, and language spread.","cn":"colonization 的八个义项：定居、统治、生物建立、微生物持续存在、先锋演替、文化支配、太空定居与语言扩散。"},"semanticMap":{"core":{"en":"CORE IMAGE: settlers arrive, clear ground, and found a lasting community.","cn":"核心意象：定居者到达、清理地面并建立持久社群。"},"chain":["ARRIVAL","CLEARING","SETTLEMENT","REPRODUCTION","PERSISTENCE","TRANSFORMATION"],"branches":[{"senses":"S1 · S2","en":"HUMAN HISTORY: a farming settlement hardens into rule by a distant power.","cn":"人类历史：农业定居点逐渐固化为远方政权的统治。"},{"senses":"S3 · S5","en":"HABITAT OCCUPATION: a population takes hold on open or bare ground and persists there.","cn":"栖息地占据：种群在开阔或裸露的地面上立足并持续存在。"},{"senses":"S4","en":"HOSTS: a microbe establishes itself inside a host, the same action at a smaller scale.","cn":"宿主：微生物在宿主体内建立自身种群，是同一动作在更小尺度上的版本。"},{"senses":"S6 · S8","en":"CULTURE: dominant practices and languages occupy social space.","cn":"文化：占主导的实践与语言占据社会空间。"},{"senses":"S7","en":"SPACE: the same settlement logic is projected onto other worlds.","cn":"太空：同一套定居逻辑被投射到其他星球上。"}]},"affixes":{"intro":{"en":"Colonization is colonize + -ation. The base colon- is Latin; -ize and -ation are productive English suffixes, so the word is a transparent modern construction on a Latin root.","cn":"colonization 是 colonize + -ation。词基 colon- 属拉丁语；-ize 与 -ation 是能产的英语后缀，因此该词是在拉丁词根上的透明现代构造。"},"latinIntro":{"en":"Latin colere 'to cultivate' also gives colony, colonial, colonist, and agriculture's 'culture'; the unrelated colon (intestine) and colonnade (columns) must be kept apart.","cn":"拉丁语 colere「耕种」还衍生 colony、colonial、colonist 以及 agriculture 中的 culture；无关的 colon（大肠）与 colonnade（柱廊）必须分开。"},"items":[{"word":"colonization","structure":"colonize + -ation (noun of process)","meaning":"the process of founding a colony","meaningCN":"建立殖民地的过程（-ation 过程名词）","example":"Colonization changed the island's forests.","exampleCN":"殖民改变了该岛的森林。"},{"word":"colonize","structure":"colony + -ize (verb)","meaning":"to settle or establish in a new place","meaningCN":"在新地方定居或建立（-ize 动词）","example":"Plants colonized the lava within a decade.","exampleCN":"植物在十年内定殖了熔岩地。"},{"word":"colony","structure":"colonia (Latin noun)","meaning":"a settlement or dependent territory","meaningCN":"定居点或属地","example":"The colony declared independence.","exampleCN":"该殖民地宣布独立。"},{"word":"colonial","structure":"colony + -al (adjective)","meaning":"relating to a colony","meaningCN":"与殖民地有关的（-al 形容词）","example":"Colonial rule lasted seventy years.","exampleCN":"殖民统治持续了七十年。"},{"word":"colonizer","structure":"colonize + -er (agent noun)","meaning":"one that colonizes","meaningCN":"殖民者；定殖者（-er 施事名词）","example":"The colonizers brought new crops.","exampleCN":"殖民者带来了新作物。"},{"word":"colonialism","structure":"colonial + -ism (system noun)","meaning":"the system of holding colonies","meaningCN":"持有殖民地的体系（-ism 体系名词）","example":"Colonialism reshaped local economies.","exampleCN":"殖民主义重塑了当地经济。"},{"word":"culture","structure":"colere + -tura (cultivation)","meaning":"cultivation, hence learned ways of life","meaningCN":"耕种，引申为文化（-tura 名词）","example":"Soil culture and human culture share a root.","exampleCN":"土壤栽培与人类文化共享一个词根。"},{"word":"agriculture","structure":"ager (field) + cultura (cultivation)","meaning":"field cultivation","meaningCN":"农田耕作","example":"Agriculture began in river valleys.","exampleCN":"农业起源于河谷。"}],"latinEntries":[{"word":"colere","structure":"colere (third conjugation)","meaning":"to till, cultivate, inhabit, worship","meaningCN":"耕种；居住；敬奉"},{"word":"colonus","structure":"colere + -onus (agent)","meaning":"tiller, settler","meaningCN":"耕种者；定居者"},{"word":"colonia","structure":"colonus + -ia (place/collective)","meaning":"settled land; colony","meaningCN":"定居之地；殖民地"},{"word":"cultura","structure":"colere + -tura (result noun)","meaning":"cultivation; care","meaningCN":"耕作；照料"}]}},{"word":"colonize","ipa_uk":"/ˈkɒlənaɪz/","ipa_us":"/ˈkɑːlənaɪz/","definition_zh":"在……殖民；使定居；定殖于；占据","definition_en":"to establish a colony in a place, or for a species or microbe to become established in a new habitat","core_image":"第一批定居者把种子撒进陌生土地，并在此扎根","scene":"一种来自亚洲的灌木在废弃牧场迅速扎根，十年内占据了整片山坡。 A shrub from Asia took root quickly in the abandoned pasture and colonized the whole slope within ten years.","sceneCN":"这里 colonize 是「定殖于、占据」（第 2 个义项：物种在新栖息地建立种群）；句意：一种来自亚洲的灌木在废弃牧场迅速扎根，十年内定殖了整片山坡。","pos":[{"tag":"vt.","zh":"在……建立殖民地；使定居；定殖于"},{"tag":"vi.","zh":"建立殖民地；定殖"}],"collocations":[{"phrase":"colonize a continent","zh":"在某个大陆殖民"},{"phrase":"colonize new habitats","zh":"定殖新栖息地"},{"phrase":"colonize the gut","zh":"定殖肠道"},{"phrase":"colonize bare rock","zh":"定殖裸岩"},{"phrase":"be colonized by","zh":"被……定殖"},{"phrase":"rapidly colonize","zh":"迅速定殖"}],"forms":[{"label":"三单（he/she/it）","form":"colonizes"},{"label":"过去式（已经发生）","form":"colonized"},{"label":"过去分词（完成／被动）","form":"colonized"},{"label":"现在分词（进行体）","form":"colonizing"}],"derivatives":[{"word":"colonization","pos":"n.","zh":"殖民；定殖"},{"word":"colony","pos":"n.","zh":"殖民地；群体；菌落"},{"word":"colonizer","pos":"n.","zh":"殖民者；定殖生物"},{"word":"colonial","pos":"adj.","zh":"殖民的；殖民地的"}],"senses":[{"no":"01","title":"Found a settlement in a new land","titleCN":"在新土地上建立定居点","definition":"to send people to live in and take control of a distant territory","definitionCN":"派人到远方领土居住并取得控制","example":"The empire colonized the coast before moving inland.","exampleCN":"帝国先殖民海岸，再向内地推进。","why":"From Latin colonia 'settled land' and colere 'to cultivate', the verb begins as 'to plant people as a settlement', much as one plants a crop.","whyCN":"来自拉丁语 colonia「定居之地」与 colere「耕种」，动词最初就是“把人像作物一样种成定居点”。"},{"no":"02","title":"Establish a population in a habitat","titleCN":"在栖息地建立种群","definition":"for a species to arrive, survive, and reproduce in an area where it was absent","definitionCN":"某物种到达、存活并在原本没有它的区域繁殖","example":"The grass colonized the disturbed soil within one season.","exampleCN":"这种草在一个季节内就定殖了受扰动的土壤。","why":"Ecology keeps the agricultural image: propagules are 'planted' by wind or animals, and colonization succeeds only if they reproduce.","whyCN":"生态学保留农业意象：繁殖体由风或动物“种下”，只有成功繁殖才算定殖。"},{"no":"03","title":"Impose rule over a people","titleCN":"对人民实施统治","definition":"to take political control of another land and govern its inhabitants","definitionCN":"取得另一片土地的政治控制并治理其居民","example":"A small force can colonize a region only with local allies.","exampleCN":"一支小部队只有借助当地盟友才能殖民一个地区。","why":"The settlement verb acquires a coercive sense when the settlers claim sovereignty; 'colonize' then means to govern from outside, not merely to live there.","whyCN":"当定居者主张主权时，定居动词带上强制义；colonize 于是指“由外部治理”，而不只是住在那里。"},{"no":"04","title":"Microbes establish on a host","titleCN":"微生物在宿主上定殖","definition":"for bacteria or fungi to adhere to and persist on or in a host","definitionCN":"细菌或真菌附着并持续存在于宿主表面或体内","example":"Certain gut bacteria colonize the intestine within hours of birth.","exampleCN":"某些肠道细菌在出生后数小时内就定殖肠道。","why":"The host is a habitat. Adhesion is arrival, growth is reproduction, and persistence without clearance is successful colonization.","whyCN":"宿主就是栖息地。附着是到达，增殖是繁殖，未被清除而持续存在就是成功定殖。"},{"no":"05","title":"Occupy bare ground first","titleCN":"率先占据裸地","definition":"for pioneer organisms to be the first to settle bare rock, ash, or sand","definitionCN":"先锋生物首先定居裸岩、火山灰或沙地","example":"Lichens colonize rock surfaces that no plant can root in.","exampleCN":"地衣能定殖任何植物都无法扎根的岩石表面。","why":"In succession the verb marks the first step: the pioneer alters the substrate, and that alteration lets later species colonize.","whyCN":"在演替中，这个动词标记第一步：先锋改变基质，而这一改变让后来的物种得以定殖。"},{"no":"06","title":"Take over a social or cultural space","titleCN":"占据社会或文化空间","definition":"in figurative use, to spread into and dominate an activity, market, or way of life","definitionCN":"用于比喻，指扩散进入并支配某项活动、市场或生活方式","example":"Online retail has colonized the small-town high street.","exampleCN":"网络零售已占据小镇的商业街。","why":"The political verb is used metaphorically for any system that moves into a space organized by others and reshapes it.","whyCN":"这个政治动词被比喻用于任何进入他人组织的空间并重塑它的系统。"},{"no":"07","title":"Settle other planets","titleCN":"定居其他星球","definition":"to establish permanent human presence on a planet, moon, or asteroid","definitionCN":"在行星、卫星或小行星上建立永久人类存在","example":"Engineers debate how to colonize Mars without contaminating it.","exampleCN":"工程师争论如何在不污染火星的情况下殖民火星。","why":"The original 'new land' sense is taken literally beyond Earth; only the destination is new, while the pattern of arrival and settlement is unchanged.","whyCN":"原本的“新土地”义被字面带入地球之外；只有目的地是新的，到达与定居的模式并未改变。"},{"no":"08","title":"Adopt a place as one's own","titleCN":"把某地当作自己的地盘","definition":"in informal use, to make a place one's regular haunt or territory","definitionCN":"非正式用法中，把某地变成自己常去的地盘","example":"The chess players have colonized the corner table of the cafe.","exampleCN":"棋手们已经把咖啡馆角落的桌子占为自己的地盘。","why":"The word's exclusionary edge survives in this light sense: a group settles in and, by habit, makes the space feel like theirs.","whyCN":"这个词的排斥性边缘在轻松用法中仍在：一群人在此落脚，并通过习惯让这片空间感觉像他们的。"}],"etymology":{"intro":{"en":"Colonize is a seventeenth-century English verb built on colony, from Latin colonia and colere. The PIE root behind colere is reconstructed, so the deepest layer is uncertain.","cn":"colonize 是 17 世纪在 colony 基础上构成的英语动词，源自拉丁语 colonia 与 colere。colere 背后的原始印欧词根是重构，最深层不确定。"},"items":[{"era":"17C.","en":"Colonize is recorded in the seventeenth century meaning 'to settle (a place) with colonists'; the intransitive 'to form a colony' follows later.","cn":"colonize 于 17 世纪被记录，义为“让殖民者定居某地”；不及物义“建立殖民地”稍后出现。"},{"era":"LATIN","en":"colony < Latin colonia 'settled land, farm', from colonus 'tiller, settler', from colere 'to cultivate, inhabit'.","cn":"colony < 拉丁语 colonia「定居之地、农庄」，来自 colonus「耕种者、定居者」，再来自 colere「耕种、居住」。"},{"era":"MORPHOLOGY","en":"English added -ize to the noun colony, a productive verb-forming suffix; the same pattern gives modernize, organize, and stabilize.","cn":"英语在名词 colony 上加 -ize 这一能产动词后缀；同一模式构成 modernize、organize、stabilize。"},{"era":"PROTO-INDO-EUROPEAN","en":"Colere is conventionally traced to *kwel- 'to turn, move; dwell'. Since the root is a reconstruction, the deepest etymology is source uncertain.","cn":"colere 通常被追溯到 *kwel-「转动、移动；居住」。由于该词根是重构，最深层词源来源不确定。"},{"era":"19C.–20C.","en":"The verb extended to political domination and, in the twentieth century, to ecological and microbiological establishment.","cn":"该动词扩展到政治支配，并在 20 世纪扩展到生态学与微生物学的“建立”。"},{"era":"MODERN ENGLISH","en":"Modern English uses colonize for people, species, microbes, markets, and planets; the spelling colonise is British and colonize American.","cn":"现代英语用 colonize 指人、物种、微生物、市场与行星；英式拼写为 colonise，美式为 colonize。"}]},"similar":{"note":{"en":"The first group separates root neighbours, the second compares verbs of settlement and occupation.","cn":"第一组区分同根近邻，第二组比较表示定居与占据的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"colonization","ipa":"/ˌkɒlənaɪˈzeɪʃn/","tag":"derived noun","definition":"the process or result of colonizing; the verb names the action, the noun the whole process.","definitionCN":"定殖或殖民的过程与结果；动词指动作，名词指整个过程。"},{"word":"colony","ipa":"/ˈkɒləni/","tag":"base noun","definition":"the settlement or group itself; colonize is what produces a colony.","definitionCN":"定居点或群体本身；colonize 是产生 colony 的动作。"},{"word":"colon","ipa":"/ˈkəʊlən/","tag":"different root","definition":"the large intestine, from Greek kolon; unrelated to settlement.","definitionCN":"大肠，来自希腊语 kolon；与定居无关。"},{"word":"colonnade","ipa":"/ˌkɒləˈneɪd/","tag":"different root","definition":"a row of columns, from columna; the resemblance is accidental.","definitionCN":"一排柱子，来自 columna；相似只是巧合。"}]},{"heading":"NEAR MEANING","entries":[{"word":"settle","ipa":"/ˈsetl/","tag":"neutral","definition":"to make a permanent home in a place; it lacks the control and exclusion senses.","definitionCN":"在某地安家；缺少控制与排斥义。"},{"word":"occupy","ipa":"/ˈɒkjupaɪ/","tag":"control","definition":"to hold or live in a place, often by force; it stresses presence rather than founding.","definitionCN":"占据或居住某地，常以武力；强调在场而非建立。"},{"word":"invade","ipa":"/ɪnˈveɪd/","tag":"force","definition":"to enter a territory with an army; colonize may involve settlement, invasion only entry by force.","definitionCN":"以军队进入领土；colonize 可能包含定居，invade 只是武力进入。"},{"word":"infest","ipa":"/ɪnˈfest/","tag":"pests","definition":"for pests or parasites to overrun a place; it is negative where colonize is technical.","definitionCN":"害虫或寄生物大批侵扰；带负面色彩，而 colonize 是技术中性词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes, standard phrases, and real relatives.","cn":"正常联想：真实后缀、标准搭配与真实同族词。"},"normal":[{"en":"colony + -ize = to make a colony, just as modern + -ize = to make modern.","cn":"colony + -ize = 使成为殖民地，正如 modern + -ize = 使现代化。"},{"en":"Ecology says a species colonizes a habitat when it arrives and reproduces there.","cn":"生态学中，物种到达并在栖息地繁殖，才叫 colonize。"},{"en":"Bacteria colonize the gut: adhesion first, then growth, then persistence.","cn":"细菌定殖肠道：先附着，再增殖，再持续存在。"},{"en":"Lichens colonize bare rock as the first step of succession.","cn":"地衣定殖裸岩，是演替的第一步。"},{"en":"Colonise is the British spelling, colonize the American; the meaning is identical.","cn":"colonise 是英式拼写，colonize 是美式拼写，意义相同。"}],"abstract":[{"en":"Picture a first furrow cut into virgin soil: the blade opens ground, and a settlement follows the line. Colonize is that first cut repeated.","cn":"想象在处女地上划出第一道犁沟：犁刀开土，定居点沿着这条线出现。colonize 就是这道第一刀的重复。"},{"en":"The verb needs reproduction, not just arrival: a visitor is not a colonist unless the population persists.","cn":"这个动词需要繁殖而不只是到达：过客不是殖民者，除非种群持续存在。"},{"en":"The same verb covers a farm, a germ, and a marketplace because each is a new space made habitual.","cn":"同一动词覆盖农庄、病菌与市场，因为每一项都是被“习惯化”的新空间。"}]},"examples":[{"en":"European powers colonized much of the region in the nineteenth century.","cn":"19 世纪欧洲列强殖民了该地区的大部分。"},{"en":"The alga colonizes coral rubble after storms.","cn":"这种藻在风暴后定殖珊瑚碎块。"},{"en":"A few bacterial strains colonize the newborn gut within days.","cn":"少数菌株在数日内定殖新生儿肠道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“靠了耐死”——靠了耐力在陌生土地上活下来、扎下根 → colonize 殖民、定殖","word":"colonize"},"root":"拉丁语 colonia「定居之地」+ 英语动词后缀 -ize；词根 colere「耕种、居住」。","sensesIntro":{"en":"Eight senses of colonize: found a settlement, establish a population, rule a people, settle microbes, occupy bare ground, take over a social space, settle other planets, and adopt a haunt.","cn":"colonize 的八个义项：建立定居点、建立种群、统治人民、微生物定殖、占据裸地、占据社会空间、定居其他星球与把某地当作地盘。"},"semanticMap":{"core":{"en":"CORE IMAGE: a first furrow is cut and people or organisms take root along it.","cn":"核心意象：第一道犁沟被划开，人或生物沿着它扎根。"},"chain":["NEW SPACE","ARRIVAL","ROOTING","REPRODUCTION","PERSISTENCE","CONTROL OR HABIT"],"branches":[{"senses":"S1 · S3","en":"HUMAN SETTLEMENT: living in a place slides into governing it.","cn":"人类定居：在一个地方生活，逐步滑向对它的统治。"},{"senses":"S2 · S5","en":"NEW GROUND: a population roots and reproduces on open or bare substrate.","cn":"新土地：种群在开阔或裸露的基质上扎根并繁殖。"},{"senses":"S4","en":"HOSTS: microbes settle on or in a host and multiply there.","cn":"宿主：微生物在宿主表面或体内定居并增殖。"},{"senses":"S6 · S8","en":"SOCIAL SPACE: systems and habits take over places organized by others.","cn":"社会空间：制度与习惯接管由他人组织的场所。"},{"senses":"S7","en":"SPACE: the same settlement pattern is imagined on other worlds.","cn":"太空：同一套定居模式被想象到其他星球上。"}]},"affixes":{"intro":{"en":"Colonize is colony + -ize, a fully productive English pattern. The Latin base colon- is opaque to modern speakers but still visible in colony and colonial.","cn":"colonize 是 colony + -ize，属于完全能产的英语模式。拉丁词基 colon- 对现代使用者不透明，但在 colony 与 colonial 中仍可见。"},"latinIntro":{"en":"Colere 'cultivate' yields colony, colonial, colonist, culture, and agriculture; unrelated homographs colon (intestine) and colonnade (columns) are common traps.","cn":"colere「耕种」衍生 colony、colonial、colonist、culture、agriculture；无关的同形词 colon（大肠）与 colonnade（柱廊）是常见陷阱。"},"items":[{"word":"colonize","structure":"colony + -ize (verb)","meaning":"to found or establish a colony","meaningCN":"建立殖民地；定殖（-ize 动词）","example":"Weeds colonize disturbed fields first.","exampleCN":"杂草首先定殖受扰动的田地。"},{"word":"colonized","structure":"colonize + -ed (past participle)","meaning":"settled or occupied by a colony","meaningCN":"被殖民的；被定殖的","example":"The colonized coast lost its old ports.","exampleCN":"被殖民的海岸失去了旧港口。"},{"word":"colonizing","structure":"colonize + -ing (participle/adjective)","meaning":"in the act of establishing","meaningCN":"正在定殖的；殖民的","example":"Colonizing ants spread across the clearing.","exampleCN":"定殖蚁群散布到空地各处。"},{"word":"colonization","structure":"colonize + -ation (noun)","meaning":"the process of establishing","meaningCN":"定殖或殖民的过程","example":"Colonization followed the trade routes.","exampleCN":"殖民沿贸易路线展开。"},{"word":"colonizer","structure":"colonize + -er (agent)","meaning":"a person, species, or state that colonizes","meaningCN":"殖民者；定殖者","example":"The colonizers introduced new grasses.","exampleCN":"殖民者引入了新草种。"},{"word":"colony","structure":"colonia (Latin noun)","meaning":"the settlement or group established","meaningCN":"被建立的定居点或群体","example":"The ant colony has one queen.","exampleCN":"这个蚁群只有一只蚁后。"},{"word":"colonial","structure":"colony + -al (adjective)","meaning":"of a colony","meaningCN":"殖民地的（-al 形容词）","example":"Colonial architecture remains.","exampleCN":"殖民地建筑仍在。"},{"word":"culture","structure":"colere + -tura","meaning":"cultivation; learned life","meaningCN":"耕作；文化","example":"Culture and cultivation share a root.","exampleCN":"文化与耕作共享一个词根。"}],"latinEntries":[{"word":"colere","structure":"colere (third conjugation)","meaning":"to till, cultivate, inhabit","meaningCN":"耕种；居住"},{"word":"colonus","structure":"colere + -onus","meaning":"tiller, settler","meaningCN":"耕种者；定居者"},{"word":"colonia","structure":"colonus + -ia","meaning":"settled land, colony","meaningCN":"定居之地；殖民地"},{"word":"cultura","structure":"colere + -tura","meaning":"cultivation, care","meaningCN":"耕作；照料"}]}},{"word":"colony","ipa_uk":"/ˈkɒləni/","ipa_us":"/ˈkɑːləni/","definition_zh":"殖民地；定居群体；（动物）群体；菌落","definition_en":"a territory settled and governed by another country, a group of people or animals living together, or a group of microorganisms growing in one place","core_image":"一片被外来旗帜标记的土地，或一群同住一处的生物","scene":"在这片雨林里，切叶蚁建立了一个有数百万个体的群体，巢穴分布在数十平方米内。 In this rainforest, leaf-cutter ants have built a colony of millions of individuals, with nests spread over dozens of square metres.","sceneCN":"这里 colony 是「（动物的）群体」（第 3 个义项：同种个体共同生活的群体）；句意：在这片雨林里，切叶蚁建立了一个数百万个体的群体，巢穴分布在数十平方米内。","pos":[{"tag":"n.","zh":"殖民地；定居地；（人、动物）群体；菌落（可数，复数为 colonies）"}],"collocations":[{"phrase":"British colony","zh":"英国殖民地"},{"phrase":"ant colony","zh":"蚁群"},{"phrase":"breeding colony","zh":"繁殖群；繁殖地群体"},{"phrase":"bacterial colony","zh":"细菌菌落"},{"phrase":"form a colony","zh":"形成群体"},{"phrase":"colony of artists","zh":"艺术家聚居地"}],"forms":[{"label":"复数","form":"colonies"},{"label":"动词（殖民）","form":"colonize"},{"label":"名词（殖民过程）","form":"colonization"},{"label":"形容词（殖民的）","form":"colonial"}],"derivatives":[{"word":"colonize","pos":"v.","zh":"殖民；定殖"},{"word":"colonization","pos":"n.","zh":"殖民；定殖"},{"word":"colonial","pos":"adj.","zh":"殖民的；殖民地的"},{"word":"colonist","pos":"n.","zh":"殖民者；定居者"}],"senses":[{"no":"01","title":"Territory settled by another country","titleCN":"由他国建立并治理的领地","definition":"a territory settled by people from another country and governed by that country","definitionCN":"由来自另一国的人定居、并由该国治理的领土","example":"The colony gained self-rule after a long campaign.","exampleCN":"经过长期运动，这块殖民地获得了自治。","why":"Latin colonia was a settlement of citizens on new land, from colonus 'tiller' and colere 'to cultivate'. The political sense grew when such settlements were ruled from a distant capital.","whyCN":"拉丁语 colonia 是公民在新土地上的定居点，来自 colonus「耕种者」与 colere「耕种」。当这些定居点由远方首都治理时，政治义随之产生。"},{"no":"02","title":"A group of settlers","titleCN":"定居者群体","definition":"the community of settlers themselves, not the land they occupy","definitionCN":"定居者组成的社群本身，而非他们占据的土地","example":"The first colony survived on fish and imported grain.","exampleCN":"第一批定居者靠鱼与进口谷物生存。","why":"Colonia could mean both the settlement and its people; English keeps that ambiguity, so colony may refer to the place or the community.","whyCN":"colonia 既可指定居点也可指其中的人；英语保留这种模糊性，因此 colony 可指地方或社群。"},{"no":"03","title":"A group of animals living together","titleCN":"共同生活的动物群体","definition":"a community of animals of one species that live and cooperate in a shared nest or site","definitionCN":"同种动物在共同巢址生活并协作的群体","example":"A honeybee colony can regulate its own temperature.","exampleCN":"一个蜜蜂群体能自行调节温度。","why":"The biological sense borrows the social image: many individuals live in one 'settlement', divide labour, and reproduce as a unit.","whyCN":"生物义借用了社会意象：许多个体住在一个“定居点”里，分工并作为一个单位繁殖。"},{"no":"04","title":"A microbial colony on a surface","titleCN":"表面上的微生物菌落","definition":"a visible cluster of microorganisms grown from one cell or a few cells on a medium","definitionCN":"由单个或少数细胞在培养基上长成的可见微生物集团","example":"Each colony on the plate came from one bacterium.","exampleCN":"培养皿上的每个菌落都来自一个细菌。","why":"Microbiology uses the word for a cluster founded by one cell: the 'settlement' is literally the descendants of a single colonist.","whyCN":"微生物学用这个词指由一个细胞建立的集团：“定居点”字面上就是单个定殖者的后代。"},{"no":"05","title":"An artists' or writers' community","titleCN":"艺术家或作家的聚居群体","definition":"a group of artists, writers, or like-minded people living and working in one place","definitionCN":"艺术家、作家或志趣相投者在一处生活工作的群体","example":"The coastal colony attracted painters in the 1920s.","exampleCN":"这座海滨聚居地在 20 年代吸引了画家。","why":"The 'community of settlers' sense is applied to culture: a group occupies a place, shares habits, and produces a recognizable local scene.","whyCN":"“定居者社群”义被用于文化：一群人在某地落脚、共享习惯，并形成可辨识的地方场景。"},{"no":"06","title":"A breeding or nesting aggregation","titleCN":"繁殖或营巢聚集地","definition":"a large gathering of animals at a specific site for breeding, nesting, or roosting","definitionCN":"动物为繁殖、营巢或栖息在特定地点的大量聚集","example":"The island hosts a colony of terns each summer.","exampleCN":"每年夏天，这座岛上有大量燕鸥聚集繁殖。","why":"Here colony names a place-based aggregation rather than a society: the bond is shared location and season, not division of labour.","whyCN":"这里 colony 指基于地点的聚集而非社会：纽带是共同地点与季节，而不是分工。"},{"no":"07","title":"A Roman or Greek colonial foundation","titleCN":"罗马或希腊的殖民城邦","definition":"in ancient history, a city founded by citizens of another city-state","definitionCN":"古代史中由另一城邦公民建立的城市","example":"Greek colonies spread from the Aegean to the Black Sea.","exampleCN":"希腊殖民城邦从爱琴海扩展到黑海。","why":"This is the word's oldest documented layer: a new city founded by a mother city, which explains why both 'settlement' and 'dependency' survive.","whyCN":"这是该词最早有记录的一层：由母邦建立的新城，这解释了为何“定居点”与“属地”两义都保留下来。"},{"no":"08","title":"An isolated community, as in a leper colony","titleCN":"隔离社群，如麻风村","definition":"a segregated community established for people with a disease or for a specific group","definitionCN":"为某种疾病患者或特定群体设立的隔离社群","example":"The old leper colony stood on the headland for a century.","exampleCN":"旧麻风村在海岬上存在了一个世纪。","why":"The settlement sense takes on exclusion: a group is placed apart from the main society, so 'colony' can name a place of separation rather than expansion.","whyCN":"定居义带上了排斥：一群人被安置在主流社会之外，于是 colony 可指分隔之地，而非扩张之地。"}],"etymology":{"intro":{"en":"Colony came into English from Latin colonia, a settlement of citizens, through Old French. Its base colere 'to cultivate' is well attested; the PIE root behind it is reconstructed.","cn":"colony 经由古法语从拉丁语 colonia（公民定居点）进入英语。词基 colere「耕种」有充分记录；其背后的原始印欧词根是重构。"},"items":[{"era":"LATE 14C.","en":"English colony is recorded in the late fourteenth century, first for ancient Roman settlements and then for contemporary overseas settlements.","cn":"英语 colony 于 14 世纪晚期被记录，先指古罗马定居点，后指当代海外定居点。"},{"era":"LATIN","en":"From Latin colonia 'settled land, farm, landed estate', from colonus 'tiller, tenant farmer, settler', from colere 'to cultivate, till, inhabit'.","cn":"来自拉丁语 colonia「定居之地、农庄、地产」，来自 colonus「耕种者、佃农、定居者」，再来自 colere「耕种、居住」。"},{"era":"ROMAN CONTEXT","en":"A Roman colonia was a settlement of citizens, often veterans, planted in conquered or frontier territory; the word therefore carried both 'new farm' and 'outpost of the state'.","cn":"罗马的 colonia 是安置在被征服或边疆地区的公民定居点，常为老兵；因此该词同时带有“新农庄”与“国家前哨”之意。"},{"era":"PROTO-INDO-EUROPEAN","en":"Colere is conventionally referred to *kwel- 'to turn, move; dwell'. This is a reconstructed root, so the deepest layer is source uncertain.","cn":"colere 通常被归入 *kwel-「转动、移动；居住」。这是重构词根，故最深层来源不确定。"},{"era":"17C.–19C.","en":"Overseas expansion fixed the political sense 'territory ruled by another country'; naturalists then borrowed colony for animal and microbial groups.","cn":"海外扩张固定了“由他国治理的领土”这一政治义；博物学者随后借 colony 指动物与微生物群体。"},{"era":"MODERN ENGLISH","en":"Modern English uses colony across politics, sociobiology, microbiology, and culture; the plural colonies is regular.","cn":"现代英语中，colony 横跨政治、社会生物学、微生物学与文化；复数 colonies 为规则形式。"}]},"similar":{"note":{"en":"The first group separates look-alikes and root neighbours, the second compares settlement and group nouns.","cn":"第一组区分形近词与同根词，第二组比较表示定居点与群体的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"colonial","ipa":"/kəˈləʊniəl/","tag":"derived adjective","definition":"relating to a colony; the adjective never names the settlement itself.","definitionCN":"与殖民地有关的；形容词不能直接命名定居点本身。"},{"word":"colonist","ipa":"/ˈkɒlənɪst/","tag":"person noun","definition":"a person who settles in a colony; the human agent, not the place or group.","definitionCN":"在殖民地定居的人；指人，不指地方或群体。"},{"word":"colon","ipa":"/ˈkəʊlən/","tag":"different root","definition":"the large intestine, from Greek kolon; a classic false friend of colony.","definitionCN":"大肠，来自希腊语 kolon；colony 的经典假朋友。"},{"word":"colonnade","ipa":"/ˌkɒləˈneɪd/","tag":"different root","definition":"a row of columns, from columna 'pillar'; no connection to settlement.","definitionCN":"一排柱子，来自 columna「柱」；与定居无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"settlement","ipa":"/ˈsetlmənt/","tag":"place","definition":"a community where people have settled; it lacks the dependent-rule sense.","definitionCN":"人们定居的社群；缺少“受外部治理”之义。"},{"word":"dependency","ipa":"/dɪˈpendənsi/","tag":"politics","definition":"a territory governed by another state; it stresses legal subordination rather than settlement.","definitionCN":"由另一国治理的领土；强调法律上的从属而非定居。"},{"word":"community","ipa":"/kəˈmjuːnəti/","tag":"group","definition":"a group living together or sharing interests; it is broader and not tied to a site.","definitionCN":"共同生活或共享利益的群体；更宽泛，不与特定地点绑定。"},{"word":"swarm","ipa":"/swɔːm/","tag":"animals","definition":"a large moving group of insects; a colony is settled and organized, a swarm may be temporary.","definitionCN":"大量移动的昆虫；colony 是定居且有组织的，swarm 可能是暂时的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin parts, standard phrases in history and biology.","cn":"正常联想：真实拉丁语成分，以及历史与生物学的标准搭配。"},"normal":[{"en":"colere = cultivate: a colony is first a place where someone farms.","cn":"colere = 耕种：colony 最初就是有人耕种的地方。"},{"en":"An ant colony and a bacterial colony share the image of many individuals in one founded site.","cn":"蚁群与菌落共享同一意象：许多个体住在一个被建立的场所。"},{"en":"A colony can be the land or the people; context decides which.","cn":"colony 可指土地也可指人，由语境决定。"},{"en":"Colonist is the person, colony is the place or group, colonial is the adjective.","cn":"colonist 指人，colony 指地方或群体，colonial 是形容词。"},{"en":"A leper colony shows the dark side of the word: settlement as separation.","cn":"leper colony 显示该词的阴暗面：定居即隔离。"}],"abstract":[{"en":"Picture a flag planted in new soil with a farm beside it: the flag is rule, the farm is settlement, the people are the colony.","cn":"想象新土地上插着一面旗、旁边有一块田：旗是统治，田是定居，人是 colony。"},{"en":"The biological sense keeps the shape but drops the flag: a group occupies one site and reproduces there.","cn":"生物义保留形状却去掉旗帜：一群个体占据一处并在那里繁殖。"},{"en":"Every colony implies a boundary: inside are members, outside are others.","cn":"每个 colony 都隐含边界：内是成员，外是他者。"}]},"examples":[{"en":"The colony declared independence after two centuries of foreign rule.","cn":"经过两个世纪的外来统治，该殖民地宣布独立。"},{"en":"The ant colony sends out scouts before the main foraging group moves.","cn":"蚁群在主要觅食群体出发前先派出侦察蚁。"},{"en":"One colony on the agar plate contained a single resistant strain.","cn":"琼脂平板上的一个菌落含有单一抗性菌株。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“靠了泥”——靠了这片泥地才落脚建村 → colony 殖民地、定居群体","word":"colony"},"root":"拉丁语 colonia「定居之地、农庄」，来自 colonus（耕种者）与 colere（耕种、居住）。","sensesIntro":{"en":"Eight senses of colony: a ruled territory, its settlers, animal societies, microbial clusters, cultural communities, breeding gatherings, ancient foundations, and segregated communities.","cn":"colony 的八个义项：被治理的领地、定居者、动物社会、微生物集团、文化社群、繁殖聚集、古代殖民城邦与隔离社群。"},"semanticMap":{"core":{"en":"CORE IMAGE: a group founds one site and lives there together.","cn":"核心意象：一个群体建立一处场所并共同生活在那里。"},"chain":["FOUNDED SITE","SETTLERS","SHARED LIFE","BOUNDARY","REPRODUCTION","DEPENDENCE OR SEPARATION"],"branches":[{"senses":"S1 · S2 · S7","en":"POLITICS: a settlement of citizens becomes a territory ruled from elsewhere.","cn":"政治：公民定居点变成由外部治理的领土。"},{"senses":"S3 · S6","en":"ANIMALS: one species occupies a site, cooperates, and breeds there.","cn":"动物：同一物种占据一处、协作并在那里繁殖。"},{"senses":"S4","en":"MICROBES: a visible cluster descends from one founding cell.","cn":"微生物：可见集团源自一个建立者细胞。"},{"senses":"S5","en":"CULTURE: like-minded people settle together and create a local scene.","cn":"文化：志趣相投者共同定居并形成地方场景。"},{"senses":"S8","en":"EXCLUSION: settlement can also mean being placed apart.","cn":"隔离：定居也可以意味着被安置在别处。"}]},"affixes":{"intro":{"en":"Colony is a borrowed Latin noun; English derives colonize, colonization, colonial, and colonist from it with productive suffixes, but does not split colon- into smaller English parts.","cn":"colony 是借入的拉丁名词；英语用能产后缀从它派生 colonize、colonization、colonial、colonist，但不会把 colon- 进一步拆成英语成分。"},"latinIntro":{"en":"Latin colere 'cultivate' also gives culture and agriculture; colonia gives colony and colonial. The unrelated colon (intestine) and colonnade (columns) are false friends.","cn":"拉丁语 colere「耕种」还衍生 culture 与 agriculture；colonia 衍生 colony 与 colonial。无关的 colon（大肠）与 colonnade（柱廊）是假朋友。"},"items":[{"word":"colony","structure":"colonia (Latin noun)","meaning":"a settlement or group living together","meaningCN":"定居点或共同生活的群体","example":"The colony was founded in 1630.","exampleCN":"该殖民地建于 1630 年。"},{"word":"colonies","structure":"colony + -es (plural)","meaning":"more than one colony","meaningCN":"多个殖民地或群体（复数）","example":"Bacterial colonies differ in colour.","exampleCN":"细菌菌落颜色不同。"},{"word":"colonize","structure":"colony + -ize (verb)","meaning":"to establish a colony","meaningCN":"建立殖民地；定殖（-ize 动词）","example":"Mosses colonize the rock.","exampleCN":"苔藓定殖岩石。"},{"word":"colonization","structure":"colonize + -ation (noun)","meaning":"the process of founding colonies","meaningCN":"建立殖民地的过程","example":"Colonization altered the landscape.","exampleCN":"殖民改变了景观。"},{"word":"colonial","structure":"colony + -al (adjective)","meaning":"of or relating to a colony","meaningCN":"殖民地的（-al 形容词）","example":"Colonial borders still matter.","exampleCN":"殖民地边界仍有影响。"},{"word":"colonist","structure":"colony + -ist (person)","meaning":"a settler in a colony","meaningCN":"殖民地定居者（-ist 指人）","example":"The colonists planted wheat.","exampleCN":"殖民者种下小麦。"},{"word":"culture","structure":"colere + -tura (result noun)","meaning":"cultivation; shared ways of life","meaningCN":"耕作；文化（-tura 结果名词）","example":"Culture grew from cultivation.","exampleCN":"文化由耕作而来。"},{"word":"agriculture","structure":"ager (field) + cultura","meaning":"field cultivation","meaningCN":"农田耕作","example":"Agriculture supports the colony.","exampleCN":"农业支撑着这个定居点。"}],"latinEntries":[{"word":"colere","structure":"colere (third conjugation)","meaning":"to cultivate, inhabit, worship","meaningCN":"耕种；居住；敬奉"},{"word":"colonus","structure":"colere + -onus (agent)","meaning":"tiller, settler","meaningCN":"耕种者；定居者"},{"word":"colonia","structure":"colonus + -ia (place)","meaning":"settled land, colony","meaningCN":"定居之地；殖民地"},{"word":"cultura","structure":"colere + -tura","meaning":"cultivation, care","meaningCN":"耕作；照料"}]}},{"word":"community structure","ipa_uk":"/kəˈmjuːnəti ˈstrʌktʃə/","ipa_us":"/kəˈmjuːnəti ˈstrʌktʃər/","definition_zh":"群落结构；社群结构","definition_en":"the composition and arrangement of the species in an ecological community, including which species are present, how many, and how they interact","core_image":"森林剖面图：乔木层、灌木层、草本层各自成层，物种名单与数量排成一张表","scene":"调查者记录了样方中每一层的物种、数量与盖度，用来比较两片森林的群落结构。 The surveyors recorded the species, abundance, and cover in each layer of the plot in order to compare the community structure of the two forests.","sceneCN":"这里 community structure 是「群落结构」（第 1 个义项：生态群落中的物种组成与数量配置）；句意：调查者记录样方中每一层的物种、数量与盖度，以比较两片森林的群落结构。","pos":[{"tag":"n.","zh":"群落结构；社群结构（多作不可数，指具体类型时可数）"}],"collocations":[{"phrase":"community structure of a forest","zh":"森林的群落结构"},{"phrase":"change in community structure","zh":"群落结构的变化"},{"phrase":"community structure analysis","zh":"群落结构分析"},{"phrase":"simplify community structure","zh":"简化群落结构"},{"phrase":"restore community structure","zh":"恢复群落结构"},{"phrase":"community structure and function","zh":"群落结构与功能"}],"forms":[{"label":"复数（指多种群落结构）","form":"community structures"},{"label":"相关名词（群落）","form":"community"},{"label":"相关名词（结构）","form":"structure"},{"label":"相关形容词（结构的）","form":"structural"}],"derivatives":[{"word":"community","pos":"n.","zh":"群落；社群"},{"word":"structure","pos":"n.","zh":"结构；构造"},{"word":"structural","pos":"adj.","zh":"结构的；构造的"},{"word":"structurally","pos":"adv.","zh":"在结构上"}],"senses":[{"no":"01","title":"Species composition and abundance","titleCN":"物种组成与数量配置","definition":"the set of species in a community together with their relative abundances","definitionCN":"一个群落中的物种集合及其相对数量","example":"Grazing changed the community structure from grass-dominated to shrub-dominated.","exampleCN":"放牧使群落结构从以草为主转变为以灌木为主。","why":"Community is a group living together, structure is a fitting together. Ecologists therefore name the way species are 'fitted' into one assemblage: who is present and in what numbers.","whyCN":"community 是共同生活的群体，structure 是“拼合”。生态学家因此把物种“拼合”成一个集合的方式命名为群落结构：谁存在、各有多少。"},{"no":"02","title":"Trophic or food-web structure","titleCN":"营养级或食物网结构","definition":"the arrangement of species into feeding levels and predator-prey links","definitionCN":"物种被排列成取食层级与捕食—被捕食联系的方式","example":"The removal of top predators simplified the community structure.","exampleCN":"顶级捕食者的消失简化了群落结构。","why":"Structure here is relational: species are not just listed but linked as eaters and eaten, so the architecture is a network of flows.","whyCN":"这里的结构是关系性的：物种不只是被列出，还作为取食者与被取食者相连，因此架构是一张流动网络。"},{"no":"03","title":"Spatial or vertical structure","titleCN":"空间或垂直结构","definition":"the physical layering and patchiness of a community, such as canopy, understorey, and ground layers","definitionCN":"群落的物理分层与斑块分布，如林冠层、下木层与地被层","example":"The vertical community structure of the rainforest supports many more niches than a grassland.","exampleCN":"雨林的垂直群落结构比草地支撑多得多的生态位。","why":"A community occupies space, and structure as 'building' becomes literal: layers and gaps create different places to live within one site.","whyCN":"群落占据空间，structure 的“建筑”义变成字面意义：层次与空隙在同一地点造出不同的栖居位置。"},{"no":"04","title":"Functional or guild structure","titleCN":"功能群结构","definition":"the division of a community into groups that perform similar ecological roles","definitionCN":"群落按执行相似生态角色的类群进行划分","example":"Functional community structure groups nitrogen-fixers, grazers, and decomposers separately.","exampleCN":"功能群落结构把固氮者、植食者与分解者分别归类。","why":"The metaphor shifts from parts to jobs: structure is the arrangement of roles, and species with the same job can substitute for one another.","whyCN":"隐喻从“部件”转向“职能”：结构是角色的排列，执行同一职能的物种可以相互替代。"},{"no":"05","title":"Social structure of a human community","titleCN":"人类社群的社会结构","definition":"the arrangement of roles, institutions, and relationships within a human community","definitionCN":"人类社群中角色、制度与关系的排列","example":"Migration altered the community structure of the old mill towns.","exampleCN":"移民改变了旧磨坊镇的社群结构。","why":"The sociological sense uses the same word for a different assemblage: people rather than species are fitted into positions, and the pattern is roles rather than trophic levels.","whyCN":"社会学义用同一个词指另一种集合：被拼入位置的是人而非物种，格局是角色而非营养级。"},{"no":"06","title":"Organizational or network structure","titleCN":"组织或网络结构","definition":"the pattern of connections among groups, agencies, or actors in a system","definitionCN":"系统中群体、机构或行动者之间连接的模式","example":"The study mapped the community structure of disaster-response agencies.","exampleCN":"这项研究绘制了灾害应对机构的社群结构。","why":"In network analysis, community structure names clusters that are denser inside than between; the ecological word is reused for any grouped network.","whyCN":"在网络分析中，community structure 指内部连接比外部更密的集团；生态词被复用于任何成组的网络。"},{"no":"07","title":"Structure as a measured variable","titleCN":"作为可测量变量的结构","definition":"a quantitative description of a community, such as diversity indices, evenness, or size spectra","definitionCN":"对群落的定量描述，如多样性指数、均匀度或体尺谱","example":"The index summarizes community structure in a single number.","exampleCN":"该指数用单一数字概括群落结构。","why":"Once structure can be measured, the phrase becomes a variable in models: changes are expressed as shifts in indices rather than as lists of species.","whyCN":"一旦结构可测量，这个短语就成为模型中的变量：变化用指数移动来表示，而不是用物种清单。"},{"no":"08","title":"Structure as a conservation target","titleCN":"作为保护目标的结构","definition":"the desired arrangement of species and ages that restoration aims to rebuild","definitionCN":"恢复工作力求重建的物种与年龄配置","example":"Restoration aims at reference community structure, not just species count.","exampleCN":"恢复工作瞄准参照群落结构，而不只是物种数量。","why":"Management turns the description into a goal: a 'good' community has a particular structure, and success is measured by how closely the rebuilt site matches it.","whyCN":"管理把描述变成目标：“良好”的群落有特定结构，成功程度以重建样地与它的接近程度衡量。"}],"etymology":{"intro":{"en":"The phrase joins community, from Latin communitas 'fellowship', and structure, from Latin structura 'a building'. It is a modern ecological collocation, not an inherited Latin phrase.","cn":"这个短语由 community（拉丁语 communitas「共同体」）与 structure（拉丁语 structura「建筑」）组合而成，是现代生态学搭配，并非承继的拉丁短语。"},"items":[{"era":"LATIN","en":"communitas 'community, fellowship' comes from communis 'common, shared', analysed as com- 'together' + munis 'performing service, obliging'.","cn":"communitas「共同体、情谊」来自 communis「共同的、共享的」，可分析为 com-「一起」+ munis「履行职责、有义务」。"},{"era":"LATIN","en":"structura 'a fitting together, building' comes from struere 'to pile, build, arrange'; the noun names both the act of building and its result.","cn":"structura「拼合、建筑」来自 struere「堆叠、建造、排列」；名词同时指建造行为与结果。"},{"era":"PROTO-INDO-EUROPEAN","en":"struere is traced to *stere- 'to spread', and communis to *mei- 'to change, exchange' via munus 'duty, gift'. Both roots are reconstructions, so the deepest layer is source uncertain.","cn":"struere 被追溯到 *stere-「铺展」，communis 则经 munus「义务、赠礼」追溯到 *mei-「交换、改变」。两个词根均为重构，故最深层来源不确定。"},{"era":"19C.–20C.","en":"Community was used for plant and animal assemblages in the nineteenth century; 'community structure' became standard with the quantitative ecology of the mid-twentieth century.","cn":"community 在 19 世纪被用于植物与动物集合；“community structure”随 20 世纪中期的定量生态学成为标准术语。"},{"era":"MODERN ENGLISH","en":"Modern usage spans ecology, sociology, and network science; in ecology it usually means composition plus abundance plus interaction, not merely a species list.","cn":"现代用法横跨生态学、社会学与网络科学；在生态学中通常指组成、数量与相互作用的结合，而不只是物种清单。"}]},"similar":{"note":{"en":"The first group separates look-alike phrases, the second compares structural concepts in ecology.","cn":"第一组区分形近短语，第二组比较生态学中的结构概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"community composition","ipa":"/kəˈmjuːnəti kəmˈpəzɪʃn/","tag":"narrower","definition":"the species list and their abundances, without the interaction or layering aspect.","definitionCN":"物种清单及其数量，不包含相互作用或分层方面。"},{"word":"population structure","ipa":"/ˌpɒpjuˈleɪʃn ˈstrʌktʃə/","tag":"different level","definition":"the age, sex, or size distribution within one species; community structure concerns many species.","definitionCN":"单一物种内的年龄、性别或体尺分布；群落结构涉及多个物种。"},{"word":"ecosystem structure","ipa":"/iːˈkɒsɪstəm ˈstrʌktʃə/","tag":"wider","definition":"the physical and biological arrangement including abiotic components; community structure excludes the physical setting.","definitionCN":"包含非生物成分的物理与生物排列；群落结构不含物理环境。"},{"word":"social structure","ipa":"/ˈsəʊʃl ˈstrʌktʃə/","tag":"human","definition":"the arrangement of roles and institutions among people; it is the sociological parallel.","definitionCN":"人与人之间角色与制度的排列；是社会学的平行概念。"}]},{"heading":"NEAR MEANING","entries":[{"word":"biodiversity","ipa":"/ˌbaɪəʊdaɪˈvɜːsəti/","tag":"measured property","definition":"variety of species or genes; it is one dimension of community structure, not the whole arrangement.","definitionCN":"物种或基因的多样性；是群落结构的一个维度，而非整体排列。"},{"word":"food web","ipa":"/fuːd web/","tag":"network","definition":"the feeding links among species; it is the trophic part of community structure.","definitionCN":"物种间的取食联系；是群落结构的营养部分。"},{"word":"assemblage","ipa":"/əˈsemblɪdʒ/","tag":"neutral","definition":"a set of species found together, without implying organization.","definitionCN":"共同出现的物种集合，不暗示组织性。"},{"word":"zonation","ipa":"/zəʊˈneɪʃn/","tag":"spatial","definition":"banded distribution along a gradient; it is a spatial pattern within community structure.","definitionCN":"沿梯度成带分布；是群落结构中的空间格局。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts and standard ecological phrasing.","cn":"正常联想：真实构词成分与标准生态学表述。"},"normal":[{"en":"Community + structure: who lives together, and how they are fitted together.","cn":"community + structure：谁共同生活，以及它们如何被拼合在一起。"},{"en":"Structure here means composition, abundance, layering, and interaction, not a building.","cn":"这里的 structure 指组成、数量、分层与相互作用，不是建筑物。"},{"en":"Trophic structure is the food-web part; spatial structure is the layering part.","cn":"trophic structure 是食物网部分；spatial structure 是分层部分。"},{"en":"Population structure is one species; community structure is many species.","cn":"population structure 是一个物种；community structure 是多个物种。"},{"en":"Restoration ecologists compare a rebuilt site's community structure with a reference site.","cn":"恢复生态学家把重建样地的群落结构与参照样地比较。"}],"abstract":[{"en":"Picture a seating chart: who is in the room, how many from each group, and who talks to whom. That chart is community structure.","cn":"想象一张座位图：谁在房间里、每组有多少人、谁与谁交谈。这张图就是 community structure。"},{"en":"The phrase has two halves: community supplies the many-species gathering, structure supplies the arrangement.","cn":"短语有两半：community 提供多物种集合，structure 提供排列方式。"},{"en":"A list of species is a cast; community structure is the play they perform together.","cn":"物种清单是演员表；community structure 是他们共同演出的戏。"}]},"examples":[{"en":"Fire suppression shifted the community structure toward shade-tolerant trees.","cn":"灭火使群落结构转向耐阴树种。"},{"en":"The two reefs differ in community structure although they share most species.","cn":"两处礁区虽共享多数物种，群落结构却不同。"},{"en":"Monitoring community structure is cheaper than counting every population.","cn":"监测群落结构比逐一统计每个种群更省钱。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“社区结构”——一个社区里谁住哪层、谁和谁来往，排成一张结构图 → community structure 群落结构","word":"community structure"},"root":"community 来自拉丁语 communitas（共同体），structure 来自拉丁语 structura（建筑、拼合）。","sensesIntro":{"en":"Eight senses of community structure: composition, trophic links, spatial layering, functional roles, human institutions, network clusters, measured indices, and restoration targets.","cn":"community structure 的八个义项：物种组成、营养联系、空间分层、功能角色、人类制度、网络集团、可测指数与恢复目标。"},"semanticMap":{"core":{"en":"CORE IMAGE: a layered forest diagram with species lists and numbers attached to each layer.","cn":"核心意象：一张分层森林剖面图，每层附有物种清单与数量。"},"chain":["MANY SPECIES","PRESENT","ABUNDANT","LINKED","LAYERED","PATTERN"],"branches":[{"senses":"S1 · S7","en":"COMPOSITION: who is present and how many, summarized by indices.","cn":"组成：谁存在、各有多少，用指数概括。"},{"senses":"S2 · S4","en":"RELATIONS: feeding links and functional roles organize the assemblage.","cn":"关系：取食联系与功能角色组织集合。"},{"senses":"S3","en":"SPACE: canopy, understorey, and gaps create layered habitats.","cn":"空间：林冠、下木与空隙造出分层栖息地。"},{"senses":"S5 · S6","en":"HUMAN AND NETWORK: people and agencies form their own clustered structures.","cn":"人类与网络：人与机构形成各自的集团结构。"},{"senses":"S8","en":"GOAL: a reference structure guides restoration and management.","cn":"目标：参照结构指导恢复与管理。"}]},"affixes":{"intro":{"en":"Both halves are borrowed Latin nouns; English combines them freely, and adds -al to structure to make the adjective structural.","cn":"两半都是借入的拉丁名词；英语自由组合它们，并在 structure 上加 -al 构成形容词 structural。"},"latinIntro":{"en":"Communis yields community, communal, commune, and communicate; struere yields structure, construct, instruct, and destroy (de- + struere).","cn":"communis 衍生 community、communal、commune、communicate；struere 衍生 structure、construct、instruct、destroy（de- + struere）。"},"items":[{"word":"community","structure":"communis + -ity (noun of state)","meaning":"a group sharing a place or interest","meaningCN":"共享地点或利益的群体（-ity 名词）","example":"The reef community includes corals and fish.","exampleCN":"礁区群落包括珊瑚与鱼类。"},{"word":"structure","structure":"structura (Latin noun)","meaning":"an arrangement of parts","meaningCN":"各部分的排列","example":"The structure of the plot was mapped.","exampleCN":"样方的结构被绘制出来。"},{"word":"structural","structure":"structure + -al (adjective)","meaning":"relating to structure","meaningCN":"与结构有关的（-al 形容词）","example":"Structural complexity creates niches.","exampleCN":"结构复杂性创造生态位。"},{"word":"structurally","structure":"structural + -ly (adverb)","meaning":"in structural terms","meaningCN":"在结构方面","example":"The forests are structurally different.","exampleCN":"这些森林在结构上不同。"},{"word":"construct","structure":"con- (together) + struere (to build)","meaning":"to build by fitting parts","meaningCN":"通过拼合部件来建造","example":"Insects construct nests from leaves.","exampleCN":"昆虫用叶子筑巢。"},{"word":"instruct","structure":"in- (into) + struere (to build)","meaning":"to build knowledge into someone","meaningCN":"把知识建构到某人心中；指导","example":"The manual instructs surveyors.","exampleCN":"手册指导调查员。"},{"word":"destroy","structure":"de- (down) + struere (to build)","meaning":"to unbuild","meaningCN":"拆毁；破坏","example":"Storms destroy the canopy.","exampleCN":"风暴摧毁林冠。"},{"word":"communal","structure":"communis + -al (adjective)","meaning":"shared by a community","meaningCN":"社群共享的","example":"The birds have communal nests.","exampleCN":"这些鸟有共用巢。"}],"latinEntries":[{"word":"communis","structure":"com- + munis (adjective)","meaning":"common, shared","meaningCN":"共同的；共享的"},{"word":"communitas","structure":"communis + -itas","meaning":"community, fellowship","meaningCN":"共同体；情谊"},{"word":"struere","structure":"struere (third conjugation)","meaning":"to pile, build, arrange","meaningCN":"堆叠；建造；排列"},{"word":"structura","structure":"struere + -tura","meaning":"a building; arrangement","meaningCN":"建筑；结构"}]}},{"word":"ecological succession","ipa_uk":"/ˌiːkəˈlɒdʒɪkl səˈkseʃn/","ipa_us":"/ˌiːkəˈlɑːdʒɪkl səˈkseʃn/","definition_zh":"生态演替；生态演替过程","definition_en":"the gradual, directional change in the species composition of an ecological community over time, especially after a disturbance or on newly exposed ground","core_image":"同一块地从裸岩、苔藓、草地到森林的一串连续快照","scene":"冰川退去后留下的裸岩上，地衣先出现，随后苔藓、草本与灌木依次进入，最终形成灌丛。 On the bare rock left by a retreating glacier, lichens appeared first, then mosses, herbs, and shrubs followed one another in a classic ecological succession that ended in scrub.","sceneCN":"这里 ecological succession 是「生态演替」（第 1 个义项：群落随时间的定向变化）；句意：冰川退去后的裸岩上，地衣先出现，随后苔藓、草本与灌木依次进入，构成一场典型的生态演替，最终形成灌丛。","pos":[{"tag":"n.","zh":"生态演替；生态演替过程（多作不可数，指具体序列时可数）"}],"collocations":[{"phrase":"primary succession","zh":"原生演替"},{"phrase":"secondary succession","zh":"次生演替"},{"phrase":"ecological succession after a fire","zh":"火灾后的生态演替"},{"phrase":"stage of succession","zh":"演替阶段"},{"phrase":"succession sequence","zh":"演替序列"},{"phrase":"arrest succession","zh":"阻止演替"}],"forms":[{"label":"复数（指多次或多种演替）","form":"ecological successions"},{"label":"相关名词（演替）","form":"succession"},{"label":"相关形容词（演替的）","form":"successional"},{"label":"相关名词（顶极群落）","form":"climax community"}],"derivatives":[{"word":"succession","pos":"n.","zh":"演替；连续；继承"},{"word":"successional","pos":"adj.","zh":"演替的；连续发生的"},{"word":"succeed","pos":"v.","zh":"接替；继任；随后发生"},{"word":"successive","pos":"adj.","zh":"连续的；相继的"}],"senses":[{"no":"01","title":"Directional change of communities over time","titleCN":"群落随时间的定向变化","definition":"the orderly replacement of one community by another at a site through time","definitionCN":"同一地点上群落随时间被另一个群落有序替代","example":"Ecological succession turns a abandoned field into woodland over decades.","exampleCN":"生态演替在数十年间把弃耕地变成林地。","why":"Succession is from succedere 'to come after'. Ecology applies 'coming after' to species: each assemblage creates conditions that let the next one follow it.","whyCN":"succession 来自 succedere「随后而来」。生态学把“随后而来”用于物种：每个群落创造条件，让下一个群落接替它。"},{"no":"02","title":"Primary succession on new substrate","titleCN":"新基质上的原生演替","definition":"succession that begins on bare rock, lava, or sand where no soil and no seed bank exist","definitionCN":"在没有土壤与种子库的裸岩、熔岩或沙地上开始的演替","example":"Primary succession on the lava flow has taken four centuries to produce forest.","exampleCN":"熔岩流上的原生演替用了四个世纪才形成森林。","why":"The prefix 'primary' marks a zero starting point: there is no previous community and no stored propagules, so colonists must arrive from outside.","whyCN":"primary 标记零起点：没有先前群落，也没有储存的繁殖体，因此定殖者必须从外部到达。"},{"no":"03","title":"Secondary succession after disturbance","titleCN":"干扰后的次生演替","definition":"succession that restarts on a site where soil and seeds survive a disturbance","definitionCN":"在土壤与种子于干扰后仍存留的地点重新开始的演替","example":"Secondary succession after the fire was visible within a single spring.","exampleCN":"火灾后的次生演替在一个春天内就可见。","why":"Secondary means the site is not blank: soil, roots, and seeds remain, so recovery 'comes after' disturbance from an already prepared base.","whyCN":"secondary 意味着地点并非空白：土壤、根与种子仍在，因此恢复是“在已准备好的基础上”随之而来。"},{"no":"04","title":"The sequence of seral stages","titleCN":"演替阶段序列","definition":"the ordered series of communities, called seral stages, through which a site passes","definitionCN":"一个地点依次经过的群落序列，各阶段称为演替阶段","example":"The succession sequence ran from annual weeds to perennial grass to pine.","exampleCN":"演替序列从一年生杂草到多年生草，再到松树。","why":"The abstract process is also the concrete ladder: each rung is a seral stage, and the whole ladder is the succession.","whyCN":"抽象过程同时也是具体的阶梯：每一级是一个演替阶段，整架梯子就是 succession。"},{"no":"05","title":"Mechanisms that drive replacement","titleCN":"驱动替代的机制","definition":"the processes such as facilitation, tolerance, and inhibition by which earlier species affect later ones","definitionCN":"较早物种通过促进、耐受或抑制等过程影响后来物种的机制","example":"Facilitation during succession allows nitrogen-poor sites to support herbs.","exampleCN":"演替中的促进作用使缺氮地点能够支撑草本植物。","why":"Change is not automatic: earlier species alter soil, light, or herbivory, so succession is the sum of these species-by-species effects.","whyCN":"变化并非自动发生：较早物种改变土壤、光照或植食压力，因此演替是这些逐种效应的总和。"},{"no":"06","title":"Succession as a theoretical model","titleCN":"作为理论模型的演替","definition":"the conceptual framework that predicts trajectories, from classical climax theory to modern non-equilibrium models","definitionCN":"预测演替轨迹的概念框架，从经典顶极理论到现代非平衡模型","example":"Modern succession theory accepts multiple stable states rather than one endpoint.","exampleCN":"现代演替理论接受多个稳定状态，而不是单一终点。","why":"The phrase also names a model, not just a process: ecologists argue about whether succession converges, cycles, or depends on chance.","whyCN":"这个短语也指模型而非仅指过程：生态学家争论演替是趋同、循环还是取决于偶然。"},{"no":"07","title":"Applied succession in restoration","titleCN":"恢复实践中的演替应用","definition":"the deliberate use of successional processes to rebuild vegetation on degraded land","definitionCN":"有意利用演替过程在退化土地上重建植被","example":"Restoration relies on ecological succession but may accelerate it with nurse plants.","exampleCN":"恢复依赖生态演替，但可能用保育植物加速它。","why":"Applied ecology treats the sequence as a tool: managers plant pioneers, remove grazing, or add propagules so that the natural ladder starts climbing again.","whyCN":"应用生态学把这个序列当作工具：管理者种植先锋、排除放牧或补充繁殖体，使自然的梯子重新开始攀升。"},{"no":"08","title":"Succession interrupted or arrested","titleCN":"被中断或停滞的演替","definition":"a stalled or deflected succession caused by grazing, fire, or other persistent pressure","definitionCN":"由放牧、火灾或其他持续压力造成的停滞或偏转的演替","example":"Heavy grazing produced an arrested succession dominated by spines.","exampleCN":"重度放牧造成以刺灌为主的停滞演替。","why":"If the driver that removes each stage keeps operating, 'coming after' never arrives; the sequence is held at an early rung, which is still described as succession in its arrested form.","whyCN":"如果移除每一阶段的驱动持续存在，“随后而来”就永远不会到达；序列被卡在早期一级，这仍被称为停滞形式的演替。"}],"etymology":{"intro":{"en":"The phrase combines Greek oikos 'house' through ecology with Latin successio 'a following after'. The collocation is a twentieth-century ecological coinage.","cn":"这个短语把经 ecology 而来的希腊语 oikos「住所」与拉丁语 successio「随后而至」结合，是 20 世纪的生态学造词。"},"items":[{"era":"GREEK","en":"oikos 'house, dwelling' gives eco- through Ernst Haeckel's coinage Ökologie (1866), 'the study of the household of nature'.","cn":"oikos「住所、家宅」经海克尔 1866 年创造的 Ökologie 提供 eco-，意为“研究自然之家”。"},{"era":"LATIN","en":"successio 'a following after, a coming into another's place' comes from succedere 'to come close after', sub- 'next to' + cedere 'to go'.","cn":"successio「随后而至、接替他人位置」来自 succedere「紧随而来」，即 sub-「靠近」+ cedere「走」。"},{"era":"LATIN PARTS","en":"The same cedere family gives proceed, precede, recede, and concede; succession is the branch in which one thing takes the place of another.","cn":"同一个 cedere 词族还衍生 proceed、precede、recede、concede；succession 是其中“一物取代另一物位置”的分支。"},{"era":"20C.","en":"The modern phrase ecological succession was standardized in early twentieth-century plant ecology, building on Cowles, Clements, and Gleason.","cn":"现代短语 ecological succession 在 20 世纪初的植物生态学中定型，建立在 Cowles、Clements 与 Gleason 的工作之上。"},{"era":"MODERN ENGLISH","en":"Modern usage distinguishes primary from secondary succession and treats the climax endpoint as one possible outcome rather than a universal law.","cn":"现代用法区分原生与次生演替，并把顶极终点视为一种可能结果，而非普遍规律。"}]},"similar":{"note":{"en":"The first group separates successional terms, the second compares processes of change in communities.","cn":"第一组区分演替相关术语，第二组比较群落变化过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"succession","ipa":"/səˈkseʃn/","tag":"base noun","definition":"the general act of following in order; in ecology it is the community replacement process.","definitionCN":"按顺序接替的一般行为；生态学中指群落替代过程。"},{"word":"successive","ipa":"/səkˈsesɪv/","tag":"adjective","definition":"following one after another; it describes the stages, not the process.","definitionCN":"一个接一个的；描述各阶段，而非过程。"},{"word":"primary succession","ipa":"/ˈpraɪməri səˈkseʃn/","tag":"subtype","definition":"succession on bare substrate with no soil or seed bank.","definitionCN":"无土壤与种子库的裸基质上的演替。"},{"word":"secondary succession","ipa":"/ˈsekəndəri səˈkseʃn/","tag":"subtype","definition":"succession after disturbance where soil and propagules survive.","definitionCN":"干扰后土壤与繁殖体仍存时的演替。"}]},{"heading":"NEAR MEANING","entries":[{"word":"regeneration","ipa":"/ˌriːdʒenəˈreɪʃn/","tag":"recovery","definition":"the regrowth of vegetation after damage, which may follow a successional path.","definitionCN":"受损后植被再生长，可能沿演替路径进行。"},{"word":"restoration","ipa":"/ˌrestəˈreɪʃn/","tag":"human action","definition":"deliberate rebuilding of an ecosystem; succession may be the tool, restoration the goal.","definitionCN":"有意重建生态系统；演替可能是工具，恢复是目标。"},{"word":"zonation","ipa":"/zəʊˈneɪʃn/","tag":"space","definition":"banded pattern in space along a gradient, not change in time.","definitionCN":"沿梯度形成的空间带状格局，而非时间变化。"},{"word":"evolution","ipa":"/ˌiːvəˈluːʃn/","tag":"different scale","definition":"genetic change in populations; succession is ecological change of communities.","definitionCN":"种群的遗传变化；演替是群落的生态变化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek and Latin parts and standard ecological stages.","cn":"正常联想：真实的希腊语与拉丁语成分，以及标准生态学阶段。"},"normal":[{"en":"Ecology from oikos 'house': succession is the household changing its residents over time.","cn":"ecology 来自 oikos「住所」：演替就是这座“自然之家”的住户随时间更换。"},{"en":"succedere = sub- + cedere 'go after': one community goes after another.","cn":"succedere = sub- + cedere「随后走」：一个群落接替另一个。"},{"en":"Primary succession starts from zero: bare rock, no soil, no seeds.","cn":"原生演替从零开始：裸岩、无土、无种子。"},{"en":"Secondary succession starts from soil: roots and seeds survive the fire.","cn":"次生演替从土壤开始：根与种子在火灾后存活。"},{"en":"Arrested succession is a stalled ladder: grazing or fire keeps removing the next rung.","cn":"停滞演替是卡住的梯子：放牧或火灾不断移除下一级。"}],"abstract":[{"en":"Picture a photo series of one hillside: rock, lichen, moss, grass, shrub, forest. The series is succession.","cn":"想象同一片山坡的连续照片：岩石、地衣、苔藓、草、灌木、森林。这组照片就是演替。"},{"en":"Each stage writes the conditions for the next: shade, soil depth, and nutrients are inherited.","cn":"每个阶段为下一阶段写下条件：遮阴、土层深度与养分被继承。"},{"en":"Succession is directional but not guaranteed; disturbance can reset or freeze it.","cn":"演替有方向性但无保证；干扰可以重置或冻结它。"}]},"examples":[{"en":"The island's ecological succession began with lichens on fresh lava.","cn":"该岛的生态演替从新鲜熔岩上的地衣开始。"},{"en":"Grazing pressure produced an arrested succession of thorn scrub.","cn":"放牧压力造成了以刺灌为主的停滞演替。"},{"en":"Ecological succession after the dam removal restored a gravel-bar plant community.","cn":"拆坝后的生态演替恢复了砾石滩植物群落。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一靠逻辑，接着升”——一步一步有次序地往上换，像梯队接班 → ecological succession 生态演替","word":"ecological succession"},"root":"ecology 来自希腊语 oikos（住所）+ -logia（研究）；succession 来自拉丁语 succedere（随后而来）。","sensesIntro":{"en":"Eight senses of ecological succession: the directional process, its primary and secondary forms, its stage sequence, its mechanisms, its theoretical models, its use in restoration, and its arrested state.","cn":"ecological succession 的八个义项：定向过程、原生与次生形式、阶段序列、驱动机制、理论模型、恢复应用与停滞状态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a photo series of one site, from bare rock to forest.","cn":"核心意象：同一地点的连续照片，从裸岩到森林。"},"chain":["OPEN SITE","COLONISTS ARRIVE","SOIL DEVELOPS","NEW SPECIES FOLLOW","COMMUNITY REPLACED","MATURE OR STALLED"],"branches":[{"senses":"S1","en":"DIRECTIONAL PROCESS: the community changes in a consistent direction rather than merely fluctuating.","cn":"定向过程：群落沿一致的方向变化，而不只是来回波动。"},{"senses":"S2 · S3","en":"STARTING POINT: zero substrate gives primary succession; surviving soil gives secondary.","cn":"起点：没有基质就产生原生演替；原有土壤残留则产生次生演替。"},{"senses":"S4","en":"LADDER: seral stages are the visible rungs of the process.","cn":"阶梯：各演替阶段是这个过程的可见横档。"},{"senses":"S5 · S6","en":"MECHANISM AND MODEL: facilitation and inhibition explain the climb; theory predicts its shape.","cn":"机制与模型：促进与抑制解释攀升过程；理论预测其形状。"},{"senses":"S7 · S8","en":"APPLICATION AND ARREST: restoration uses the ladder, while grazing or fire can freeze it.","cn":"应用与停滞：恢复实践利用这条阶梯，而放牧或火灾可能把它冻结。"}]},"affixes":{"intro":{"en":"The phrase combines a Greek-derived technical prefix eco-, the productive suffix -logical, and the Latin noun succession. English builds the whole phrase; Latin supplies only the second half.","cn":"这个短语由希腊来源的术语前缀 eco-、能产后缀 -logical 与拉丁名词 succession 组合；整条短语由英语构成，拉丁语只提供后半。"},"latinIntro":{"en":"Greek oikos yields ecology, ecosystem, economy, and ecumene; Latin cedere yields succession, proceed, precede, recede, and concede.","cn":"希腊语 oikos 衍生 ecology、ecosystem、economy、ecumene；拉丁语 cedere 衍生 succession、proceed、precede、recede、concede。"},"items":[{"word":"succession","structure":"succedere + -ion (noun of action)","meaning":"a following after; replacement","meaningCN":"随后而至；替代（-ion 名词）","example":"Succession follows disturbance.","exampleCN":"演替紧随干扰之后。"},{"word":"successional","structure":"succession + -al (adjective)","meaning":"relating to succession","meaningCN":"与演替有关的","example":"Successional species differ in shade tolerance.","exampleCN":"演替物种的耐阴能力不同。"},{"word":"primary","structure":"prim- (first) + -ary (adjective)","meaning":"first in order","meaningCN":"最初的；原生的","example":"Primary succession lacks soil.","exampleCN":"原生演替没有土壤。"},{"word":"secondary","structure":"second + -ary (adjective)","meaning":"second in order","meaningCN":"第二位的；次生的","example":"Secondary succession reuses old soil.","exampleCN":"次生演替复用原有土壤。"},{"word":"ecology","structure":"oikos (house) + -logia (study)","meaning":"the study of the household of nature","meaningCN":"研究自然之家的学科","example":"Ecology studies these transitions.","exampleCN":"生态学研究这些转变。"},{"word":"ecosystem","structure":"oikos + systema (organized whole)","meaning":"the community plus its physical setting","meaningCN":"群落与物理环境的整体","example":"An ecosystem includes soil and water.","exampleCN":"生态系统包含土壤与水。"},{"word":"succeed","structure":"sub- + cedere (to go)","meaning":"to come after; to take a place","meaningCN":"接替；随后发生","example":"Moss succeeds lichen on the rock.","exampleCN":"苔藓在岩石上接替地衣。"},{"word":"precede","structure":"prae- (before) + cedere (to go)","meaning":"to go before","meaningCN":"先于；走在前面","example":"Pioneer species precede shrubs.","exampleCN":"先锋物种先于灌木。"}],"latinEntries":[{"word":"oikos","structure":"Greek oikos (noun)","meaning":"house, dwelling","meaningCN":"住所；家宅"},{"word":"cedere","structure":"cedere (third conjugation)","meaning":"to go, yield","meaningCN":"走；让步"},{"word":"succedere","structure":"sub- + cedere","meaning":"to come after, take a place","meaningCN":"随后而来；接替"},{"word":"successio","structure":"succedere + -io","meaning":"a following after","meaningCN":"随后而至；继承"}]}},{"word":"pioneer species","ipa_uk":"/ˌpaɪəˈnɪə ˈspiːʃiːz/","ipa_us":"/ˌpaɪəˈnɪr ˈspiːʃiːz/","definition_zh":"先锋物种；先锋种","definition_en":"a species that is among the first to colonize bare or newly disturbed ground and help make it suitable for later species","core_image":"第一株在火山灰上扎根的地衣，背后还是一片灰白","scene":"在退冰川后的砾石地上，仙女木与苔藓是最早扎根的先锋物种，它们固定氮并积累薄土。 On the gravel left by a retreating glacier, Dryas and mosses are the pioneer species that root first, fixing nitrogen and building a thin soil.","sceneCN":"这里 pioneer species 是「先锋物种」（第 1 个义项：最先定殖裸地的物种）；句意：在退冰川后的砾石地上，仙女木与苔藓是最早扎根的先锋物种，它们固氮并积累薄土。","pos":[{"tag":"n.","zh":"先锋物种；先锋种（单复数同形，复数为 pioneer species）"}],"collocations":[{"phrase":"pioneer species on bare rock","zh":"裸岩上的先锋物种"},{"phrase":"pioneer species in succession","zh":"演替中的先锋物种"},{"phrase":"nitrogen-fixing pioneer species","zh":"固氮先锋物种"},{"phrase":"pioneer species for restoration","zh":"用于恢复的先锋物种"},{"phrase":"shade-intolerant pioneer species","zh":"不耐阴的先锋物种"},{"phrase":"replace pioneer species","zh":"取代先锋物种"}],"forms":[{"label":"复数（单复数同形）","form":"pioneer species"},{"label":"相关名词（先锋）","form":"pioneer"},{"label":"相关名词（演替）","form":"succession"},{"label":"相关名词（顶极群落）","form":"climax community"}],"derivatives":[{"word":"pioneer","pos":"n.","zh":"先驱；先锋；开拓者"},{"word":"pioneering","pos":"adj.","zh":"开创性的；先锋的"},{"word":"succession","pos":"n.","zh":"演替"},{"word":"colonizer","pos":"n.","zh":"定殖者；殖民者"}],"senses":[{"no":"01","title":"First colonizers of bare ground","titleCN":"裸地的最先定殖者","definition":"species that establish first on rock, lava, ash, or sand with little or no soil","definitionCN":"在几乎没有土壤的岩石、熔岩、火山灰或沙地上最先建立的物种","example":"Lichens are pioneer species on the fresh lava.","exampleCN":"地衣是新鲜熔岩上的先锋物种。","why":"Pioneer comes from French pionnier 'foot soldier': the first to enter dangerous ground. Ecologically, these species enter a site before any soil exists.","whyCN":"pioneer 来自法语 pionnier「步兵」：最先进入险地的人。生态学上，这些物种在任何土壤形成之前就进入地点。"},{"no":"02","title":"Early successional species generally","titleCN":"广义的早期演替物种","definition":"species characteristic of the early stages of succession, including fast-growing herbs and shrubs","definitionCN":"演替早期阶段的特征物种，包括速生草本与灌木","example":"Fireweed is a pioneer species after forest fires in the north.","exampleCN":"柳兰是北方森林火灾后的先锋物种。","why":"The term broadens from bare rock to any early stage: what matters is arriving early and growing fast, not the substrate type.","whyCN":"这个词从裸岩扩展到任何早期阶段：关键是最先到达并快速生长，而不是基质类型。"},{"no":"03","title":"Facilitators that build soil","titleCN":"改良土壤的促进者","definition":"pioneer species that add organic matter or nutrients and make the site habitable for later species","definitionCN":"添加有机物或养分、使地点可供后来物种居住的先锋物种","example":"Nitrogen-fixing pioneers act as facilitators for the whole succession.","exampleCN":"固氮先锋物种作为整个演替的促进者。","why":"Ecological theory calls this facilitation: the first species changes the environment, so its own success creates the conditions for its replacement.","whyCN":"生态学理论称此为促进：首批物种改变环境，因此它们自身的成功为被替代创造了条件。"},{"no":"04","title":"Nurse plants in restoration","titleCN":"恢复中的保育植物","definition":"pioneer species deliberately planted to shelter or enrich the soil for target species","definitionCN":"为遮蔽或改良土壤以利于目标物种而有意种植的先锋物种","example":"The project used a legume pioneer species as a nurse crop.","exampleCN":"该项目用豆科先锋物种作为保育作物。","why":"Restoration turns the ecological role into a tool: a hardy pioneer is planted not for itself but for what it does to the site.","whyCN":"恢复把生态角色变成工具：种植耐逆先锋不是为了它本身，而是为了它对地点所做的改变。"},{"no":"05","title":"Weedy or invasive early colonizers","titleCN":"杂草型或入侵性早期定殖者","definition":"fast-spreading species that dominate disturbed ground, sometimes hindering native succession","definitionCN":"迅速扩散、支配受扰地面、有时阻碍本地演替的物种","example":"An invasive grass became the pioneer species on every cleared slope.","exampleCN":"一种入侵草成为每片清理坡地的先锋物种。","why":"The same early-arrival strategy that makes a species a pioneer can make it a weed: rapid dispersal and growth are advantageous in bare sites.","whyCN":"使物种成为先锋的同一“早到”策略也能使它成为杂草：在裸地中，快速扩散与生长占优势。"},{"no":"06","title":"Pioneers of secondary succession","titleCN":"次生演替的先锋","definition":"species that first return after fire, logging, or abandonment where soil already exists","definitionCN":"在火灾、采伐或弃耕后土壤已存在的地点最先回归的物种","example":"Annual weeds were the pioneers of secondary succession in the old field.","exampleCN":"一年生杂草是旧田次生演替的先锋。","why":"With soil present, the pioneer need not build one; it only needs to germinate fast and tolerate full sun, so the pioneer role shifts to ruderal species.","whyCN":"土壤已存在时，先锋不必造土，只需快速萌发并耐全光，因此先锋角色转向路旁杂草型物种。"},{"no":"07","title":"A role, not a fixed list","titleCN":"一种角色而非固定名单","definition":"the functional category of first colonizers, which different species may fill in different regions","definitionCN":"最先定殖者的功能类别，不同地区可由不同物种承担","example":"Pioneer species differ between tropical and alpine sites; the role is the same.","exampleCN":"热带与高山地点的先锋物种不同，但角色相同。","why":"Ecologists treat the term as a role: any species with the right traits can be a pioneer, which is why no single species list defines it.","whyCN":"生态学家把这个词当作角色：任何具备相应性状的物种都能当先锋，因此没有单一物种名单能定义它。"},{"no":"08","title":"Pioneers in island biogeography","titleCN":"岛屿生物地理学中的先锋","definition":"the first species to reach a new island or habitat island and establish a population","definitionCN":"最先到达新岛屿或栖息地“岛”并建立种群的物种","example":"The first pioneer species on the new island were wind-borne ferns.","exampleCN":"新岛上的第一批先锋物种是风传播的蕨类。","why":"Island biogeography extends the idea from succession to dispersal: arrival order matters because the first colonist faces no competitors.","whyCN":"岛屿生物地理学把这一观念从演替扩展到扩散：到达顺序很重要，因为首个定殖者没有竞争者。"}],"etymology":{"intro":{"en":"Pioneer comes through French from a word for a foot soldier; species comes from Latin specere 'to look'. Their combination is a modern ecological label.","cn":"pioneer 经法语来自指“步兵”的词；species 来自拉丁语 specere「看」。两者的组合是现代生态学标签。"},"items":[{"era":"FRENCH","en":"Old French paonier, later pionnier, meant 'foot soldier, pioneer'. It derives from peon 'foot soldier', from Late Latin pedonem, from Latin pes 'foot'.","cn":"古法语 paonier（后为 pionnier）意为“步兵、先锋”，来自 peon「步兵」，再来自晚期拉丁语 pedonem 与拉丁语 pes「脚」。"},{"era":"MILITARY SENSE","en":"A pioneer was a soldier sent ahead to clear roads and prepare ground for the main army — exactly the image ecology later used for first colonizers.","cn":"pioneer 原指先遣清理道路、为大部队准备地面的士兵——正是生态学后来用于首批定殖者的意象。"},{"era":"LATIN","en":"species 'a particular sort, kind, appearance' comes from specere 'to look at'; the plural species is identical in form.","cn":"species「某一类别、外观」来自 specere「看」，其复数形式 species 与单数同形。"},{"era":"19C.–20C.","en":"Pioneer was applied to plant colonizers in the late nineteenth and early twentieth centuries, when succession studies named the first seral stage the pioneer stage.","cn":"pioneer 在 19 世纪末至 20 世纪初被用于植物定殖者，演替研究把第一个阶段命名为先锋阶段。"},{"era":"MODERN ENGLISH","en":"Modern ecology uses pioneer species for early colonists with fast dispersal and growth; the phrase is a role description, not a taxonomic group.","cn":"现代生态学用 pioneer species 指扩散与生长迅速的最早定殖者；该短语是角色描述，不是分类群。"}]},"similar":{"note":{"en":"The first group separates related succession terms, the second compares ecological categories of species.","cn":"第一组区分演替相关术语，第二组比较生态学物种类别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"climax community","ipa":"/ˈklaɪmæks kəˈmjuːnəti/","tag":"opposite stage","definition":"the late, relatively stable community; pioneer species name the first stage.","definitionCN":"演替后期相对稳定的群落；pioneer species 指第一阶段。"},{"word":"pioneer stage","ipa":"/ˌpaɪəˈnɪə steɪdʒ/","tag":"stage name","definition":"the first seral stage itself; the species are the organisms that occupy it.","definitionCN":"第一个演替阶段本身；物种是占据该阶段的生物。"},{"word":"pioneering","ipa":"/ˌpaɪəˈnɪərɪŋ/","tag":"adjective","definition":"the adjective meaning 'first or innovative'; it does not name a species.","definitionCN":"意为“开创性的”形容词，不指物种。"},{"word":"colonizer","ipa":"/ˈkɒlənaɪzə/","tag":"synonym-ish","definition":"any organism that establishes in a new place; a pioneer species is a colonizer of early, often bare, sites.","definitionCN":"任何在新地点建立的生物；先锋物种是早期、常为裸地的定殖者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ruderal species","ipa":"/ˈruːdərəl ˈspiːʃiːz/","tag":"disturbed ground","definition":"a plant of disturbed, nutrient-rich ground; it overlaps with pioneers of secondary succession.","definitionCN":"受扰动、养分丰富地面的植物；与次生演替先锋重叠。"},{"word":"nurse plant","ipa":"/nɜːs plɑːnt/","tag":"restoration role","definition":"a plant that shelters seedlings of other species; a pioneer can serve as a nurse.","definitionCN":"庇护其他物种幼苗的植物；先锋可作为保育植物。"},{"word":"invasive species","ipa":"/ɪnˈveɪsɪv ˈspiːʃiːz/","tag":"impact label","definition":"a non-native species that spreads and causes harm; a pioneer may or may not be invasive.","definitionCN":"扩散并造成危害的非本地物种；先锋未必是入侵种。"},{"word":"early seral species","ipa":"/ˈɜːli ˈsiːrəl ˈspiːʃiːz/","tag":"technical synonym","definition":"a species of the early stages of succession, often used interchangeably with pioneer.","definitionCN":"演替早期阶段的物种，常与 pioneer 互换使用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real etymological images, standard terms, and real relatives.","cn":"正常联想：真实词源意象、标准术语与真实同族词。"},"normal":[{"en":"Pioneer was a foot soldier sent ahead: pioneer species go in first, before soil exists.","cn":"pioneer 是先遣步兵：先锋物种最先进入，那时还没有土壤。"},{"en":"Species is both singular and plural: one pioneer species, many pioneer species.","cn":"species 单复数同形：一个 pioneer species，许多 pioneer species。"},{"en":"Facilitation is the key mechanism: pioneers build soil, later species use it.","cn":"促进是关键机制：先锋造土，后来物种用土。"},{"en":"In secondary succession the pioneer is often a fast annual weed, not a lichen.","cn":"次生演替中的先锋常是速生一年生杂草，而非地衣。"},{"en":"Climax community is the far end of the ladder; pioneer species is the bottom rung.","cn":"climax community 是梯子的远端；pioneer species 是最底一级。"}],"abstract":[{"en":"Picture a single lichen on grey rock: it is the first resident, and its death creates the first patch of soil.","cn":"想象灰色岩石上的一片地衣：它是第一个住户，它的死亡造出第一块土壤。"},{"en":"The term names a job, not a family: fast arrival, fast growth, tolerance of harsh conditions.","cn":"这个词命名的是“岗位”而非“家系”：快速到达、快速生长、耐受恶劣条件。"},{"en":"The pioneer's success is self-limiting: by improving the site it makes room for its successors.","cn":"先锋的成功是自我限制的：它改善地点，从而为后继者腾出空间。"}]},"examples":[{"en":"Mosses and lichens are the pioneer species on the new lava flow.","cn":"苔藓与地衣是新熔岩流上的先锋物种。"},{"en":"The restoration plan selected a nitrogen-fixing pioneer species to start soil formation.","cn":"恢复计划选择一种固氮先锋物种来启动成土过程。"},{"en":"Pioneer species on the abandoned field were mostly wind-dispersed annuals.","cn":"弃耕地上的先锋物种多是风传播的一年生植物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“派你先”——先派你上去占住裸地 → pioneer species 先锋物种","word":"pioneer species"},"root":"pioneer 经法语来自 peon「步兵」（拉丁语 pes「脚」）；species 来自拉丁语 specere「看」，指类别。","sensesIntro":{"en":"Eight senses of pioneer species: bare-ground first colonists, early seral species, soil-building facilitators, restoration nurse plants, invasive early colonizers, secondary-succession pioneers, the functional role itself, and first arrivals in island biogeography.","cn":"pioneer species 的八个义项：裸地首批定殖者、早期演替物种、造土促进者、恢复保育植物、入侵性早期定殖者、次生演替先锋、功能角色本身与岛屿生物地理学中的首批到达者。"},"semanticMap":{"core":{"en":"CORE IMAGE: one lichen on grey rock, the first living patch on a blank surface.","cn":"核心意象：灰色岩石上的一片地衣，是空白表面的第一块生命斑块。"},"chain":["BARE SITE","FIRST ARRIVAL","HARSH TOLERANCE","SOIL BUILDING","SITE CHANGED","SUCCESSORS ARRIVE"],"branches":[{"senses":"S1 · S6","en":"FIRST ARRIVAL: bare ground and post-disturbance fields both reward fast colonization.","cn":"最先到达：裸地与受扰动后的土地都奖赏快速的定殖。"},{"senses":"S2","en":"GENERAL LABEL: early seral species of any kind are called pioneers, even where the ground was not bare.","cn":"通用标签：任何类型的早期演替物种都被称作先锋，即使地面原本并非裸地。"},{"senses":"S3 · S4","en":"FACILITATION: the pioneer changes soil and can be planted as a nurse.","cn":"促进：先锋物种改变土壤，也可作为保育植物被栽种。"},{"senses":"S5","en":"RISK: the same fast-growth strategy can turn a pioneer into a weed.","cn":"风险：同样的快速生长策略可能把先锋变成杂草。"},{"senses":"S7 · S8","en":"ROLE AND DISPERSAL: any suitable species can fill the job, and first arrivals on islands face no competitors.","cn":"角色与扩散：任何合适的物种都能胜任这一角色，而岛屿上的首批到达者没有竞争者。"}]},"affixes":{"intro":{"en":"Pioneer species is a two-word technical phrase; neither word is analysable with a living English prefix. Pioneer has a French agent suffix, species a Latin noun ending.","cn":"pioneer species 是双词技术短语；两词都不含活的英语前缀。pioneer 有法语施事后缀，species 有拉丁名词词尾。"},"latinIntro":{"en":"Latin pes 'foot' yields pedal, pedestrian, and expedite through the pion- branch; specere 'to look' yields species, spectrum, inspect, and perspective.","cn":"拉丁语 pes「脚」经 pion- 一支衍生 pedal、pedestrian、expedite；specere「看」衍生 species、spectrum、inspect、perspective。"},"items":[{"word":"pioneer","structure":"peon/pedonem (foot soldier) + -ier (French agent)","meaning":"one who goes first","meaningCN":"先遣者；先锋（-ier 施事后缀）","example":"Pioneers cleared the road.","exampleCN":"先遣队清理了道路。"},{"word":"pioneering","structure":"pioneer + -ing (adjective)","meaning":"first and innovative","meaningCN":"开创性的","example":"Pioneering work described the stage.","exampleCN":"开创性工作描述了该阶段。"},{"word":"species","structure":"specere (to look) + -ies (noun)","meaning":"a kind or appearance","meaningCN":"类别；外观（-ies 名词词尾）","example":"Several species share the role.","exampleCN":"多个物种共享这一角色。"},{"word":"speciation","structure":"species + -ation (process noun)","meaning":"the formation of new species","meaningCN":"物种形成","example":"Speciation on islands is rapid.","exampleCN":"岛屿上的物种形成很快。"},{"word":"pioneer stage","structure":"pioneer + stage","meaning":"the first seral stage","meaningCN":"第一个演替阶段","example":"The pioneer stage lasts a few years.","exampleCN":"先锋阶段持续数年。"},{"word":"facilitation","structure":"facilis (easy) + -ation","meaning":"making a site easier for others","meaningCN":"使地点更易被他人利用；促进","example":"Facilitation speeds succession.","exampleCN":"促进加速演替。"},{"word":"ruderal","structure":"rudus (rubble) + -al","meaning":"growing on disturbed ground","meaningCN":"生长于受扰地面的","example":"Ruderal plants follow clearing.","exampleCN":"路旁植物随清理出现。"},{"word":"colonizer","structure":"colony + -izer (agent)","meaning":"one that establishes in a new place","meaningCN":"在新地点建立者","example":"Wind is the main colonizer agent.","exampleCN":"风是主要的定殖媒介。"}],"latinEntries":[{"word":"pes","structure":"pes, pedis (third declension)","meaning":"foot","meaningCN":"脚"},{"word":"pedonem","structure":"Late Latin accusative of pedo","meaning":"foot soldier","meaningCN":"步兵"},{"word":"specere","structure":"specere (third conjugation)","meaning":"to look at","meaningCN":"看；观察"},{"word":"species","structure":"specere + -ies","meaning":"appearance, kind","meaningCN":"外观；类别"}]}},{"word":"climax community","ipa_uk":"/ˈklaɪmæks kəˈmjuːnəti/","ipa_us":"/ˈklaɪmæks kəˈmjuːnəti/","definition_zh":"顶极群落；顶极群落（演替终点的群落）","definition_en":"the relatively stable, self-replacing community that classical succession theory expected at the end of a successional sequence","core_image":"一条演替阶梯的顶端：一片能自我更新的成熟森林","scene":"在这片保护区里，山毛榉林已经能够自我更新，被早期生态学家视为该地区的顶极群落。 In this reserve the beech forest renews itself, and early ecologists treated it as the climax community of the region.","sceneCN":"这里 climax community 是「顶极群落」（第 1 个义项：经典演替理论的终点群落）；句意：在这片保护区里，山毛榉林能自我更新，被早期生态学家视为该地区的顶极群落。","pos":[{"tag":"n.","zh":"顶极群落；演替终点群落（可数，复数为 climax communities）"}],"collocations":[{"phrase":"climax community theory","zh":"顶极群落理论"},{"phrase":"regional climax community","zh":"区域顶极群落"},{"phrase":"climax community of a forest","zh":"森林顶极群落"},{"phrase":"reach the climax community","zh":"达到顶极群落"},{"phrase":"climax community concept","zh":"顶极群落概念"},{"phrase":"disclimax community","zh":"偏途顶极群落"}],"forms":[{"label":"复数","form":"climax communities"},{"label":"相关名词（顶极）","form":"climax"},{"label":"相关名词（演替）","form":"succession"},{"label":"相关名词（先锋物种）","form":"pioneer species"}],"derivatives":[{"word":"climax","pos":"n.","zh":"顶极；高潮；顶点"},{"word":"climactic","pos":"adj.","zh":"顶极的；高潮的"},{"word":"community","pos":"n.","zh":"群落；社群"},{"word":"disclimax","pos":"n.","zh":"偏途顶极群落"}],"senses":[{"no":"01","title":"The traditional endpoint of succession","titleCN":"经典演替的终点","definition":"the final, stable community that a site is said to reach at the end of succession","definitionCN":"演替结束时地点据称达到的最终稳定群落","example":"The old textbook described oak forest as the climax community of the lowlands.","exampleCN":"旧教科书把橡树林描述为低地的顶极群落。","why":"Climax comes from Greek klimax 'ladder': the community at the top rung, beyond which succession is said to go no further.","whyCN":"climax 来自希腊语 klimax「梯子」：最高一级的群落，据说演替到此不再向上。"},{"no":"02","title":"A self-replacing mature community","titleCN":"能自我更新的成熟群落","definition":"a community whose dominant species reproduce within the site so that the same structure persists","definitionCN":"优势种能在本地繁殖、使同一结构持续存在的群落","example":"The beech stand is a climax community because seedlings grow beneath the canopy.","exampleCN":"这片山毛榉林是顶极群落，因为幼苗能在林冠下生长。","why":"The test is reproduction, not age: a community is climactic when its own offspring can replace its adults, closing the life cycle in place.","whyCN":"检验标准是繁殖而非年龄：当群落自身的后代能替代成年个体、在原地闭合生活史时，它就是顶极群落。"},{"no":"03","title":"Climatic climax","titleCN":"气候顶极群落","definition":"the community determined by the regional climate, especially temperature and rainfall","definitionCN":"由区域气候（尤其温度与降水）决定的群落","example":"The climatic climax of the region is temperate broadleaf forest.","exampleCN":"该地区的气候顶极是温带阔叶林。","why":"Classical theory made climate the master variable: if soil and disturbance were average, the regional climate would select one final community.","whyCN":"经典理论把气候当作主导变量：若土壤与干扰处于平均状态，区域气候将选出唯一的最终群落。"},{"no":"04","title":"Edaphic climax","titleCN":"土壤顶极群落","definition":"a stable community determined by unusual local soil conditions rather than by climate","definitionCN":"由特殊局部土壤条件而非气候决定的稳定群落","example":"Serpentine soils support an edaphic climax unlike the surrounding forest.","exampleCN":"蛇纹岩土壤支撑的土壤顶极与周围森林不同。","why":"Edaphic means 'of the soil'. Where soil overrides climate, the ladder stops at a different top rung, so theory allowed multiple climaxes.","whyCN":"edaphic 意为“土壤的”。当土壤压过气候时，梯子停在另一个顶端，因此理论允许存在多个顶极。"},{"no":"05","title":"Fire-maintained climax","titleCN":"火维持的顶极群落","definition":"a community kept stable by recurrent fire rather than by reaching a fire-free endpoint","definitionCN":"由反复火灾而非无火终点维持稳定的群落","example":"The pine savanna is a fire climax maintained by light burns every few years.","exampleCN":"松树稀树草原是靠每隔几年轻度火烧维持的火顶极。","why":"If a disturbance is frequent and predictable, the 'stable end' is actually a stable cycle; the community persists by burning, not by escaping fire.","whyCN":"如果干扰频繁且可预测，“稳定终点”实际上是一个稳定循环；群落靠燃烧而持续，而不是靠避开火。"},{"no":"06","title":"Disclimax: human-induced stable state","titleCN":"偏途顶极：人为造成的稳定状态","definition":"a stable community maintained by human land use such as grazing or mowing","definitionCN":"由放牧、割草等人类土地利用维持的稳定群落","example":"Continuous grazing created a disclimax of unpalatable grasses.","exampleCN":"持续放牧造成了不可食草类的偏途顶极。","why":"The prefix dis- marks a deflection: human pressure holds the site away from the climate-selected top, yet the resulting community is still stable.","whyCN":"前缀 dis- 标记“偏转”：人类压力使地点偏离气候选择的顶端，但形成的群落仍是稳定的。"},{"no":"07","title":"Mosaic or polyclimax","titleCN":"镶嵌或多元顶极","definition":"the view that a landscape contains several stable communities at once, depending on site conditions","definitionCN":"认为景观同时包含多个稳定群落的观点，取决于立地条件","example":"The reserve is a polyclimax mosaic of bog, pine, and beech stands.","exampleCN":"保护区是沼泽、松林与山毛榉林的多元顶极镶嵌。","why":"The suffix poly- means many: instead of one top rung, the landscape has several stable communities side by side, each tied to its own site conditions.","whyCN":"前缀 poly- 意为“多”：景观没有唯一顶端，而是多个稳定群落并列，各自绑定自己的立地条件。"},{"no":"08","title":"The concept as a contested model","titleCN":"作为受争议模型的概念","definition":"the classical idea itself, now treated as one hypothesis rather than a law of nature","definitionCN":"经典观念本身，如今被视为一种假说而非自然法则","example":"Modern ecology rarely expects a single climax community for a whole region.","exampleCN":"现代生态学很少认为整个区域只有单一顶极群落。","why":"Non-equilibrium ecology showed that disturbance, dispersal, and chance keep communities changing, so the 'top rung' is now understood as one possible state among several.","whyCN":"非平衡生态学表明干扰、扩散与偶然使群落持续变化，因此“最高一级”如今被理解为若干可能状态之一。"}],"etymology":{"intro":{"en":"Climax is Greek klimax 'ladder', used in rhetoric before ecology; community is Latin communitas. The collocation is a twentieth-century ecological term.","cn":"climax 是希腊语 klimax「梯子」，先用于修辞学后用于生态学；community 是拉丁语 communitas。该搭配是 20 世纪生态学术语。"},"items":[{"era":"GREEK","en":"klimax meant 'ladder, staircase' and also a rhetorical climax, a graded ascent of meaning; the verb klinein 'to lean' is related.","cn":"klimax 意为“梯子、楼梯”，也指修辞上的层进；动词 klinein「倾斜、倚靠」与之相关。"},{"era":"LATIN","en":"community < communitas 'fellowship', from communis 'common, shared'. The phrase therefore says 'the shared community at the top of the ladder'.","cn":"community < communitas「共同体」，来自 communis「共同的、共享的」。因此短语意为“梯子顶端的共同群落”。"},{"era":"20C.","en":"Frederic Clements made climax the endpoint of succession in early twentieth-century American ecology; the phrase climax community became standard.","cn":"Clements 在 20 世纪初的美国生态学中把 climax 设为演替终点；climax community 成为标准术语。"},{"era":"MID 20C.","en":"Critics such as Gleason and later non-equilibrium theorists argued that communities rarely reach a single stable endpoint, weakening the classical term.","cn":"Gleason 等批评者以及后来的非平衡理论家认为群落很少达到单一稳定终点，削弱了经典术语。"},{"era":"MODERN ENGLISH","en":"Modern usage keeps the phrase but treats it as a simplified model; edaphic, fire, and human-maintained climaxes show that the 'top' depends on conditions.","cn":"现代用法保留该短语，但把它当作简化模型；土壤顶极、火顶极与人为维持顶极表明“顶端”取决于条件。"}]},"similar":{"note":{"en":"The first group separates climax terms, the second compares end-state and stable-state concepts.","cn":"第一组区分顶极相关术语，第二组比较终点状态与稳定状态概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"climax","ipa":"/ˈklaɪmæks/","tag":"base noun","definition":"the top of a graded sequence; in ecology the endpoint, in narrative the peak.","definitionCN":"层进序列的顶端；生态学指终点，叙事中指高潮。"},{"word":"climactic","ipa":"/klaɪˈmæktɪk/","tag":"adjective","definition":"relating to a climax or peak; not the ecological noun.","definitionCN":"与高潮或顶点有关的；不是生态名词。"},{"word":"disclimax","ipa":"/dɪsˈklaɪmæks/","tag":"subtype","definition":"a stable community maintained by human disturbance, deflected from the climatic climax.","definitionCN":"由人为干扰维持、偏离气候顶极的稳定群落。"},{"word":"pioneer species","ipa":"/ˌpaɪəˈnɪə ˈspiːʃiːz/","tag":"opposite stage","definition":"the first colonizers, at the bottom of the same ladder.","definitionCN":"同一梯子最底端的首批定殖者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mature forest","ipa":"/məˈtʃʊə ˈfɒrɪst/","tag":"description","definition":"a forest with old trees and closed canopy; it may or may not be a climax community.","definitionCN":"有老树与郁闭林冠的森林；它未必是顶极群落。"},{"word":"steady state","ipa":"/ˈstedi steɪt/","tag":"systems","definition":"a condition that stays constant because inputs and outputs balance; stability need not imply climax.","definitionCN":"输入输出平衡而保持恒定的状态；稳定不必然意味着顶极。"},{"word":"potential natural vegetation","ipa":"/pəˈtenʃl ˈnætʃrəl ˌvedʒəˈteɪʃn/","tag":"mapping","definition":"the vegetation a site would support without human interference; a mapping analogue of climax.","definitionCN":"无人类干扰时某地可支持的植被；顶极的制图类比。"},{"word":"biome","ipa":"/ˈbaɪəʊm/","tag":"scale","definition":"a continental-scale vegetation type; climax community is site-scale.","definitionCN":"大陆尺度的植被类型；顶极群落是立地尺度。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the ladder image, standard ecological terms, and real contrasts.","cn":"正常联想：梯子意象、标准生态术语与真实对比。"},"normal":[{"en":"Climax is Greek for ladder: the climax community is the top rung of succession.","cn":"climax 在希腊语中意为梯子：顶极群落就是演替的最高一级。"},{"en":"The test of climax is self-replacement: seedlings grow under the adults.","cn":"顶极的检验是自我替代：幼苗在成年个体下生长。"},{"en":"Climatic climax uses climate as the judge; edaphic climax uses soil.","cn":"气候顶极以气候为判据；土壤顶极以土壤为判据。"},{"en":"Fire climax and disclimax are stable states held by disturbance, not by reaching a peaceful end.","cn":"火顶极与偏途顶极是由干扰维持的稳定状态，而非达到平静终点。"},{"en":"Modern ecology prefers mosaic or non-equilibrium views over one regional climax.","cn":"现代生态学更倾向镶嵌或非平衡观点，而非单一区域顶极。"}],"abstract":[{"en":"Picture a staircase whose top step is a forest that can plant its own replacement.","cn":"想象一架楼梯，最高一级是一片能种出自身替代者的森林。"},{"en":"The phrase assumes a destination; later ecology asks whether the staircase even has a last step.","cn":"这个短语假定存在终点；后来的生态学则质疑这架梯子是否真有最后一级。"},{"en":"Every climax is conditional: remove the condition (soil, fire, grazing) and the top rung moves.","cn":"每个顶极都是有条件的：去掉条件（土壤、火、放牧），顶端就会移动。"}]},"examples":[{"en":"The classical model predicted a beech climax community for the whole region.","cn":"经典模型预测整个区域将形成山毛榉顶极群落。"},{"en":"Grazing created a disclimax that only looks natural to a casual visitor.","cn":"放牧造成了偏途顶极，只有随意到访者才会觉得它自然。"},{"en":"The reserve is managed as a mosaic rather than a single climax community.","cn":"保护区按镶嵌格局管理，而不是追求单一顶极群落。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“克莱马克斯”——爬梯子到最顶端那一步，群落不再往上换 → climax community 顶极群落","word":"climax community"},"root":"climax 来自希腊语 klimax（梯子、层进），community 来自拉丁语 communitas（共同体）。","sensesIntro":{"en":"Eight senses of climax community: the classical endpoint, a self-replacing mature stand, climate- and soil-determined types, fire- and human-maintained stable states, the mosaic view, and the concept as a contested model.","cn":"climax community 的八个义项：经典终点、自我更新的成熟林分、气候与土壤决定类型、火与人为维持的稳定状态、镶嵌观点，以及作为受争议模型的概念。"},"semanticMap":{"core":{"en":"CORE IMAGE: the top step of a successional staircase, occupied by a self-renewing forest.","cn":"核心意象：演替阶梯的最高一级，由能自我更新的森林占据。"},"chain":["LADDER","STAGES CLIMBED","STABLE STATE","SELF-REPLACEMENT","CONDITIONS HOLD","ENDPOINT OR MYTH"],"branches":[{"senses":"S1","en":"CLASSICAL ENDPOINT: the traditional view treats the final community as the end of the ladder.","cn":"经典终点：传统观点把最终群落看作演替阶梯的终点。"},{"senses":"S2","en":"SELF-REPLACEMENT: stability is defined by the community renewing its own members.","cn":"自我更新：稳定性由群落能够更新自身成员来定义。"},{"senses":"S3 · S4","en":"DETERMINANTS: climate sets the regional top; soil can set a local one.","cn":"决定因素：气候设定区域性的顶点；土壤可以设定局部的顶点。"},{"senses":"S5 · S6","en":"DISTURBANCE: fire and grazing maintain stable states that are not peaceful endpoints.","cn":"扰动：火与放牧维持着并非平静终点的稳定状态。"},{"senses":"S7 · S8","en":"REVISION: mosaics and non-equilibrium theory replace the single regional climax.","cn":"修正：镶嵌格局与非平衡理论取代了单一的区域顶极。"}]},"affixes":{"intro":{"en":"The phrase joins two borrowed nouns, Greek klimax and Latin communitas. English adds no prefix; the ecological meaning is carried by the collocation.","cn":"这个短语连接两个借入名词：希腊语 klimax 与拉丁语 communitas。英语不加前缀，生态含义由搭配承担。"},"latinIntro":{"en":"Greek klinein 'to lean' yields climax, climate, and clinic; Latin communis yields community, communal, and communicate.","cn":"希腊语 klinein「倾斜」衍生 climax、climate、clinic；拉丁语 communis 衍生 community、communal、communicate。"},"items":[{"word":"climax","structure":"Greek klimax (ladder)","meaning":"the top of a graded sequence","meaningCN":"层进序列的顶端","example":"The stand is called a climax.","exampleCN":"该林分被称为顶极。"},{"word":"climax community","structure":"climax + community","meaning":"the stable endpoint community","meaningCN":"稳定的终点群落","example":"The climax community is self-replacing.","exampleCN":"顶极群落能自我替代。"},{"word":"disclimax","structure":"dis- (away) + climax","meaning":"a deflected stable community","meaningCN":"偏离的稳定群落（dis- 偏离）","example":"Grazing produced a disclimax.","exampleCN":"放牧造成了偏途顶极。"},{"word":"climactic","structure":"climax + -ic (adjective)","meaning":"relating to a peak","meaningCN":"与顶点或高潮有关的","example":"The final scene is climactic.","exampleCN":"最后一幕是高潮。"},{"word":"community","structure":"communis + -ity","meaning":"a group sharing a place","meaningCN":"共享一地的群体","example":"The community includes many species.","exampleCN":"该群落包含许多物种。"},{"word":"climate","structure":"klinein (to lean) + -ma","meaning":"the slope of the earth toward the sun","meaningCN":"地球向阳的倾斜；气候","example":"Climate sets the regional climax.","exampleCN":"气候设定区域顶极。"},{"word":"clinic","structure":"klinein (to lean over a bed)","meaning":"bedside practice","meaningCN":"床旁诊疗；诊所","example":"The word shares the 'lean' root.","exampleCN":"该词共享“倾斜”词根。"},{"word":"communal","structure":"communis + -al","meaning":"shared by a group","meaningCN":"群体共享的","example":"Communal nesting occurs in colonies.","exampleCN":"群体营巢见于聚居动物。"}],"latinEntries":[{"word":"klimax","structure":"Greek klimax (noun)","meaning":"ladder, staircase","meaningCN":"梯子；楼梯"},{"word":"klinein","structure":"Greek klinein (verb)","meaning":"to lean, slope","meaningCN":"倾斜；倚靠"},{"word":"communis","structure":"Latin adjective","meaning":"common, shared","meaningCN":"共同的；共享的"},{"word":"communitas","structure":"communis + -itas","meaning":"community, fellowship","meaningCN":"共同体；情谊"}]}},{"word":"ecosystem stability","ipa_uk":"/ˈiːkəʊsɪstəm stəˈbɪləti/","ipa_us":"/ˈiːkoʊsɪstəm stəˈbɪləti/","definition_zh":"生态系统稳定性","definition_en":"the ability of an ecosystem to remain within its normal range of structure and function, or to return to it after disturbance","core_image":"一只球在谷底：被推一下会晃动，但最终回到原来的凹槽","scene":"这片草地在连续三年干旱后仍维持了主要物种与生产力，研究者用它来说明生态系统稳定性。 After three dry years this grassland kept its main species and productivity, and researchers used it to illustrate ecosystem stability.","sceneCN":"这里 ecosystem stability 是「生态系统稳定性」（第 1 个义项：系统在扰动下维持结构与功能的能力）；句意：这片草地在连续三年干旱后仍维持主要物种与生产力，研究者用它来说明生态系统稳定性。","pos":[{"tag":"n.","zh":"生态系统稳定性（多作不可数）"}],"collocations":[{"phrase":"ecosystem stability and resilience","zh":"生态系统稳定性与恢复力"},{"phrase":"maintain ecosystem stability","zh":"维持生态系统稳定性"},{"phrase":"ecosystem stability under disturbance","zh":"扰动下的生态系统稳定性"},{"phrase":"loss of ecosystem stability","zh":"生态系统稳定性的丧失"},{"phrase":"ecosystem stability indicator","zh":"生态系统稳定性指标"},{"phrase":"ecosystem stability threshold","zh":"生态系统稳定性阈值"}],"forms":[{"label":"复数（指多种稳定性类型）","form":"ecosystem stabilities"},{"label":"相关名词（生态系统）","form":"ecosystem"},{"label":"相关名词（稳定）","form":"stability"},{"label":"相关形容词（稳定的）","form":"stable"}],"derivatives":[{"word":"ecosystem","pos":"n.","zh":"生态系统"},{"word":"stable","pos":"adj.","zh":"稳定的"},{"word":"stabilize","pos":"v.","zh":"使稳定"},{"word":"destabilize","pos":"v.","zh":"使失稳"}],"senses":[{"no":"01","title":"Resistance to change","titleCN":"抵抗变化的能力","definition":"the capacity of an ecosystem to keep its structure and function when a disturbance arrives","definitionCN":"干扰到来时生态系统维持结构与功能的能力","example":"Diverse grasslands show high resistance and thus high ecosystem stability under drought.","exampleCN":"多样性高的草地在干旱下表现出高抵抗力，因而具有高生态系统稳定性。","why":"Stability comes from Latin stare 'to stand'. Resistance is the first way of standing: the system absorbs the push without moving much.","whyCN":"stability 来自拉丁语 stare「站立」。抵抗是“站立”的第一种方式：系统承受推力而移动不大。"},{"no":"02","title":"Return after disturbance","titleCN":"扰动后的回归","definition":"the capacity of a system to recover its previous state after being displaced","definitionCN":"系统被推离后恢复原状态的能力","example":"The lake returned to clear water, a sign of ecosystem stability after the nutrient pulse.","exampleCN":"湖泊恢复清澈，这是营养脉冲后生态系统稳定性的标志。","why":"The second way of standing is to fall and then come back. In ecology this return is often called resilience, a component of overall stability.","whyCN":"“站立”的第二种方式是跌倒后再回来。生态学中这种回归常称 resilience，是整体稳定性的一部分。"},{"no":"03","title":"Constancy over time","titleCN":"随时间的恒定性","definition":"the degree to which biomass, populations, or functions stay nearly constant through time","definitionCN":"生物量、种群或功能随时间保持近乎不变的程度","example":"Long-term plots reveal the ecosystem stability of old-growth forest.","exampleCN":"长期样地揭示了原始林的生态系统稳定性。","why":"Stability can mean simply 'not varying'. Here the measurement is a time series, and the absence of large swings is the evidence.","whyCN":"稳定性可以仅指“变化不大”。这里的度量是时间序列，没有大幅波动就是证据。"},{"no":"04","title":"Absence of oscillation or chaos","titleCN":"无振荡或混沌","definition":"the condition in which populations or processes do not enter large regular or irregular cycles","definitionCN":"种群或过程不进入大幅规则或不规则循环的状态","example":"Predator-prey models predict oscillations unless stabilizing feedbacks act.","exampleCN":"除非有稳定化反馈，否则捕食—猎物模型会预测振荡。","why":"Mathematical stability is about behaviour near an equilibrium: the system either damps disturbances or amplifies them into cycles.","whyCN":"数学稳定性关乎平衡点附近的行为：系统要么阻尼扰动，要么把它放大成循环。"},{"no":"05","title":"Stability of functions and services","titleCN":"功能与服务的稳定性","definition":"the reliable delivery of processes such as productivity, nutrient cycling, and water retention","definitionCN":"生产力、养分循环与水源涵养等过程的可靠供给","example":"Pollinator loss threatens the ecosystem stability of crop production.","exampleCN":"传粉者丧失威胁作物生产的生态系统稳定性。","why":"The focus shifts from species counts to what the system does: a stable ecosystem keeps delivering the same functions even when composition shifts.","whyCN":"焦点从物种数量转向系统功能：稳定生态系统即使在组成变化时也持续提供相同功能。"},{"no":"06","title":"Persistence across scales","titleCN":"跨尺度的持续存在","definition":"the maintenance of ecosystem identity at local, landscape, and regional scales despite disturbances at each scale","definitionCN":"尽管各尺度都有干扰，生态系统在局域、景观与区域尺度上仍保持自身特征","example":"Ecosystem stability at the landscape scale depends on patches recovering at different times.","exampleCN":"景观尺度的生态系统稳定性依赖斑块在不同时间恢复。","why":"A patch may change while the landscape persists; stability is scale-dependent, and what looks unstable locally can be stable regionally.","whyCN":"斑块可以变化而景观持续存在；稳定性依赖尺度，局域看似不稳的状态在区域上可能稳定。"},{"no":"07","title":"Stability as absence of regime shift","titleCN":"作为未发生状态转换的稳定性","definition":"the retention of a regime, avoiding a shift to an alternative stable state","definitionCN":"保持原有状态、避免转向替代稳定状态","example":"Nutrient loading reduced ecosystem stability and pushed the lake into an algal regime.","exampleCN":"养分负荷降低了生态系统稳定性，把湖泊推入藻类状态。","why":"Modern theory defines stability partly by what does not happen: the system stays in its basin of attraction rather than crossing a threshold.","whyCN":"现代理论部分以“没有发生什么”来定义稳定性：系统留在其吸引域内，而没有越过阈值。"},{"no":"08","title":"Stability as a management goal","titleCN":"作为管理目标的稳定性","definition":"a desired property that conservation and restoration projects aim to maintain or restore","definitionCN":"保护与恢复项目力求维持或恢复的理想属性","example":"Managers monitor ecosystem stability as one criterion of restoration success.","exampleCN":"管理者把生态系统稳定性作为恢复成功的标准之一。","why":"Policy turns a measured property into a target: 'stable' becomes a criterion written into plans, even though the underlying science defines it in several ways.","whyCN":"政策把测量属性变成目标：“稳定”被写入计划的准则，尽管底层科学对它有多种定义。"}],"etymology":{"intro":{"en":"Ecosystem was coined in 1935 by combining Greek oikos 'house' with systema 'organized whole'; stability comes from Latin stare 'to stand'. The phrase is a modern compound.","cn":"ecosystem 于 1935 年由希腊语 oikos「住所」与 systema「有组织的整体」组合而成；stability 来自拉丁语 stare「站立」。该短语是现代复合词。"},"items":[{"era":"GREEK","en":"oikos 'house, dwelling' supplies eco-; systema 'organized whole' comes from syn- 'together' + histanai 'to place, stand'.","cn":"oikos「住所」提供 eco-；systema「有组织的整体」来自 syn-「一起」+ histanai「放置、站立」。"},{"era":"1935","en":"The ecologist A. G. Tansley coined ecosystem for the community together with its physical environment, treating them as one unit.","cn":"生态学家 Tansley 创造 ecosystem 一词，指群落与其物理环境的整体单元。"},{"era":"LATIN","en":"stability < stabilitas 'firmness' < stabilis 'firm, steadfast' < stare 'to stand'. The same stare gives stable, station, statue, and constant.","cn":"stability < stabilitas「稳固」< stabilis「坚实、坚定」< stare「站立」。同一个 stare 还衍生 stable、station、statue、constant。"},{"era":"MID 20C.","en":"Ecosystem stability became a central question when ecologists studied how diversity affects resistance and recovery.","cn":"当生态学家研究多样性如何影响抵抗与恢复时，生态系统稳定性成为核心问题。"},{"era":"LATE 20C.","en":"Resilience theory separated resistance, return time, and regime shifts, giving 'stability' several measurable components.","cn":"恢复力理论把抵抗、回归时间与状态转换分开，使“稳定性”具有若干可测成分。"},{"era":"MODERN ENGLISH","en":"Modern usage treats ecosystem stability as an umbrella term covering resistance, resilience, constancy, and persistence.","cn":"现代用法把生态系统稳定性当作涵盖抵抗、恢复力、恒定性与持续性的总称。"}]},"similar":{"note":{"en":"The first group separates stability terms, the second compares system properties.","cn":"第一组区分稳定性术语，第二组比较系统属性。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"resilience","ipa":"/rɪˈzɪliəns/","tag":"component","definition":"the capacity to return after displacement; one part of ecosystem stability.","definitionCN":"被推离后回归的能力；生态系统稳定性的一部分。"},{"word":"resistance","ipa":"/rɪˈzɪstəns/","tag":"component","definition":"the capacity to resist displacement in the first place.","definitionCN":"首先抵抗被推离的能力。"},{"word":"stabilization","ipa":"/ˌsteɪbəlaɪˈzeɪʃn/","tag":"process","definition":"an action that makes something stable; the noun of the verb, not the property.","definitionCN":"使某物稳定的行动；是动词名词化，而非属性。"},{"word":"constancy","ipa":"/ˈkɒnstənsi/","tag":"measurement","definition":"the degree of non-variation over time; a measurable face of stability.","definitionCN":"随时间不变的程度；稳定性的可测面向。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equilibrium","ipa":"/ˌiːkwɪˈlɪbriəm/","tag":"state","definition":"a balanced state; stability is the behaviour around it.","definitionCN":"平衡状态；稳定性是围绕它的行为。"},{"word":"persistence","ipa":"/pəˈsɪstəns/","tag":"outcome","definition":"remaining present through time; it is the result that stability protects.","definitionCN":"随时间持续存在；是稳定性所保护的结果。"},{"word":"robustness","ipa":"/rəʊˈbʌstnəs/","tag":"engineering","definition":"the ability to keep functioning under perturbation; common in resilience engineering.","definitionCN":"受扰时仍能运作的能力；常见于恢复力工程。"},{"word":"sustainability","ipa":"/səˌsteɪnəˈbɪləti/","tag":"human goal","definition":"the capacity to continue without degrading; it adds a normative, long-term human aim.","definitionCN":"不退化地持续的能力；增加了规范性的长期人类目标。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real roots, standard components, and real contrasts.","cn":"正常联想：真实词根、标准成分与真实对比。"},"normal":[{"en":"stare means to stand: stability is the system still standing after a push.","cn":"stare 意为站立：稳定性就是被推之后系统仍站着。"},{"en":"Resistance is standing firm; resilience is standing up again. Both are parts of stability.","cn":"抵抗是站稳；恢复力是再站起来。两者都是稳定性的一部分。"},{"en":"Ecosystem = oikos + systema: the 'household' treated as one organized whole.","cn":"ecosystem = oikos + systema：把“家宅”当作一个有组织的整体。"},{"en":"Constancy is stability seen as a flat line on a graph.","cn":"恒定性是稳定性在图上的平直线。"},{"en":"Regime shift is stability lost: the ball leaves its valley for another one.","cn":"状态转换是稳定性丧失：球离开自己的谷底，进入另一个谷底。"}],"abstract":[{"en":"Picture a ball in a bowl: resistance is how hard you must push, resilience is how fast it rolls back, and stability names both.","cn":"想象碗里的一只球：抵抗是要用多大力推，恢复力是滚回多快，而稳定性命名两者。"},{"en":"The phrase is not one number; it is a family of behaviours united by the idea of staying in the same basin.","cn":"这个短语不是一个数字，而是一组行为，它们因“留在同一吸引域”而统一。"},{"en":"A system can be stable in function while changing in composition, so 'stable' never means 'unchanging'.","cn":"系统可以在功能上稳定而组成变化，因此“稳定”从不等于“不变”。"}]},"examples":[{"en":"Diverse communities often show greater ecosystem stability under drought.","cn":"多样性高的群落在干旱下常表现出更强的生态系统稳定性。"},{"en":"The lake lost ecosystem stability when nutrient loading crossed a threshold.","cn":"当养分负荷越过阈值，该湖失去了生态系统稳定性。"},{"en":"Restoration projects now assess ecosystem stability, not just species richness.","cn":"恢复项目如今评估生态系统稳定性，而不只是物种丰富度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一个系统站稳了”——被推一下还能回到原位 → ecosystem stability 生态系统稳定性","word":"ecosystem stability"},"root":"ecosystem 为 1935 年由希腊语 oikos（住所）+ systema（整体）造出；stability 来自拉丁语 stare（站立）。","sensesIntro":{"en":"Eight senses of ecosystem stability: resistance, return, constancy, absence of oscillation, functional reliability, cross-scale persistence, avoidance of regime shift, and the same property used as a management target.","cn":"ecosystem stability 的八个义项：抵抗、回归、恒定性、无振荡、功能可靠、跨尺度持续、避免状态转换，以及作为管理目标的同一属性。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ball in a bowl, pushed but returning to the bottom.","cn":"核心意象：碗中的球被推动后又回到碗底。"},"chain":["SYSTEM","PERTURBATION","ABSORB OR MOVE","RETURN","SAME BASIN","CONTINUED FUNCTION"],"branches":[{"senses":"S1","en":"RESISTANCE: the system holds its structure when pushed.","cn":"抵抗力：系统受到推动时仍保持自身结构。"},{"senses":"S3","en":"CONSTANCY: biomass and composition stay steady through ordinary years.","cn":"恒定性：在平常年份里，生物量与组成保持稳定。"},{"senses":"S2 · S4","en":"RETURNING: recovery and damped dynamics describe how the system comes back.","cn":"回归：恢复过程与阻尼动态描述系统如何回到原状。"},{"senses":"S5 · S6","en":"FUNCTION AND SCALE: services persist, and landscape stability can coexist with local change.","cn":"功能与尺度：生态系统服务持续存在，景观尺度的稳定可与局部的变化并存。"},{"senses":"S7 · S8","en":"THRESHOLDS AND POLICY: avoiding a regime shift becomes a criterion for managers.","cn":"阈值与政策：避免状态转换成为管理者的判定标准。"}]},"affixes":{"intro":{"en":"Ecosystem is a modern Greek-Latin compound; stability is a Latin noun from stare. The phrase has no single prefix and is built as a noun plus noun.","cn":"ecosystem 是现代希腊—拉丁复合词；stability 是来自 stare 的拉丁名词。该短语没有单一前缀，按名词加名词构成。"},"latinIntro":{"en":"oikos yields ecology, ecosystem, economy, and ecumene; stare yields stable, stability, station, statue, and constant.","cn":"oikos 衍生 ecology、ecosystem、economy、ecumene；stare 衍生 stable、stability、station、statue、constant。"},"items":[{"word":"ecosystem","structure":"oikos (house) + systema (whole)","meaning":"community plus physical environment","meaningCN":"群落加物理环境","example":"The ecosystem includes soil and water.","exampleCN":"生态系统包括土壤与水。"},{"word":"stability","structure":"stabilis (firm) + -ity (noun)","meaning":"the state of standing firm","meaningCN":"稳固的状态（-ity 名词）","example":"Stability is measured over decades.","exampleCN":"稳定性以数十年为尺度测量。"},{"word":"stable","structure":"stare (to stand) + -ble (adjective)","meaning":"able to stand firm","meaningCN":"能站稳的；稳定的","example":"The state is stable but not fixed.","exampleCN":"该状态稳定但并非固定。"},{"word":"stabilize","structure":"stable + -ize (verb)","meaning":"to make firm","meaningCN":"使稳定","example":"Feedback can stabilize populations.","exampleCN":"反馈能使种群稳定。"},{"word":"destabilize","structure":"de- (down) + stabilize","meaning":"to make unstable","meaningCN":"使失稳","example":"Invasion destabilized the food web.","exampleCN":"入侵使食物网失稳。"},{"word":"resistance","structure":"resistere (to withstand) + -ance","meaning":"the capacity to withstand","meaningCN":"抵抗能力","example":"Resistance buffers the first shock.","exampleCN":"抵抗缓冲第一次冲击。"},{"word":"resilience","structure":"resilire (to leap back) + -ence","meaning":"the capacity to return","meaningCN":"回归能力","example":"Resilience sets the recovery time.","exampleCN":"恢复力决定恢复时间。"},{"word":"system","structure":"systema (organized whole)","meaning":"a set of interacting parts","meaningCN":"相互作用的部件集合","example":"The system has many feedbacks.","exampleCN":"该系统有许多反馈。"}],"latinEntries":[{"word":"oikos","structure":"Greek oikos (noun)","meaning":"house, dwelling","meaningCN":"住所；家宅"},{"word":"systema","structure":"Greek systema (noun)","meaning":"organized whole","meaningCN":"有组织的整体"},{"word":"stare","structure":"stare (first conjugation)","meaning":"to stand","meaningCN":"站立"},{"word":"stabilitas","structure":"stabilis + -itas","meaning":"firmness","meaningCN":"稳固；坚定"}]}},{"word":"resilience","ipa_uk":"/rɪˈzɪliəns/","ipa_us":"/rɪˈzɪliəns/","definition_zh":"恢复力；韧性；回弹能力","definition_en":"the capacity to recover quickly from difficulties, or of a system to absorb disturbance and return to its previous state or function","core_image":"被压弯的芦苇在风停后弹回原位","scene":"洪水退去后，这片芦苇地在两个季节内恢复了原有高度与盖度，显示出很强的恢复力。 After the flood receded, this reed bed recovered its former height and cover within two seasons, showing strong resilience.","sceneCN":"这里 resilience 是「恢复力」（第 1 个义项：受扰后回到原状态的能力）；句意：洪水退去后，这片芦苇地在两个季节内恢复了原有高度与盖度，显示出很强的恢复力。","pos":[{"tag":"n.","zh":"恢复力；韧性；回弹能力（多作不可数）"}],"collocations":[{"phrase":"ecological resilience","zh":"生态恢复力"},{"phrase":"build resilience","zh":"建立韧性"},{"phrase":"resilience to stress","zh":"对压力的恢复力"},{"phrase":"resilience of a community","zh":"社区的韧性"},{"phrase":"resilience engineering","zh":"恢复力工程"},{"phrase":"loss of resilience","zh":"恢复力的丧失"}],"forms":[{"label":"复数（少见，指多种恢复力）","form":"resiliences"},{"label":"形容词","form":"resilient"},{"label":"副词","form":"resiliently"},{"label":"同义名词变体（美式）","form":"resiliency"}],"derivatives":[{"word":"resilient","pos":"adj.","zh":"有恢复力的；有韧性的"},{"word":"resiliently","pos":"adv.","zh":"有韧性地；能恢复地"},{"word":"resiliency","pos":"n.","zh":"恢复力（美式变体）"},{"word":"resile","pos":"v.","zh":"弹回；撤回（法律与正式用语）"}],"senses":[{"no":"01","title":"Ecological capacity to absorb disturbance","titleCN":"生态学上的吸收扰动能力","definition":"the capacity of an ecosystem to absorb disturbance and keep its structure and functions","definitionCN":"生态系统吸收扰动并保持结构与功能的能力","example":"Coral reef resilience depends on herbivorous fish and clean water.","exampleCN":"珊瑚礁的恢复力依赖植食性鱼类与清洁的水。","why":"From Latin resilire 'to leap back', resilience is the ability to be pushed and still spring back into the same shape.","whyCN":"来自拉丁语 resilire「跳回」，resilience 就是被推之后仍弹回原形的能力。"},{"no":"02","title":"Engineering return time","titleCN":"工程学的回归时间","definition":"the speed with which a system returns to equilibrium after a displacement","definitionCN":"系统被推离后回到平衡的速度","example":"Engineering resilience measures how quickly the lake clears after a storm.","exampleCN":"工程恢复力度量湖泊在风暴后多快恢复清澈。","why":"In engineering, resilience is a stopwatch: the faster the return, the more resilient the system. Ecology later distinguished this from the ability to absorb change at all.","whyCN":"在工程学中，resilience 是秒表：回归越快，系统越有恢复力。生态学后来把它与“能否吸收变化”区分开。"},{"no":"03","title":"Psychological resilience","titleCN":"心理韧性","definition":"the capacity of a person to cope with stress, loss, or adversity and continue functioning","definitionCN":"个人应对压力、丧失或逆境并继续运作的能力","example":"Children's resilience after displacement depended on stable caregivers.","exampleCN":"流离失所后儿童的心理韧性取决于稳定的照护者。","why":"The physical image of springing back is applied to the mind: adversity bends a person, and resilience is the return, not the absence of bending.","whyCN":"弹回的物理意象被用于心理：逆境把人压弯，resilience 是回归，而不是从未被压弯。"},{"no":"04","title":"Material resilience","titleCN":"材料的回弹性","definition":"the ability of a material to return to its original shape after being bent or compressed","definitionCN":"材料被弯曲或压缩后恢复原形的能力","example":"The resilience of the reed fibres makes the mat spring back.","exampleCN":"芦苇纤维的回弹性使垫子能弹回。","why":"This is the oldest literal layer: resiliens described something leaping back, and materials still demonstrate the original image most directly.","whyCN":"这是最古老的字面层：resiliens 描述某物跳回，而材料至今最直接地展示这一原始意象。"},{"no":"05","title":"Community or social resilience","titleCN":"社区或社会韧性","definition":"the capacity of a community to prepare for, respond to, and recover from shocks","definitionCN":"社区准备、应对并从冲击中恢复的能力","example":"Neighbour networks increased the town's resilience to the flood.","exampleCN":"邻里网络提高了小镇对洪水的韧性。","why":"The unit changes from an individual to a community; the 'springing back' now depends on social ties, infrastructure, and institutions.","whyCN":"单位从个人变为社区；“弹回”现在依赖社会纽带、基础设施与制度。"},{"no":"06","title":"Organizational or business resilience","titleCN":"组织或商业韧性","definition":"the capacity of an organization to withstand disruption and continue its core functions","definitionCN":"组织承受中断并继续核心职能的能力","example":"Supply-chain resilience became a board-level concern after the pandemic.","exampleCN":"疫情之后，供应链韧性成为董事会层面的议题。","why":"The collective unit changes again: an organization must keep its core functions when suppliers, staff, or systems fail.","whyCN":"集体单位再次变化：当供应商、员工或系统失效时，组织必须维持核心职能。"},{"no":"07","title":"Resilience contrasted with resistance","titleCN":"恢复力与抵抗力的对照","definition":"the property of recovering after change, as opposed to resisting change in the first place","definitionCN":"变化后恢复的属性，与首先抵抗变化的属性相对","example":"A resistant forest barely changes; a resilient one changes and returns.","exampleCN":"有抵抗力的森林几乎不变；有恢复力的森林会变化然后回归。","why":"The pair divides the labour of stability: resistance refuses the push, resilience accepts it and comes back.","whyCN":"这一对概念分担了稳定性的工作：抵抗力拒绝推力，恢复力接受推力再回来。"},{"no":"08","title":"Resilience as a policy goal","titleCN":"作为政策目标的恢复力","definition":"a desired capacity that governments, insurers, and planners try to measure and increase","definitionCN":"政府、保险机构与规划者试图度量并提升的理想能力","example":"The city plan set a resilience target for heat waves.","exampleCN":"城市规划为热浪设定了韧性目标。","why":"When a concept becomes a target, it is operationalized: indicators, audits, and budgets turn 'springing back' into something to be managed.","whyCN":"当概念成为目标，它就被操作化：指标、审计与预算把“弹回”变成可管理的东西。"}],"etymology":{"intro":{"en":"Resilience comes from Latin resiliens, the present participle of resilire 'to leap back', from re- 'back' + salire 'to leap'. The same salire gives result and assault.","cn":"resilience 来自拉丁语 resiliens，即 resilire「跳回」的现在分词，由 re-「向后」+ salire「跳」构成。同一个 salire 还衍生 result 与 assault。"},"items":[{"era":"LATIN","en":"resilire 'to rebound, recoil, leap back' = re- 'back' + salire 'to leap, jump'. Its participle resiliens is the direct source of the English noun and adjective.","cn":"resilire「弹回、反冲、跳回」= re-「向后」+ salire「跳」。其分词 resiliens 是英语名词与形容词的直接来源。"},{"era":"17C.","en":"English resilience is recorded in the seventeenth century, first for the physical property of springing back.","cn":"英语 resilience 于 17 世纪被记录，最初指物体弹回的物理属性。"},{"era":"19C.","en":"The word extended to character: a resilient person recovers from hardship as a bent rod recovers its shape.","cn":"该词扩展到性格：有韧性的人从困苦中恢复，正如弯曲的杆恢复形状。"},{"era":"20C.","en":"Ecology adopted resilience for the capacity to absorb disturbance; C. S. Holling distinguished it from resistance and from engineering return time.","cn":"生态学采用 resilience 指吸收扰动的能力；Holling 把它与抵抗力和工程回归时间区分开。"},{"era":"MODERN ENGLISH","en":"Modern usage spans materials, psychology, ecology, disaster planning, and business; the noun is usually uncountable.","cn":"现代用法横跨材料、心理学、生态学、灾害规划与商业；该名词通常不可数。"}]},"similar":{"note":{"en":"The first group separates resilience terms, the second compares capacities under stress.","cn":"第一组区分恢复力术语，第二组比较压力下的能力。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"resilient","ipa":"/rɪˈzɪliənt/","tag":"adjective","definition":"having resilience; the adjective describes the bearer, the noun the capacity.","definitionCN":"具有恢复力的；形容词描述承载者，名词描述能力。"},{"word":"resiliency","ipa":"/rɪˈzɪliənsi/","tag":"variant","definition":"an American variant of resilience, chiefly in psychology and policy writing.","definitionCN":"resilience 的美式变体，主要用于心理学与政策写作。"},{"word":"resile","ipa":"/rɪˈzaɪl/","tag":"verb","definition":"to spring back or withdraw, chiefly in legal usage.","definitionCN":"弹回或撤回，主要用于法律语境。"},{"word":"result","ipa":"/rɪˈzʌlt/","tag":"same salire root","definition":"an outcome, literally 'that which springs back'; it shares salire but not the 'recover' sense.","definitionCN":"结果，字面为“弹回之物”；共享 salire，但无“恢复”义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"resistance","ipa":"/rɪˈzɪstəns/","tag":"paired concept","definition":"the capacity to withstand a push without being displaced.","definitionCN":"承受推力而不被推离的能力。"},{"word":"robustness","ipa":"/rəʊˈbʌstnəs/","tag":"engineering","definition":"the ability to keep functioning across a range of conditions.","definitionCN":"在一系列条件下持续运作的能力。"},{"word":"toughness","ipa":"/tʌfnəs/","tag":"materials","definition":"the ability to absorb energy without breaking; it is about not failing, not about returning.","definitionCN":"吸收能量而不破坏的能力；关乎不失效，而非回归。"},{"word":"adaptability","ipa":"/əˌdæptəˈbɪləti/","tag":"change","definition":"the capacity to adjust to new conditions rather than return to old ones.","definitionCN":"调整以适应新条件、而非回到旧状态的能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin leap, standard phrases, and real contrasts.","cn":"正常联想：拉丁语“跳”的意象、标准搭配与真实对比。"},"normal":[{"en":"re- + salire: to leap back. Resilience is the leap back after being bent.","cn":"re- + salire：向后跳。resilience 是被压弯后的那一跳。"},{"en":"Result and assault share salire: one springs back, the other leaps at.","cn":"result 与 assault 共享 salire：一个弹回，一个扑向。"},{"en":"Resistance refuses the push; resilience takes it and returns.","cn":"抵抗力拒绝推力；恢复力接受推力并回归。"},{"en":"Psychological resilience is not 'never bending'; it is bending and coming back.","cn":"心理韧性不是“从不弯曲”，而是弯曲后再回来。"},{"en":"Engineering resilience is measured by return time; ecological resilience by the ability to absorb change.","cn":"工程恢复力以回归时间度量；生态恢复力以吸收变化的能力度量。"}],"abstract":[{"en":"Picture a reed in wind: it bends almost flat, then stands up when the gust passes. That stand-up is resilience.","cn":"想象风中的芦苇：它几乎被压平，阵风过后又立起来。这个“立起来”就是 resilience。"},{"en":"The word always implies a prior disturbance; without a push there is nothing to spring back from.","cn":"这个词总隐含先前的扰动；没有推力，就无所谓弹回。"},{"en":"A system can be resilient and still change: returning to function is not the same as returning to the exact old state.","cn":"系统可以有恢复力却仍发生变化：回到功能不等于回到完全旧状态。"}]},"examples":[{"en":"The reef's resilience declined as water temperatures rose.","cn":"随着水温升高，该礁的恢复力下降。"},{"en":"Community resilience depends on trust as much as on concrete barriers.","cn":"社区韧性既依赖混凝土屏障，也依赖信任。"},{"en":"Engineers measure resilience as the time a network needs to recover.","cn":"工程师把恢复力度量为一个网络恢复所需的时间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瑞贼连斯”——被压弯了还能连着弹回来 → resilience 恢复力、韧性","word":"resilience"},"root":"拉丁语 resilire「跳回」，re-（向后）+ salire（跳）；同根词有 result、assault、salient。","sensesIntro":{"en":"Eight senses of resilience: ecological absorption, engineering return time, psychological coping, material spring-back, community and organizational capacity, the contrast with resistance, and the same capacity used as a policy target.","cn":"resilience 的八个义项：生态吸收、工程回归时间、心理应对、材料回弹、社区与组织能力、与抵抗力的对照，以及作为政策目标的同一能力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bent reed springs upright when the wind stops.","cn":"核心意象：被压弯的芦苇在风停后弹直。"},"chain":["STABLE STATE","PUSH","DEFORMATION","SPRING BACK","FUNCTION RESTORED","SAME OR BETTER"],"branches":[{"senses":"S1","en":"ECOLOGY: the capacity to absorb disturbance and keep the same relationships.","cn":"生态学：吸收扰动并保持原有关系格局的能力。"},{"senses":"S7","en":"CONTRAST: resilience is coming back, resistance is not moving at all.","cn":"对照：恢复力是回到原状，抵抗力是根本不被推动。"},{"senses":"S2","en":"ENGINEERING: the stopwatch version, measured as return time.","cn":"工程学：用秒表计时的版本，以回归时间度量。"},{"senses":"S3 · S4","en":"PERSON AND MATERIAL: minds and fibres both bend and come back.","cn":"人与材料：心理与纤维都会弯曲再回弹。"},{"senses":"S5 · S6 · S8","en":"COLLECTIVE AND POLICY: communities, firms, and governments turn resilience into a target.","cn":"集体与政策：社区、企业与政府把恢复力变成目标。"}]},"affixes":{"intro":{"en":"Resilience is Latin re- + salire plus the noun suffix -ence. English also forms resilient, resile, and the variant resiliency; salire is a bound Latin stem.","cn":"resilience 是拉丁语 re- + salire 加名词后缀 -ence。英语还构成 resilient、resile 与变体 resiliency；salire 是黏着拉丁词干。"},"latinIntro":{"en":"Latin salire 'to leap' yields resilient, resilience, resile, result, assault, and salient; the re- prefix marks a backward direction in the resilient branch.","cn":"拉丁语 salire「跳」衍生 resilient、resilience、resile、result、assault、salient；re- 前缀在 resilient 一支标记向后方向。"},"items":[{"word":"resilience","structure":"re- (back) + salire (leap) + -ence (noun)","meaning":"the capacity to leap back","meaningCN":"跳回的能力（-ence 名词）","example":"The reed bed shows resilience.","exampleCN":"芦苇地表现出恢复力。"},{"word":"resilient","structure":"re- + salire + -ent (adjective)","meaning":"springing back","meaningCN":"弹回的；有韧性的（-ent 形容词）","example":"Resilient crops survive drought.","exampleCN":"有韧性的作物能熬过干旱。"},{"word":"resiliently","structure":"resilient + -ly (adverb)","meaning":"in a recovering manner","meaningCN":"以能恢复的方式","example":"The town recovered resiliently.","exampleCN":"小镇有韧性地恢复了。"},{"word":"resiliency","structure":"resilient + -cy (noun variant)","meaning":"resilience, chiefly American","meaningCN":"恢复力（美式变体）","example":"The report measured resiliency.","exampleCN":"报告测量了韧性。"},{"word":"resile","structure":"re- + salire (verb)","meaning":"to spring back; to withdraw","meaningCN":"弹回；撤回","example":"The contract resiled to earlier terms.","exampleCN":"合同回退到先前条款。"},{"word":"result","structure":"re- + salire via resultare","meaning":"that which springs back; an outcome","meaningCN":"弹回之物；结果","example":"The result followed the cause.","exampleCN":"结果随原因而来。"},{"word":"assault","structure":"ad- (to) + salire (leap)","meaning":"a leaping at; an attack","meaningCN":"扑向；攻击","example":"The storm assaulted the coast.","exampleCN":"风暴猛扑海岸。"},{"word":"salient","structure":"salire + -ent","meaning":"leaping out; prominent","meaningCN":"跃出的；显著的","example":"The salient ridge stands out.","exampleCN":"显著的山脊很突出。"}],"latinEntries":[{"word":"salire","structure":"salire (fourth conjugation)","meaning":"to leap, jump","meaningCN":"跳；跃"},{"word":"resilire","structure":"re- + salire","meaning":"to leap back, rebound","meaningCN":"跳回；弹回"},{"word":"resiliens","structure":"present participle of resilire","meaning":"leaping back","meaningCN":"正在跳回的"},{"word":"resultare","structure":"re- + saltare (frequentative)","meaning":"to spring back","meaningCN":"弹回；反弹"}]}}]);
